window.HIKAM_SEED=[{"id":"m1","text":"لا تعدن عدة لا تثق من نفسك بإنجازها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m2","text":"لا يغرنك المرتقى السهل إذا كان المنحدر وعرا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص3"},{"id":"m3","text":"عواقب الأعمال من جنسها، فالعمل الصالح عاقبة صالحة، والعمل الخبيث عاقبته خبيثة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m4","text":"اللهم إنا نعوذ بك من بلاء ليس معه ثواب، ونسألك عافية معها ثواب.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص3"},{"id":"m5","text":"اللهم إنا نعوذ بك من فقر ليس معه صبر، ونسألك غنى معه شكر.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص3"},{"id":"m6","text":"الخضاب شاهد زور.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص3"},{"id":"m7","text":"إذا كان الكثير كرما، كان الأكثر منه إسرافا، والأقل منه بخلا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص3"},{"id":"m8","text":"من كانت حوائج الناس إليه، فهي نعمة من الله عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص3"},{"id":"m9","text":"أفضل المال ما أكسب أجرا، وقهر فقرا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص3"},{"id":"m10","text":"أكرم الناس من أعطى من لا يرجوه، وأنال قبل السؤال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m11","text":"قال محتضر : الرجوع إلى من يرجى عفوه، ويطمع في خيره، خير من البقاء مع من لا يؤمن شره، ولا يرجى عفوه.","kind":"hikma","topic":"الإيمان والعبادة","note":"«محتضر» ترجيح من «حمتض» في المصدر","source":"شذرات المطوع، ص3"},{"id":"m12","text":"من شاب شعره فقد مات بعضه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص3"},{"id":"m13","text":"من أكثر من استماع الحكمة أوشك أن ينطق بها.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص3"},{"id":"m14","text":"أربعة لا يستحي من خدمتهم : السلطان والوالد والضيف والدابة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص3"},{"id":"m15","text":"إذا جعلك الأمير من خواصه فلا تكثر الملق والدعاء، وعظمه ووقره عند الناس.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص3"},{"id":"m16","text":"رب كلمة تقول لقائلها : دعني.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص3"},{"id":"m17","text":"العصبية : أن يرى الرجل شرار قومه خيرا من خيار قوم آخرين. وأن يرى باطل قومه أحق من حق قوم آخرين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص3"},{"id":"m18","text":"من محاسن النوم أن فيه إعراض عن الأعراض.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص3"},{"id":"m19","text":"لعل الفرج قريب وأنت لا تدري.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص4"},{"id":"m20","text":"من أساء إليك فقد مكنك من لذة الذم والغيبة، ومن أحسن إليك فقد حرمك لذة الذم ومزمزة الغيبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m21","text":"إذا زرت البخيل أعانك على الذم، وإذا زرت الكريم حرمك لذة الذم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m22","text":"ناموس المشايخ قلة المزح وكثرة الصمت، وناموس الشباب كثرة المزح وقلة الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص4"},{"id":"m23","text":"نسبة الصواب إلى قائله أحمد من التفرد بالادعاء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m24","text":"من لم يسخط نفسه في شهوته، لم يرض ربه في طاعته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص4"},{"id":"m25","text":"لو اطلع ابن آدم على ما بقي من أجله، لزهد في طول ما يرجو من أمله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص4"},{"id":"m26","text":"هب المسيء قد عفي عنه، أليس قد فاته ثواب المحسنين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m27","text":"رفاهة العيش ومحبة النساء والأولاد توهي العزم، وتكسر حمية الشجاعة، وتحبب السلامة، وتباعد من ركوب المخاطر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص4"},{"id":"m28","text":"ليس مع الاستئثار محبة، ولا مع المواساة بغضة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص4"},{"id":"m29","text":"الملك الذي يطلب طاعة رعيته بالإحسان والمودة، أحمد عاقبة وأفضل عافية من الذي يطلبها بالقهر والاستطالة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص4"},{"id":"m30","text":"إذا غضبت على من تعاطى ما يغضبك، فاجعل بين غضبك ورضاك مدة بقدر ما تردعه عن تعاطي ما يغضبك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m31","text":"لو أن أحدا قليل العلم عمل بعلمه لكان جديرا بالنجاة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m32","text":"لو أن أحدا كثير العلم لم يعمل بعلمه لكان جديرا بالهلاك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص4"},{"id":"m33","text":"تعودوا الخير فإنما الخير عادة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص4"},{"id":"m34","text":"السحاب فحل الأرض.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص5"},{"id":"m35","text":"إذا كان لك أكثري فتجاف عن أقلي.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص5"},{"id":"m36","text":"الدرهم يزرع، والسيف يحصد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m37","text":"إن لم ترهب فأرغب.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m38","text":"اشبع من تخشاه فإن لم تشبعه أكلك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص5"},{"id":"m39","text":"استدم النعم بالشكر، والمقدرة بالعفو، والطاعة بالتألف، والنصر بالتواضع، والرحمة بالرحمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص5"},{"id":"m40","text":"اطلب الرحمة بالرحمة، والستر بالستر، وتفريج الكرب بتفريج الكرب، والتجاوز بالتجاوز، والسماح بالسماح، والرفق بالرفق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص5"},{"id":"m41","text":"اطلب كل شيء من الله تعالى بأن تعمل مثله مع عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m42","text":"إذا أردت أن يكون الله سبحانه معك كما تريد، فعامل عباده كما يريد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m43","text":"ما تريده من الله تعالى اطلبه بأن تفعله مع عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m44","text":"إذا وضحت الحجة ثقل استماع المنازعة فيها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص5"},{"id":"m45","text":"أول طريق الحكمة اتهام الرأي، واحتقار النفس، ومعوقاتها الإعجاب بالرأي وتعظيم النفس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص5"},{"id":"m46","text":"أقدار الله تعالى تأتي على كل حال : فقير يستغني، وغني يفتقر، وشيخ يعمر، وطفل يموت، وطبيب يهلك، ومريض يعيش، فلا تأمن في أي حال.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m47","text":"الطاعات تخفف من كربة الموت، والمعاصي تزيدها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m48","text":"من اشتغل بالطاعات أحب لقاء الله فخف عليه مجيء الأجل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص5"},{"id":"m49","text":"من اشتغل بمعاصي الله كره لقاء الله، فثقل عليه مجيء الأجل.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m50","text":"المبادرة في إثابة المحسن تعدل التثبت في عقوبة المسيء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m51","text":"إذا عم الشر فخير الناس النومة ( الخامل ).","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m52","text":"استرجع شارد النعمة بالتوبة والاستغفار، واستدم راهنها بالشكر وكرم الجوار.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m53","text":"الشكر يزرع، والكفر يحصد.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m54","text":"من أطعمه التراب أكله التراب.","kind":"hikma","topic":"المال والاقتصاد","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m55","text":"من كثر جده ثقل، ومن كثر هزله رذل، وليكن مقدار المزاح في الكلام، مقدار الملح في الطعام.","kind":"hikma","topic":"الكلام والصمت","note":"في المصدر «هزل» بلا هاء؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m56","text":"آفة الأمن التفريط، وثمرة الخوف الحزم.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m57","text":"حاجة الحكيم إلى السفه حاجة العجين إلى الملح.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m58","text":"حاجة الحليم إلى الغضب حاجة الدواء إلى السم.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m59","text":"الذي يقرأ القرآن إنما يحدث عن ربه.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m60","text":"على ألافها الطير تقع.","kind":"mathal","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m61","text":"الذكر صابون القلوب، والاستغفار صابون الذنوب.","kind":"hikma","topic":"الإيمان والعبادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m62","text":"السفر يعطل العادات، ويكسب المستجدات.","kind":"hikma","topic":"الحياة والزمن","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m63","text":"من بادر بالإنكار مخطئا وهو لا يعلم، أعذر ممن بادر بالإقرار مصيبا وهو لا يعلم.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m64","text":"الإقرار بعد الإنكار أيسر من الإنكار بعد الإقرار.","kind":"hikma","topic":"الكلام والصمت","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m65","text":"من سلب نعمة غيره، سلب غيره نعمته.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m66","text":"مريض يشتهي أرجى من مريض لا يشتهي.","kind":"mathal","topic":"الصحة والنفس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m67","text":"عدل السلطان صلاح العمران.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m68","text":"جور السلطان خراب العمران.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m69","text":"إصلاح الموجود مقدم على انتظار المفقود.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m70","text":"غاية الاحتمال تمكين الفرصة.","kind":"hikma","topic":"الصبر والشدائد","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m71","text":"العمل يحتاج إلى الإرادة، والإرادة تحتاج إلى العلم، والعلم يحتاج إلى العقل، والعقل يحتاج إلى التجارب، والتجارب لا تتم إلا بمزاولة العمل، إذا العمل يحتاج إلى العمل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m72","text":"تجويد العمل لا يتم إلا بكثرة مزاولة العمل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m73","text":"غاية الاستمرار بالعمل كثرة الجودة والمهارة، وقلة الوقت والمجهود.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m74","text":"مشقة العمل بالمكابدة والمقاومة تقل وتخف، وبالتواني والتراخي تزيد وتثقل.","kind":"hikma","topic":"النجاح والإبداع","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m75","text":"ضرب الوالد للولد كضرب المنجد للقطن، يضربه لإصلاحه وتجديده.","kind":"hikma","topic":"التربية والأسرة","note":"في المصدر «كضب» و«بضبه»؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m76","text":"الستر رداء الرذائل، والإخلاص رداء الفضائل.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m77","text":"ما نجا مجاهر، ولا هلك مستور.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m78","text":"الرذيلة المستورة كالفضيلة المنشورة.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m79","text":"ستر المثالب خير من نشر المناقب.","kind":"hikma","topic":"الأخلاق والآداب","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m80","text":"مقاربة العامة بلين الكلام، وخفض الجناح، وسكون الطائر.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m81","text":"مقاربة الخاصة ببسط اليد، ورفع الحجاب، وطلاقة الوجه.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m82","text":"لتمزيق عرض البخيل حلاوة لا توجد في مدح الكريم.","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m83","text":"اللهم إنا من فضلك، نسألك بفضلك، من فضلك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m84","text":"في الاغتراب يزيد الاقتراب، فابن البلد كابن الولد.","kind":"hikma","topic":"العلاقات والناس","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m85","text":"قبل أن تحسو ذق.","kind":"mathal","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m86","text":"العقل صديق لا يطاع، والهوى عدو يطاع.","kind":"hikma","topic":"العقل والحكمة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m87","text":"الرعية تنقاد للحاكم والأمراء، والحاكم والأمراء ينقادون لأهل الرأي والعقلاء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m88","text":"أهل الرأي والعلم يحكمون على الناس، بواسطة الأمراء والكبراء.","kind":"hikma","topic":"السياسة والقيادة","note":"الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)","source":"شذرات المطوع"},{"id":"m89","text":"قبح الخطأ أظهر جمال الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m90","text":"سمعنا من يبرئ الأكمه والأبرص، وما سمعنا من يبرئ الأحمق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m91","text":"من يعلم أنه جاهل أفضل ممن يجهل أنه جاهل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m92","text":"الجاهل الذي لا يجهل أنه جاهل أفضل من الجاهل الذي يجهل أنه جاهل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m93","text":"من لا يعلم ويعلم أنه لا يعلم خير ممن لا يعلم ولا يعلم أنه لا يعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص8"},{"id":"m94","text":"الأحمق المتعاقل كالجاهل المتعالم، والشيخ المتصابي كالصبي المتشايخ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m95","text":"إن المستشير معان فهو بين صواب يفوز بثمرته، وخطأ يشارك في مكروهه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m96","text":"لا تستشر بخيلا فيحسن لك البخل، ولا مبذرا فيحسن لك التبذير، ولا جبانا فيحسن لك الجبن، ولا متهورا فيحسن لك التهور، ولكن استشر عالما مستقيم الرأي، مجربا خبيرا بما تستشيره به.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m97","text":"المستشار ليس بضامن، والرأي ليس بمضمون.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m98","text":"من استخار ربه، وشاور نصيحه، واجتهد رأيه، فقد أدى ما عليه، ويقضي الله تعالى ما يشاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص8"},{"id":"m99","text":"ليردعك عن الناس ما تعرف من نفسك، ولا تجد عليهم فيما تأتي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص8"},{"id":"m100","text":"لا عقل كالتدبير، ولا ورع كالكف.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص8"},{"id":"m101","text":"آفة النصيحة الفضيحة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص8"},{"id":"m102","text":"لا تحتقر شرا فإن قليله كثير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m103","text":"أميطوا عن النصيحة قبح العلانية، وزينوها بالستر.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص9"},{"id":"m104","text":"اتق الأنس بالسلطان، إن رفع عنك الاحتشام، فزده من الإعظام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m105","text":"كلما زادك السلطان بسطا فزده هيبة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m106","text":"من شغلته حلاوة الدنيا فاجأته مرارة الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m107","text":"من صبر على مرارة الدنيا نال حلاوة الآخرة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m108","text":"لن تدرك ما تحب إلا بالصبر على ما تكره.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m109","text":"لن تنال حلاوة الشفاء إلا بتجرع مرارة الدواء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص9"},{"id":"m110","text":"ذكر الله والاستعانة به عند القيام وعند القعود هون علي ضعف الشيخوخة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m111","text":"الشيخ أقوى من الشاب، لأن الشاب ينهض بحوله، والشيخ ينهض بحول الله.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المصدر «بحول» بلا هاء","source":"شذرات المطوع، ص9"},{"id":"m112","text":"الضعيف أقوى من القوي، لأن الضعيف يعتمد على الله، والقوي يعتمد على قوته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m113","text":"ثمن الحكمة حسن الاستماع.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص9"},{"id":"m114","text":"لا تصغر أمر من حاربت أو عاديت، فإنك إذا ظفرت لم تحمد، وإذا عجزت لم تعذر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص9"},{"id":"m115","text":"قال كريم : لأن أخطئ باذلا أحب إلي من أن أصيب باخلا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص9"},{"id":"m116","text":"احذروا دمعة اليتيم، ودعوة المظلوم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m117","text":"لو كان للذنوب رائحة لما طاب ريح أحد، ولما جلس أحد إلى أحد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m118","text":"من طلب حاجة إلى غير صديقه فقد شانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص9"},{"id":"m119","text":"طرحنا الحشمة فيما بيننا وبين حفظتنا طرح من لا يؤمن أنهم معه يعلمون ما يقول ويفعل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص9"},{"id":"m120","text":"من عير أخاه بذنب قد تاب منه ابتلاه الله به.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m121","text":"احذر صولة الانهماك، في بغضك وهواك، فإنها تؤدي إلى الهلاك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص9"},{"id":"m122","text":"رب مكروه أنفع من محبوب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m123","text":"اللهم ارزقنا من الخير أكثر مما نرجو، واصرف عنا من الشر أكثر مما نخاف.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص10"},{"id":"m124","text":"الأسى على الفائت تضييع وقت ثان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m125","text":"لا تسبوا الغوغاء، فإنهم يطفئون الحريق، ويخرجون الغريق، ويسدون البثوق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص10"},{"id":"m126","text":"لن تنال ما تهوى إلا بترك ما تشتهي.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m127","text":"كن حلو الصبر عند مر النازلة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص10"},{"id":"m128","text":"عذر جميل خير من مطل طويل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص10"},{"id":"m129","text":"أمارات الوجه : الصفرة للفرق، والحمرة للخجل، والإشراق للسرور، والكمد للحزن، والسكون للبراءة، والاضطراب للريبة، وجحوظ العين للإنكار، وغورها للقبول، وترددها في الجانبين للمكر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m130","text":"مثل الذي يوصي مثل الذي يهدي إذا شبع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص10"},{"id":"m131","text":"حسن الخلق نصف الدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص10"},{"id":"m132","text":"من أرجأ غداءه خسر عشاءه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m133","text":"من بكر بغدائه استلذ بعشائه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص10"},{"id":"m134","text":"إذا كان المكروه ممن فوقك كان حزنا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m135","text":"وإذا كان المكروه ممن دونك كان غضبا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص10"},{"id":"m136","text":"الثناء بعد البلاء، والاختيار بعد الاختبار، والشهادة بالإحسان بعد الامتحان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص11"},{"id":"m137","text":"إذا زللت فارجع، وإذا ندمت فأقلع، وإذا أسأت فاندم، وإذا منيت فاكتم، وإذا قريت فأفضل، وإذا منعت فأجمل.","kind":"hikma","topic":"الأخلاق والآداب","note":"«منيت» كما في المصدر، ولعلها «مننت»","source":"شذرات المطوع، ص11"},{"id":"m138","text":"اللهم إن كنا عصيناك فقد تركنا من معاصيك أبغضها إليك، وهو الإشراك بك، وإن كنا قصرنا في طاعتك، فقد تمسكنا بأحبها إليك توحيدك والإيمان برسولك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص11"},{"id":"m139","text":"هدية الأحياء إلى الأموات الدعاء والاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m140","text":"الموت تحفة المؤمن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m141","text":"الكريم يرى حق اللفظة، وحرمة اللحظة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m142","text":"لا تعص الله اليوم لخوف الغد، ولا العام لخوف القابل، واستعن بتقوى الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص11"},{"id":"m143","text":"نعم الصديق من يغفر الزلل، ويسد الخلل، ويقبل العلل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص11"},{"id":"m144","text":"آفة الحزم ترك الاستعداد، وآفة الرأي سوء الاستبداد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m145","text":"لذة العفو أطيب من لذة التشفي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m146","text":"عاقبة العفو محمودة، وعاقبة التشفي مذمومة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص11"},{"id":"m147","text":"الحلم قرين العقل، والسؤال مفتاح التثبت، وفي المشورة وضوح الرأي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m148","text":"أخطأ من ظن أن ابن آدم لا يخطئ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص11"},{"id":"m149","text":"من قال : لا أعلم، فقد علم أنه لا يعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص11"},{"id":"m150","text":"أوثق ما توصلت إليه من العلم وأصدقه، علمي بأني لا أعلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص11"},{"id":"m151","text":"من الأجدى على العليل أن يداوى بعشبة أرضه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص12"},{"id":"m152","text":"لو قنع الناس بأرزاقهم كقناعتهم بأوطانهم، ما اشتكى عبد رزقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m153","text":"من لم يؤدب في صغره لم يفلح في كبره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص12"},{"id":"m154","text":"المساجد سوق الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m155","text":"الكريم يذكر إذا وعد، وينسى إذا أوعد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص12"},{"id":"m156","text":"الهدية السحر الحلال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m157","text":"التعاون على البر وسيلة لاتفاق الآراء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m158","text":"اتفاق الآراء وسيلة لتحقيق المراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص12"},{"id":"m159","text":"خير الناس للناس، أنفع الناس للناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m160","text":"شر الناس للناس، أضر الناس للناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص12"},{"id":"m161","text":"من عجز عن تقويم نفسه، فهو عن تقويم غيره أعجز.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص12"},{"id":"m162","text":"عدم التصديق بقول غيرك إخبار عن نفسك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m163","text":"التكذيب بقول غيرك حكم على غيرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m164","text":"التصديق بقول غيرك لا يلزمك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m165","text":"التكذيب بقول غيرك من غير بينة ظلم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m166","text":"التصديق بقول غيرك من غير بينة غفلة وسذاجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص12"},{"id":"m167","text":"لا تملي على حافظيك شرا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m168","text":"لا تسقط الكلفة بينك وبين حافظيك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص12"},{"id":"m169","text":"من ذهب ماله هان على أهله.","kind":"hikma","topic":"المال والاقتصاد","note":"في المصدر «مال» بلا هاء","source":"شذرات المطوع، ص12"},{"id":"m170","text":"من استغنى كرم على أهله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m171","text":"سوط الفقر موجع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m172","text":"من ابتلي بالفقر، ولم يتزين بالعفاف، وتنكب طريق الحلال، فقد جمع على نفسه فقرين : فقر الدنيا وفقر الآخرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص12"},{"id":"m173","text":"كثرة مال المتوفى شطر التعزية.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m174","text":"حذق المرء وذكاؤه محسوب عليه من رزقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m175","text":"من فوائد المال : يقرب الأصدقاء ويغيظ الأعداء، ويجلب الرخاء، ويدفع البلاء، ويدني الإخوان، ويطرد الأحزان، ويحقق رجاء المؤمل، ويصلح حال القاصد، ويقضي به الدين، ويوصل به الرحم، ويسترضي به الكاشح، ويصان به الوجه، ويعين على المروءة، ومكارم الأخلاق، وتنفس به الكربة، ويغاث به اللهفان، وييسر به على المعسر، وبه تكسب المحامد، وتضاعف الحسنات، وتدرك الدرجات، وفيه مهر الكريمة، ورقوء الدم، وهو مادة السخاء، وعمود الجود، فالمال فيه خير الدنيا والآخرة، لمن وفقه الله في جمعه وإنفاقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص13"},{"id":"m176","text":"سافروا تغنموا.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص13"},{"id":"m177","text":"لو يعلم المسافر ما له عند الله من الرحمة لما أحب أن يقطع سفره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص13"},{"id":"m178","text":"الحركة ولود، والسكون عاقر.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص13"},{"id":"m179","text":"ليس الناس بشيء من أقسامهم أقنع منهم بأوطانهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m180","text":"من أدناه الأمير من نفسه فقد جعله شافعا عنده، وذريعة لقضاء حوائج الناس لديه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص13"},{"id":"m181","text":"إذا منعت فاعذر وقل لم أوافق قدرا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m182","text":"إذا سألت الأمير أو الكريم فعاوده فإن الله يقلب القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m183","text":"إذا ردك الكريم فلا تيأس فإن طباع الجود أولى به.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص13"},{"id":"m184","text":"الأجل آفة الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص13"},{"id":"m185","text":"زكاة الجاه أن تنصر به مظلوما، أو تنفس به عن مكروب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m186","text":"من المعروف أن تعين بجاهك من لا جاه له.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m187","text":"الخلق عيال الله، فأحبهم إلى الله أنفعهم لعياله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m188","text":"إذا سألت شريفا فاستعن عليه بشرفه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m189","text":"زكاة الجاه رفد المستعين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m190","text":"الدعاء إحدى الصدقتين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m191","text":"لؤم الاكتساب يمنع من الانتساب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m192","text":"الثناء بأكثر من الاستحقاق ملق، والتقصير عن الاستحقاق عي أو حسد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص15"},{"id":"m193","text":"لا تعاجل الذنب بالعقوبة، واجعل بينهما للاعتذار طريقا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص15"},{"id":"m194","text":"اللهم إن رجاءنا بعفوك أعظم من ذنوبنا، وجودك بعفوك أعظم من رجائنا، فاغفر بعظيم عفوك عظيم ذنوبنا، فإنه لا يغفر الذنب العظيم إلا الرب العظيم.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص15"},{"id":"m195","text":"المصائب مفاتيح الأجر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص15"},{"id":"m196","text":"المصيبة مع الجزع مصيبتان.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص15"},{"id":"m197","text":"من أتاه المكروه ممن فوقه أثار حزنا، ومن أتاه المكروه ممن دونه هيج غضبا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص15"},{"id":"m198","text":"إذا استأثر الله بشيء فاله عنه.","kind":"mathal","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص15"},{"id":"m199","text":"المودة قرابة مستجدة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m200","text":"صاحب من ينسى معروفه عندك، ويتذكر حقوقك عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m201","text":"تقاربوا في المودة، ولا تتكلوا على القرابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m202","text":"القرابة توجب المودة ولا توجدها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص15"},{"id":"m203","text":"الأقلام مطايا الكلام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص15"},{"id":"m204","text":"الخط للقريب والبعيد، واللفظ للقريب فقط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m205","text":"الخط للشاهد والغائب، واللفظ للشاهد فقط.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m206","text":"ما تساب اثنان إلا غلب ألأمهما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m207","text":"ذاكر غائبا تره.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m208","text":"إذا لم تسمع فألمع. ( فأشر )","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص16"},{"id":"m209","text":"من أحسن إلى أحد فبنفسه بدأ، ومن أساء على أحد فبنفسه بدأ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m210","text":"لقاء الأحبة مسلاة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m211","text":"الأدب رفعة، والرفعة يمن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m212","text":"الجود رداء العيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m213","text":"الأدب حلة زاهية الألوان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m214","text":"العلم ثوب الوقار.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص16"},{"id":"m215","text":"التقوى رداء الورع.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص16"},{"id":"m216","text":"الصحة ثوب الجمال.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص16"},{"id":"m217","text":"الغنى قميص العز.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص16"},{"id":"m218","text":"أملِ على الناس ما تحب أن يذكروك به بعد حياتك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص16"},{"id":"m219","text":"أملِ على جليسك ما تحب أن يذكرك به بعد غيابك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m220","text":"أملِ على أولادك ما تحب أن يذكروك به بعد رحيلك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص16"},{"id":"m221","text":"أعني على شكرك بالإحسان إلي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m222","text":"أعني على الإحسان إليك بشكرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص16"},{"id":"m223","text":"اقطع لسان الذم عنك بالإحسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m224","text":"حرك لسانه بالثناء عليك بالإحسان إليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m225","text":"حب الناس لك في يدك : إن أحسنت إليهم أحبوك، وإن أسأت إليهم أبغضوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m226","text":"نماء الحب بالإحسان، ونماء البغض بالإساءة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m227","text":"اقتلع البغضاء من قلوب الناس بالإحسان إليهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m228","text":"لا تطلب من الناس أن يحبوك، ولكن أحسن إليهم فيحبوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m229","text":"لا تطلب من الناس ألا يكرهوك، ولكن أحسن إليهم فيحبوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m230","text":"تعلم من الكريم أن تكون كريما، وتعلم من البخيل ألا تكون بخيلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m231","text":"تعلم من الأمين أن تكون أمينا، وتعلم من الخائن ألا تكون خائنا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m232","text":"تعلم من أهل الخير الخير، وتعلم من أهل الشر الخير، بأن لا تكون مثلهم، فإذا فعلت فأنت الرجل الكامل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص17"},{"id":"m233","text":"لا تطلب العلم بالجهل، فلا تقصد العالم في غير وقته، ولا تتخطى إليه الرقاب، ولا تتعنت في السؤال، ولا تقل له قال فلان غير قولك، لا تذم عنده العلماء، ولا تغتب عنده أحدا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m234","text":"كتاب الرجل أمارة علمه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m235","text":"من قرأ كتابا فقد جالس مؤلفه من غير كلفة واحتشام.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص17"},{"id":"m236","text":"تغاب عما لا يتضح لك من أخيك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص17"},{"id":"m237","text":"من نم لك نم عليك، وأصدقهم أخبثهم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص17"},{"id":"m238","text":"أردع النمام بقولك : أتحب أن نقبل منك ما قلت فيه، على أن نقبل منه ما يقول فيك ؟","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص17"},{"id":"m239","text":"الغموم التي تعرض للقلوب كفارات للذنوب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص17"},{"id":"m240","text":"السرور في الدنيا ربح، لأن مبناها على الغموم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص17"},{"id":"m241","text":"إذا اشتد الغم انقطع الدمع.","kind":"hikma","topic":"الصحة والنفس","note":"سبقها في المصدر رقم «71» وهو رقم الصفحة 17 معكوسا","source":"شذرات المطوع، ص18"},{"id":"m242","text":"الحزن يبلى كما يبلى الثوب، ولو بقي الحزن على أحد لقتله.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص18"},{"id":"m243","text":"المؤمن أكثر هما، لأنه يكابد هم المعاش، وهم المعاد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m244","text":"ثلاثة أشياء ترد القضاء البكاء والاستغفار والدعاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m245","text":"ليس الخائف الذي يبكي، إنما الخائف الذي يترك ما يخاف أن يعاقبه الله عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m246","text":"إن أحبكم إلينا قبل أن نراكم أحسنكم اسما، فإذا رأيناكم فأحسنكم سمتا، فإذا تكلمتم فأحسنكم منطقا، فإذا عملتم فأحسنكم عملا، وسرائركم بينكم وبين الله تعالى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m247","text":"الحق الذي لا يقبل من قائله، مدحه نفسه بالحق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص18"},{"id":"m248","text":"الصدق الذي لا يقبل، ثناء المرء على نفسه بما هو أهله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص18"},{"id":"m249","text":"عجب الشكر مأمور به، كأن يعظم الإنسان نعم الله عليه، ويحدث بها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m250","text":"عجب الكبر منهي عنه، كأن يفتخر الإنسان بما حققه وجمعه ويستطيل به.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m251","text":"جهر النبي بعجب الشكر، وأسقط استطالة الكبر، فقال : ( أنا سيد ولد آدم ولا فخر ).","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص18"},{"id":"m252","text":"لله دره، أي علم بين جنبيه، وأي لسان بين فكيه، وأي يقين بين ضلوعه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص18"},{"id":"m253","text":"لو لم يصف الطبيب منافع دوائه للمتعالجين لما قصده طالب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص18"},{"id":"m254","text":"نظر عمر بن العزيز إلى علوي يمشي مشية منكرة، فقال : يا هذا، إن الذي شرفت به لم تكن هذه مشيته.","kind":"hikma","topic":"الأخلاق والآداب","note":"كذا في المصدر، ولعله: عمر بن عبد العزيز","source":"شذرات المطوع، ص18"},{"id":"m255","text":"من تكبر على من دونه، ذل لمن فوقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص18"},{"id":"m256","text":"من تواضع لمن دونه، لم يذل لمن فوقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص19"},{"id":"m257","text":"لو أن العالم كلما قال أصاب، وكلما عمل أحسن، أوشك أن يعجب بنفسه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص19"},{"id":"m258","text":"ثمرة المشاورة الصواب، وثمرة الهدايا المحبة، وثمرة الكبر المقت.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m259","text":"لا تلعن إبليس في العلانية، وتصادقه في السر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص19"},{"id":"m260","text":"رب بعيد أقرب من قريب في نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص19"},{"id":"m261","text":"رب قريب أبعد من بعيد في عدم نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص19"},{"id":"m262","text":"إذا غلب العقل الهوى صرف المساوئ إلى محاسن، فجعل البلادة حلما، والحدة ذكاء، والمكر فطنة، والهذر بلاغة، والعي صمتا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m263","text":"شاور من جرب، فإنه يمنحك صواب رأيه الذي بلغه بالمعاناة وأنت تأخذه وأنت وادع.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m264","text":"حاجة العقل إلى التجربة حاجة العلم إلى المذاكرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m265","text":"استخراج الرأي الجليل كاستخراج اللؤلؤ الثمين، بعد الجهد والمعاناة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m266","text":"يقول الغزال للكلب لن تلحقني، قال : لم ؟ قال : لأني أعدو لنفسي، وأنت تعدو لصاحبك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص19"},{"id":"m267","text":"من حرص على الرياسة لم يسلم من الحسد والبغي والطغيان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص19"},{"id":"m268","text":"لا تحدث بالحكمة إلا لمن ألقى إليك السمع وهو شهيد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص19"},{"id":"m269","text":"ثمن الحكمة طلبها، فمن طلبها فقد دفع ثمنها، فاستحق أن يسمعها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص20"},{"id":"m270","text":"أجرأ الناس على الفتيا أقلهم علما باختلاف العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m271","text":"اختلاف العلماء يردع عن التسارع في الفتيا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m272","text":"من أراد أن يأكل الخبز بالعلم لا يوثق بعلمه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m273","text":"مجالسة العلماء تجلي القلوب.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m274","text":"من أراد أن يصقل قلبه ويذهب بصدأه، فعليه بمجالسة العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m275","text":"من اتخذ علم الدين تجارة فلا أربح الله تجارته.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m276","text":"أدنى العلم ما كان على اللسان، وأرفعه ما كان في الجنان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m277","text":"علم اللسان لا يجاوز البيان، وعلم الجنان يظهر على الجوارح والأركان.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m278","text":"بالعلم يشرف الوضيع، ويعز الذليل، ويناطح الصغير الكبير، ويمكن الضعيف من مخاطبة القوي بمثل قول « أحطت بما لم تحط به ».","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m279","text":"أشتهي أن أرى عالما زاهدا أو زاهدا عالما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m280","text":"ما أكثر الشجر، وليس كلها بمثمر، وما أكثر الثمار، وليس كلها بمطعوم، وما أكثر المطعوم، وليس كله بمشتهى، وما أكثر المشتهى، وليس كله بمقدور عليه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص20"},{"id":"m281","text":"ما أقل العلماء، وليس كلهم بعاملين، وما أقل العاملين، وليس كلهم بزاهدين، وما أقل الزاهدين، وليس كلهم بمخلصين.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m282","text":"خذ من كل علم بطرف، فإن من جهل شيئا عاداه، ومن عادى علما فقد حقر نفسه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص20"},{"id":"m283","text":"إن الله تعالى ذم الذين يطلبون العلم بالجهل، فقال : « إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون ».","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص21"},{"id":"m284","text":"لا تصحبن عاقا، فإنه لن يصلك وقد عق والديه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m285","text":"لا تتوخى الإحسان من قاطع رحم، فإنه لن يحسن إليك وقد قطع رحمه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m286","text":"استكثروا من العيال، فإنكم لا تدرون بمن ترزقون.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص21"},{"id":"m287","text":"صاحب العيال أعظم أجرا، والفار من عياله كالعبد الآبق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص21"},{"id":"m288","text":"النعمة تقول : كفرت، والأمانة تقول : أكلت، والرحم تقول : قطعت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص21"},{"id":"m289","text":"أمران يشوبها الكذب : المواعيد والاعتذار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص21"},{"id":"m290","text":"شر الناس المثلث، الذي يسعى بصاحبه إلى سلطانه، فيهلك نفسه وصاحبه وسلطانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص21"},{"id":"m291","text":"صاحب الدرهمين أشد حسابا يوم القيامة من صاحب الدرهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m292","text":"من ولد في الفقر أبطره الغنى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m293","text":"من ولد في الغنى لم تزده النعمة إلا تواضعا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m294","text":"الفقر والذكر شعار الصالحين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m295","text":"الغنى والغفلة شعار المنافقين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m296","text":"أشقى الأشقياء من جمع عليه فقر الدنيا وعذاب الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص21"},{"id":"m297","text":"بئس المذلان : الفقر والجهل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m298","text":"نعم المعزان : الغنى والعلم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m299","text":"من حفظ ماله فقد حفظ الأكرمين : دينه وعرضه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m300","text":"المال عز للمؤمن، يصون به وجهه عن ذل السؤال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص21"},{"id":"m301","text":"المال سلاح المؤمن يقي به دينه وشرفه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص22"},{"id":"m302","text":"من كان له مال فليصلحه وينميه ليكون به اليد العليا، ولا يكون اليد السفلى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص22"},{"id":"m303","text":"قال محتضر : ما أكره أن يذهب بي إلى من لم أر الخير إلا منه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m304","text":"إن الموت قد أفسد على أهل النعيم نعيمهم، فالتمسوا نعيما لا موت فيه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص22"},{"id":"m305","text":"اشتر نفسك من الله تعالى ببعض ما وهبك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m306","text":"أشقى الولاة من شقيت به رعيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m307","text":"جور السلطان خير من ضعفه، لأن جوره يخص، وأما ضعفه فيتواثب الناس فيتفشى الشر والظلم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m308","text":"من شارك السلطان الظالم في عز الدنيا، شاركه في ذل الآخرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m309","text":"من تأدب وجد بغيته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص22"},{"id":"m310","text":"ذكر عمر أزرى بالولاة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص22"},{"id":"m311","text":"ذاكر الله في الغافلين، كالشجرة الخضراء في وسط الأشجار اليابسة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m312","text":"ذاكر الله في الغافلين كالمقاتل المقبل بين المدبرين الفارين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص22"},{"id":"m313","text":"لا تحقرن أحدا من المسلمين، فإن صغيرهم عند الله كبير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m314","text":"إن لم تجد حكيما ترسله فكن رسول نفسك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص22"},{"id":"m315","text":"ربما كان التقالي من كثرة التلاقي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m316","text":"الإكثار ممل، والإقلال مخل.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m317","text":"بالبشر والبر تقبل عليك قلوب الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص22"},{"id":"m318","text":"أجلس علي الحسن والحسين على سريره، وأجلس محمد بن الحنفية في الحضيض وقال : يا بني أنت ابني، وهذان ابنا رسول الله.","kind":"hikma","topic":"التربية والأسرة","note":"«أجلس علي» أي علي بن أبي طالب","source":"شذرات المطوع، ص22"},{"id":"m319","text":"أطعمنا من أحاديثك الطريفة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m320","text":"أطعم آذاننا من أحاديثك الشيقة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص22"},{"id":"m321","text":"ابن الثمانين حبيس الله.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص22"},{"id":"m322","text":"من بلغ الثمانين فهو أسير الله في أرضه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص23"},{"id":"m323","text":"قيل لحكيم مالك تمسك العصا، ولست بمريض ولا كبير ؟ قال : لأرى أني مسافر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص23"},{"id":"m324","text":"خير شبابكم من تشبه بكهولكم، وليس خير كهولكم من تشبه بشبابكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص23"},{"id":"m325","text":"صحبة الأخيار تورث حسن الظن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m326","text":"صحبة الأشرار تورث سوء الظن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m327","text":"نية المؤمن خير من عمله، وعمله لا يبلغ نيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص23"},{"id":"m328","text":"نية المنافق شر من عمله، وعمله لا يبلغ نيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص23"},{"id":"m329","text":"شح البخيل على قدر ماله، فكلما زاد ماله زاد شحه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m330","text":"كرم الجواد على قدر ماله، فكلما زاد ماله زاد كرمه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m331","text":"أتوسل إليك بك، واستشفع بك عندك، ليجتمع شكري لك، ولا يتفرق على غيرك.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص23"},{"id":"m332","text":"صلاح ذات البين تعمر الديار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m333","text":"فساد ذات البين خراب الديار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص23"},{"id":"m334","text":"الصبر على طاعة الله أهون من الصبر على عذابه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص23"},{"id":"m335","text":"اعمل وكل، فإن الله يحب من يعمل ويأكل، ولا يحب من يأكل ولا يعمل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص23"},{"id":"m336","text":"رأس مال الدلال الكذب، وأول من دل إبليس حيث قال : « هل أدلك على شجرة الخلد وملك لا يبلى ».","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص24"},{"id":"m337","text":"الفرق بين النكاح والسفاح : الوليمة، والغناء، والدف، والإعلان.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص24"},{"id":"m338","text":"الكريم يطعم فمك، والحكيم يطعم أذنيك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m339","text":"الكريم يملأ بطنك، والحكيم يملأ عقلك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m340","text":"إذا جالست حكيما فأطعم أذنيك من أطايب كلامه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m341","text":"إذا خرج الكلام من جلجلان القلب، أفرغ في قمع الأذن ( حبة القلب )","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m342","text":"إذا خرج الكلام من حماطة القلب، بلغ صماخ الأذن. ( حبة القلب )","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m343","text":"قال عمر : إنا إذا خلونا قلنا ما يقول الناس في بيوتهم.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m344","text":"الدعاء للسائل إحدى الصدقتين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m345","text":"صاحت عصافير بطنه، ونقت ضفادعه. ( جاع )","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m346","text":"فلان شدق وعلق وحدق : لقمة في شدقه، ولقمة في يده، ولقمة في ناظره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m347","text":"ليس شيء أحب إلي من الضيف، رزقه على الله، وأجره لي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m348","text":"كل شيء ينقص في ابن آدم، إلا الحرص والأمل يزيدان.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m349","text":"لو تفكر ابن آدم في الأجل، لقصر في الأمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m350","text":"ابن آدم قصير الأجل، طويل الأمل، ضعيف العمل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m351","text":"لا يكون العمران حيث يجور السلطان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m352","text":"عدل السلطان عمار للأوطان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m353","text":"إذا أرهق الملك رعيته بجباية الأموال، كان كمن يعمر سطح بيته، بما يقتلع من قواعد بنائه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m354","text":"من طال عدوانه زال سلطانه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m355","text":"احذروا دمعة اليتيم، ودعوة المظلوم، ونهر السائل، وإذلال الغريب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m356","text":"أصبحا يتكاشحان ولا يتناصحان، ويتكاشران ولا يتعاشران.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m357","text":"إياك أن تعادي من إذا شاء خلع ثيابه، ودخل مع الملك في لحافه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m358","text":"إلى متى هذا الغرور، ويحكم، أما تمشون بين القبور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m359","text":"إذا تفقه الشريف تواضع، فأفشى السلام، وصافح العوام، وجالس المساكين، وعاد المرضى، وشيع الجنائز.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص24"},{"id":"m360","text":"إذا تفقه الوضيع تكبر، فأمر بالمعروف، ونهى عن المنكر، ووعظ الشريف، وأخذ في الحسبة، وأم أهل محلته، واحتد على من رد عليه، ورأى أن له فضيلة على كل أحدٍ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص24"},{"id":"m361","text":"لا تقل ما في خير، فإن فيك التوحيد والإخلاص، ولكن قل لقد خشيت أن يهلكني ما في من الشر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m362","text":"ما رأيت عاقلا يلم به أمر، إلا كان معوله على لحيته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص24"},{"id":"m363","text":"يقال للجميل : أنت يوسف زمانك.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m364","text":"من رأى النبي فقد اقتبس من وجهه نورا.","kind":"hikma","topic":"الإيمان والعبادة","note":"لعل رمز الصلاة على النبي سقط في الاستخراج","source":"شذرات المطوع، ص24"},{"id":"m365","text":"أقبح من عجوز يوم طلاقها.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص24"},{"id":"m366","text":"صحبة فاجر حسن الخلق، أدوم وأحب من صحبة عابد سيء الخلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m367","text":"الفاسق إذا حسن خلقه خف على الناس وأحبوه، والعابد إذا ساء خلقه ثقل على الناس ومقتوه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m368","text":"إذا اقترن حسن الخلق بالفاسق قدم، وإذا اقترن سوء الخلق بالعابد أخر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m369","text":"المتقلب كثير الألوان يقال له : أبو رياح، وقوس السماء.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص24"},{"id":"m370","text":"يباعدك من غضب الله ألا تغضب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m371","text":"أعدى أعدائك الغضب، لأنك تفعل في غضبك، ما تندم عليه في رضاك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص24"},{"id":"m372","text":"من أطاع الغضب أضاع الأدب.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m373","text":"الحلم أحمد عاقبة من الانتقام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m374","text":"لست عن نفسي راضيا فكيف أعيب الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص24"},{"id":"m375","text":"من ترك الغيبة أحرز حسناته.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m376","text":"لا تسلط الغيبة على حسناتك، فإن لم تفن تنقص.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m377","text":"لا تشغل نفسك بذكر الفاسق المجاهر، ولا تعود لسانك الغيبة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m378","text":"استعذ بالله من الشيطان الرجيم، ولا تلعنه حتى لا تعود لسانك على اللعنة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m379","text":"إذا كان عاملان من قبيلة واحدة، فلا تفاضل بينهما، حتى لا توغر صدورهما.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص24"},{"id":"m380","text":"إذا أردت أن تظلم أو تغتاب، فاذكر القطن إذا وضعوه على عينيك وفي فمك وأنفك وأذنيك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m381","text":"زين إبليس لحوم الناس للناس، فكانت أطيب من الدجاج والدراج.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m382","text":"سامع الغيبة أحد المغتابين.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص24"},{"id":"m383","text":"أهدى الحسن البصري إلى مغتابه طبقا من رطب، وقال : أهديت إلي حسناتك، فأردت أن أكافئك.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج «على مغتابه» والأرجح «إلى»","source":"شذرات المطوع، ص24"},{"id":"m384","text":"ترك الذنوب استغفار، ولا يغني عن الاستغفار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص24"},{"id":"m385","text":"أمارة المدينة وجود الحائك والمعلم.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص24"},{"id":"m386","text":"ليس حسن الجوار كف الأذى، ولكن حسن الجوار بذل الندى، والصبر على الأذى.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m387","text":"كان أبو بكر وعمر وزيري رسول الله ﷺ، وحليتيه، يتزين بهما في يوم عيد أو قدوم وفد، أبو بكر عن يمينه، وعمر عن يساره.","kind":"hikma","topic":"الإيمان والعبادة","note":"رمز الصلاة على النبي ساقط في المستخرج","source":"شذرات المطوع، ص26"},{"id":"m388","text":"منزلة أبي بكر وعمر رضي الله عنهما من الرسول في حياته، كمنزلتهما بعد الحياة وهما ضجيعاه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m389","text":"أبو بكر رضي الله عنه ثاني اثنين في الإسلام، وفي الغار، وفي المشورة يوم بدر، وفي القبر، والخلافة، والجنة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m390","text":"المؤمن مألفة، ولا خير فيمن لا يألف ولا يؤلف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m391","text":"الحرفة مع العفة، خير من الغنى مع الفجور.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m392","text":"حركة الإقبال بطيئة، وحركة الإدبار سريعة، لأن المقبل كالصاعد من مرقاة إلى مرقاة، والمدبر كالمقذوف من علو إلى أسفل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص26"},{"id":"m393","text":"عند تقلب الأحوال تعرف معادن الرجال.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m394","text":"إذا ذكرنا الموتى حييت قلوبنا، وإذا ذكرنا الأحياء ماتت قلوبنا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m395","text":"إن الكريم إذا خادعته في مال انخدع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m396","text":"إذا عصاني من يعرفني، سلطت عليه من لا يعرفني.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m397","text":"إن الله أفرح بتوبة عبده من المضل الواجد، والظمآن الوارد، والعقيم الوالد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m398","text":"الإمرة تذهب الحفيظة، وحقد السلطان عجز.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص26"},{"id":"m399","text":"« فإنه كان للتوابين غفورا » أي : يذنب ثم يتوب ثم يذنب ثم يتوب.","kind":"hikma","topic":"الإيمان والعبادة","note":"نص الآية «للأوابين»؛ أبقيت ما في الأصل","source":"شذرات المطوع، ص26"},{"id":"m400","text":"إياكم ومحقرات الذنوب، فإن محقرات الأعواد تنضج الطعام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m401","text":"البر زيادة في العمر « وأما ما ينفع الناس فيمكث في الأرض » .","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m402","text":"سبحان من حلمه أوسع من جهل عباده، وعفوه أعظم من ذنوبهم، وجوده أوسع من حوائجهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m403","text":"سبحان من يدعو المدبرين عنه، فكيف بالمقبلين عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m404","text":"قنوطكم أعظم من ذنوبكم، ويأسكم أعظم من جرمكم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m405","text":"اتقوا الله وكونوا من حيث شئتم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m406","text":"لو أن العبد أحسن الإحسان كله ثم أساء إلى دجاجة عنده لم يكن من المحسنين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m407","text":"أعبد الناس رجل اجترح الذنوب، فكلما ذكر ذنبه احتقر عمله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص26"},{"id":"m408","text":"إذا أقدرك الله على خصمك، فقد صنع لك ما أحببت، فاصنع له ما أحب : العفو.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m409","text":"من علم أنه مسيء فقد أحسن، ومن ظن أنه محسن فقد أساء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص26"},{"id":"m410","text":"لا تأمن الرجال على النساء، ولا تأمن النساء على الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m411","text":"لا توجد فتنة أشد على الرجال من النساء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m412","text":"النمائم تنبت السخائم.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص26"},{"id":"m413","text":"أمارة وفاء الرجل حنينه إلى أوطانه، وبكاؤه على ما مضى من زمانه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m414","text":"تجارها فجارها إلا من أتى بشاهدي عدل : الصدق والأمانة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m415","text":"لا تعاتب صديقك إن أفشى سرك، لأنك كنت أحق بصيانته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص26"},{"id":"m416","text":"القلب صندوق الأسرار، واللسان مفتاحه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص26"},{"id":"m417","text":"البراطيل تنصر الأباطيل. ( الرشوة )","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m418","text":"من صانع بالمال لم يحتشم من طلب الحاجة. ( المصانعة : الرشوة )","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص26"},{"id":"m419","text":"صب في قنديله زيتا. ( رشاه، والمصانعة : قندلة )","kind":"mathal","topic":"المال والاقتصاد","note":"ترتيب الأقواس مضطرب في المستخرج","source":"شذرات المطوع، ص26"},{"id":"m420","text":"لا يأخذ أحد من أحد إلا ذل له، وأنا أكره لنفسي أن أذل لغير الله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص26"},{"id":"m421","text":"الطمع فقر حاضر، واليأس غنى عاجل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص28"},{"id":"m422","text":"من يئس من شيء استغنى عنه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m423","text":"قيل للنعامة احملي، قالت : أنا طائر، فقيل لها طيري، قالت : أنا بعير، ( التعلق بالعلل )","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص28"},{"id":"m424","text":"من كرم الله تعالى أنه يأخذ ليعطي، ويبتلي ليجزي.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m425","text":"الحية سمها في أولها، والعقرب سمها في آخرها، والدنيا سمها في أولها وآخرها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m426","text":"الدنيا مطية المؤمن، يبلغ بها بالخير إلى الخير، ومطية المنافق يبلغ بها بالشر إلى الشر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m427","text":"الليل والنهار يعملان فيك ما لا ترجو عقباه، فاعمل فيهما ما ترجو عقباه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m428","text":"يا ابن آدم إذا بلغت الأربعين فالليل والنهار يعملان فيك ما يسوء، فاعمل فيهما ما يحسن.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m429","text":"عمر الإنسان ما بين الذكريات والأمنيات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m430","text":"الدنيا خمر الشيطان للإنسان، فمتى يفيق ؟","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m431","text":"مهر الآخرة طلاق الدنيا، ومهر الدنيا طلاق الآخرة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m432","text":"لا تترك الدنيا فتكن كلا على الناس، ولا تأخذها أخذا يضر بآخرتك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m433","text":"الشمس قطيفة المساكين، وتكنى بأم شملة.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m434","text":"توقوا البرد في أوله، وتلقوه في آخره.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m435","text":"البرد يفعل في الأبدان ما يفعله في الأغصان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص28"},{"id":"m436","text":"البرد أوله يحرق، وآخره يورق.","kind":"hikma","topic":"الصحة والنفس","note":"في المستخرج «الربد أول حيرق» والأرجح «أوله»","source":"شذرات المطوع، ص28"},{"id":"m437","text":"الشتاء ذكر، والصيف أنثى.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m438","text":"قال لمؤدب ولده : علمه العوم، وقلة النوم.","kind":"hikma","topic":"التربية والأسرة","note":"ينتهي في الأصل بفاصلة","source":"شذرات المطوع، ص28"},{"id":"m439","text":"علمه العوم قبل الكتابة، لأنه يجد من يكتب له، ولا يجد من يعوم عنه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص28"},{"id":"m440","text":"إذا دخلت المساجد رأيت الراكع والساجد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m441","text":"إذا دخلت السوق فاستعذ من الفسوق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص28"},{"id":"m442","text":"أمارة القرية صياح الديكة ونباح الكلاب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص28"},{"id":"m443","text":"إذا عدل السلطان في رعيته، سهل عليهم الطاعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m444","text":"إذا جار السلطان في الرعية، فتح لهم باب المعصية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m445","text":"العدل ميزان الحق، والجور ميزان الباطل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m446","text":"إذا زهد الملك في العدل زهدت الرعية في الطاعة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص28"},{"id":"m447","text":"إذا عقلك عقلك عما يشين عقلك فأنت عاقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص28"},{"id":"m448","text":"هذا كلام يتقاطر عسله.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص28"},{"id":"m449","text":"رخص الأشياء من كثرتها، وغلاءها من ندرتها، إلا العقل والعلم فغلاءهما من كثرتهما.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص28"},{"id":"m450","text":"كل شيء إذا كثر رخص، إلا العلم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص30"},{"id":"m451","text":"الطفل إذا جاع بكى، وإذا شبع سكت، ويطلب الثدي حين يحتاج إليه ويدعه حين يقضي حاجته منه، فهو يعرف مقادير احتياجاته.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m452","text":"الحلم يستر، والعقل يقطع، والصبر يحمل، والكبر يحط، والتواضع يرفع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m453","text":"لا رأي لمن استبد برأيه. ( تفرد )","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m454","text":"إذا أشكل الرأي فهو كاللؤلؤة التي تسقط في الرمل، فيجمع ما حول مسقطها ثم يلتمسها صاحبها، وكذلك استخلاص الرأي السديد، واستبعاد الآراء الضعيفة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m455","text":"ثلاثة لا يستغنون عن ثلاثة : العاقل عن الاستشارة، والدابة الفارة عن السوط، والمرأة الحسناء عن الزوج.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m456","text":"الرجال ثلاثة : رجل رجل، ورجل نصف رجل، ورجل لا رجل : فالأول : ذو الرأي والمشورة، والثاني : له رأي ولا يشاور، أو يشاور ولا رأي له، والثالث : لا رأي له ولا يشاور.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص30"},{"id":"m457","text":"عمر مفتاح الأمصار، لأنه الذي فتح أكثرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m458","text":"مما يشد أركان الملك : التودد إلى الخاصة، والعدل في العامة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m459","text":"ينبغي للوالي أن يتفقد أمر خاصته كل يوم، وأمر عامته كل شهر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m460","text":"من أخلاق الملوك حب التفرد، وكراهية المشاركة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص30"},{"id":"m461","text":"خير نساءكم الحصان الهلوك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص30"},{"id":"m462","text":"المغبون لا محمود ولا مأجور.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m463","text":"إن الكريم ليجر ذيله على الخدائع في ماله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m464","text":"إن الجواد لا يكون ماكسا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m465","text":"إذا ذكرنا الموت حييت قلوبنا، وإذا ذكرنا الحياة ماتت قلوبنا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص30"},{"id":"m466","text":"جمال طبعك فاق طابع جمالك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m467","text":"فلان حتف على الأعداء، وربيع للأصدقاء.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص30"},{"id":"m468","text":"صدور الأحرار قبور الأسرار.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص30"},{"id":"m469","text":"أجمل من رخص الأسعار، وهطول الأمطار.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m470","text":"رخص الأسعار من هطول الأمطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m471","text":"غلاء الأسعار من قلة الأمطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص30"},{"id":"m472","text":"لولا الرسوم لضاعت العلوم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص30"},{"id":"m473","text":"المباني مطية المعاني.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص30"},{"id":"m474","text":"المبتدي بالخير خير من المقتدي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص30"},{"id":"m475","text":"من أجسر أيسر، ومن هاب خاب.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص30"},{"id":"m476","text":"العلقة خرقة، والحب عذاب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m477","text":"الأمثال مصابيح الأقوال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص32"},{"id":"m478","text":"لا ينصف اللسان في وصف الإساءة والإحسان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص32"},{"id":"m479","text":"دون النجاح مشقة النطاح.","kind":"mathal","topic":"النجاح والإبداع","source":"شذرات المطوع، ص32"},{"id":"m480","text":"رب نظرة أثمرت صبابة.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m481","text":"القريب من قرب بره، وإن كان بعيدا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m482","text":"البعيد من بعد بره، وإن كان قريبا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص32"},{"id":"m483","text":"كن جميل الصبر عند قبح المصيبة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص32"},{"id":"m484","text":"قيل للعجلة ما كنيتك ؟ قالت : أم الندامة.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m485","text":"قيل للتؤدة ما كنيتك ؟ قالت : أم السلامة.","kind":"mathal","topic":"العقل والحكمة","note":"في المستخرج «أم السالم» والأرجح «السلامة»","source":"شذرات المطوع، ص32"},{"id":"m486","text":"إن المحسن معان، والمسيء مهان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص32"},{"id":"m487","text":"يا أنيس المنفردين، حططنا رحلنا بفنائك، لا نلوذ بالمعذرة، بل نعول على المغفرة.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص32"},{"id":"m488","text":"الإفراط في توقي الخطأ خطأ.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m489","text":"الاقتصاد في العمل أدوم للعمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص32"},{"id":"m490","text":"الجمال في المرأة أظهر، والجلال في الرجل أظهر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m491","text":"جلال الجمال في المرأة، يعدل جمال الجلال في الرجل.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص32"},{"id":"m492","text":"أجمل ما يكون الجميل إذا قارن القبيح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص32"},{"id":"m493","text":"جمال الخط يبرز الحق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص32"},{"id":"m494","text":"كثرة الحسن في الملامح والأعضاء جمال.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص32"},{"id":"m495","text":"الجمال قيد النظر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m496","text":"الأم ترى ابنها جميلا لأنها تحبه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص33"},{"id":"m497","text":"الزوج يحب زوجته لأنه يراها جميلة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m498","text":"الجمال موهوب، وهو أول السعادة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m499","text":"الجمال مفتاح القلوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m500","text":"الجمال يخطب المودة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m501","text":"الجمال يثير الغيرة، ويدعو إلى الحسد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m502","text":"الجمال محط الأنظار، ومطمع الآمال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m503","text":"الجمال يفتح الأبواب المغلقة، ويستدعي الكلمات المؤنقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m504","text":"الجمال يشفع لصاحبه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m505","text":"الجمال يدرك من أول وهلة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص33"},{"id":"m506","text":"اجتمع فيه جمال الطبع، وطابع الجمال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m507","text":"طابع الجمال يسبق جمال الطبع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m508","text":"كنت أرى فيه طابع الجمال، فلما خالطته رأيت فيه جمال الطبع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m509","text":"جمال الطبع يزيد في طابع الجمال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m510","text":"الرجل لا يمكن أن يكتم حب المرأة يوما واحدا، ويمكن أن يكتم بغضها أعواما.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m511","text":"المرأة لا يمكن أن تكتم بغض الرجل يوما واحدا، وتكتم حبه أعواما.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص33"},{"id":"m512","text":"أجلست عبدي فاتكأ.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص33"},{"id":"m513","text":"التسلط على الضعيف دناءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص33"},{"id":"m514","text":"من كرم الرجل سوء أدب غلمانه.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m515","text":"أضيع من قمر الشتاء.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m516","text":"إذا طلع القمر طاب السفر.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m517","text":"انحط من الثريا إلى الثرى.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m518","text":"المطر بعل الأرض.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m519","text":"الليالي حبالى، ليس يدرى ما تلد.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m520","text":"دع من الثياب المحتقر والمشتهر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m521","text":"جمال الثياب يزيد من جمال الشباب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m522","text":"بينهما سوق السلاح.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m523","text":"نعم الواقي من الخطر الحاضر أجل غائب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m524","text":"كفى بتأخير الأجل واقيا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m525","text":"لا ترفع عصاك عن أهلك. ( كناية عن التأديب بالتخويف ).","kind":"mathal","topic":"التربية والأسرة","source":"شذرات المطوع، ص36"},{"id":"m526","text":"عصا الجبان أطول.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m527","text":"علق عصاك حيث يراها أهلك.","kind":"mathal","topic":"التربية والأسرة","source":"شذرات المطوع، ص36"},{"id":"m528","text":"لا تدخل بين العصا ولحائها.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m529","text":"هو لين العصا. إذا كان رفيقا.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص36"},{"id":"m530","text":"فلان ألقى عصاه. إذا أقام.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m531","text":"طارت عصاهم شققا. أي : تفرقوا.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص36"},{"id":"m532","text":"ليس في عصاه سير. أي : ما به حركة.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص36"},{"id":"m533","text":"قشرت له العصا. أي : كاشفته.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص37"},{"id":"m534","text":"أقرب من عصا الأعرج.","kind":"mathal","topic":"الحياة والزمن","note":"في الأصل «عصاه الاعرج»","source":"شذرات المطوع، ص37"},{"id":"m535","text":"هم عبيد العصا. إذا استذلوا.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m536","text":"الدار الضيقة العمى الأصغر.","kind":"mathal","topic":"الحياة والزمن","source":"شذرات المطوع، ص37"},{"id":"m537","text":"أبطأ فيض الدلاء أملؤها.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص37"},{"id":"m538","text":"عفو الله أكثر من ذنوب عباده.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m539","text":"لا تنس الموت، فإنه لا ينساك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m540","text":"العافية ملك خفي.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص37"},{"id":"m541","text":"تاجروا الله بالصدقات تربحوا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص37"},{"id":"m542","text":"ربما أتى البلاء من فرط الحب، فيوسف أحبه أبوه - عليهما السلام - فحسده إخوته، وألقوه في الجب، وأحبته امرأة العزيز فلبث في السجن بضع سنين.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص37"},{"id":"m543","text":"استعيذوا بالله من كيد النساء، وكونوا من ثقاتهن على حذر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص37"},{"id":"m544","text":"قيل للحسن : أيكذب المؤمن ؟ فقال : أنسيتم إخوة يوسف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m545","text":"للملوك بدوات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m546","text":"الملك يبقى على الكفر، ولا يبقى على الظلم.","kind":"hikma","topic":"السياسة والقيادة","note":"في الأصل «يتبىق»","source":"شذرات المطوع، ص37"},{"id":"m547","text":"عفو الملك أبقى للملك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص37"},{"id":"m548","text":"الحمد يشترى، والذم بالمجان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m549","text":"قصد رجل رجلا ذا جاه وكرم، فقال له : من أنت ؟ فقال : أنا الذي أحسنت إليه، فقال : مرحبا بمن توسل إلينا بنا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m550","text":"لذة العفو خير من لذة العقوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص37"},{"id":"m551","text":"صيانة العلم ببذله لأهله.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص37"},{"id":"m552","text":"حفظ العلم بإنفاقه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص37"},{"id":"m553","text":"إذا كثرت الأمطار قلت الأسعار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m554","text":"إذا قلت الأمطار ارتفعت الأسعار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m555","text":"تقول النخلة لجارتها أبعدي عني ظلك، لأحمل حملي وتحملي حملك.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص38"},{"id":"m556","text":"أول الربح حفظ رأس المال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m557","text":"الأسواق موائد الله في أرضه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m558","text":"من اشترى الدون، رجع وهو مغبون.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m559","text":"الكفالة ندامة.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m560","text":"لا تشتر كل ما تشتهيه، يكفيك أن تشتري بعض ما تشتهيه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m561","text":"طعام المطاعم مستطاب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص38"},{"id":"m562","text":"إذا سلمت الأرواح، خفت خسارة الأرباح.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m563","text":"من لم يحترف، لم يعتلف.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m564","text":"ليس في البيت إلا البيت.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص38"},{"id":"m565","text":"القبح حارس المرأة.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص39"},{"id":"m566","text":"خير المناكح الأبكار.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص39"},{"id":"m567","text":"قيل لحكيم : مالك تمسك العصا ؟ ولست بمريض ولا كبير، فقال: حتى لا أنسى أني عابر سبيل.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص39"},{"id":"m568","text":"لا تكثر الوعد، فإنه فيه شائبة رق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص39"},{"id":"m569","text":"كل كثير عدو الطبيعة. ( الأكل الكثير، والسهر الكثير وحمل الأثقال الكثيرة).","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m570","text":"العاقل يترك بعض ما يحب، ليحرز نفسه عن بعض ما يكره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص39"},{"id":"m571","text":"إذا اشتهى المريض الطعام فبشره بالصحة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m572","text":"من أكل ما لا يشتهيه، حرم مما يشتهيه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m573","text":"الغم مرض الروح، والألم مرض البدن.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m574","text":"ربما أضر بالشيخ الجارية الحسناء، والطباخ الحاذق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص39"},{"id":"m575","text":"قبلة الوالدين بر، وقبلة الأولاد عطف، وقبلة الأخ صلة، وقبلة الزوجة عاطفة، وقبلة القادم شوق، وقبلة العالم توقير، وقبلة الملك طاعة، وقبلة الحجر الأسود إتباع، وقبلة المصحف تعظيم، وقبلة آل البيت قربة، وقبلة المكاشح مخادعة، وقبلة الصغير ملاطفة، وقبلة الكبير تقدير، وقبلة الضيف إيناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص39"},{"id":"m576","text":"من خدم السوقة فهو خادم من جميع الجهات.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m577","text":"من خدم الملك فهو خادم من جهات، وملك من جهة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m578","text":"السلطان إذا غضب كالبحر إذا هاج، فتوقاه بالابتعاد عنه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m579","text":"ادن من السلطان دنوك من النار، عند الحاجة، ثم ابتعد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m580","text":"السلطان العادل كالغيث، يحيي البلاد وينعش العباد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m581","text":"السلطان الجائر كالنار تحرق البلاد، وتهلك العباد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m582","text":"أحق الناس بالإحسان من جاز حكمه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m583","text":"استكثروا من الحمد بالحلم والجود، فإن الذم قل من ينجو منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص40"},{"id":"m584","text":"إذا أقبلت عليك الدنيا فلير آثارها على من حولك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m585","text":"الكريم يطلب المال لينفقه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m586","text":"لن تبلغ مرتبة الشرف حتى تطأ طرف السرف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص40"},{"id":"m587","text":"إذا أردت أن تطفئ الفتنة، فلا تحرك ساكنا وسكن كل متحرك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m588","text":"من أراد أن يثير الفتنة حرك الساكن، ولم يسكن المتحرك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص40"},{"id":"m589","text":"من وفى لمن لا يرجى كان لمن يرجى أوفى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m590","text":"قال الرشيد لمعن بن زائدة : سلني، قال : يدك بالعطية أطلق من لساني بالمسألة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m591","text":"أسوس الملوك من كان له في نفوس رعيته هيبة، وفي قلوبهم محبة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m592","text":"الناس لا يصلحون إلا على الشدة واللين، والعفو والعقاب، والبذل والمنع، فإذا كان الأمر كذلك، عاد المنع عطاء، والمكروه محبوبا، بحسب المآل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m593","text":"وصى ملك ابنه فقال : لا تمكن الناس من كثرة رؤيتهم لك، فإن أجرأ الناس على الأسد أكثرهم له رؤية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص41"},{"id":"m594","text":"كل كثير عدو للطبيعة ( البرد الكثير، الحر الكثير، الرياح الكثيرة، المطر الكثير ).","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص41"},{"id":"m595","text":"الناس أتباع من غلب.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m596","text":"النفس عيوف شغوف.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص41"},{"id":"m597","text":"ما عاب الرجل الكريم كنفسه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m598","text":"والمرء يصلحه الجليس الصالح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m599","text":"من لم يحسن إلى نفسه كيف يحسن إلى غيره ؟.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m600","text":"ناقل القبيح أقبح من قائله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص41"},{"id":"m601","text":"وجه المحرش أقبح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m602","text":"أنت فيهم كالرأس في البدن، والعين في الرأس، والإنسان في الحدقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص41"},{"id":"m603","text":"كيف لا أستحي، وأنا ملتحي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص41"},{"id":"m604","text":"يحلب تيسا من شهوة اللبن.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص41"},{"id":"m605","text":"أخفق حالب التيس.","kind":"mathal","topic":"العقل والحكمة","note":"تكرر في الصفحة السابقة بخلل استخراج فأثبت هنا","source":"شذرات المطوع، ص42"},{"id":"m606","text":"القرد قبيح مليح.","kind":"mathal","topic":"الحياة والزمن","note":"تكرر في الصفحة السابقة بصيغة «القدر» بخلل استخراج فأثبت هنا","source":"شذرات المطوع، ص42"},{"id":"m607","text":"الكافي الخائن خير من العاجز الأمين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m608","text":"أين الكفاة الخونة ؟.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m609","text":"ينبغي للملك أن يرفق بعدوه، كالزجاج يرفق بالزجاجة حتى يضعها على حد الكسر ثم يكسرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m610","text":"الفرار في وقته انتصار.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m611","text":"ربما نتج الاقدام من الاحجام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m612","text":"الإدبار في حينه إقبال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m613","text":"الفر في وقته كالكر في وقته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m614","text":"التأخر قبل التندم خير من التندم بعد التقدم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص42"},{"id":"m615","text":"ينبغي للملك أن يختار الحال المناسبة مع عدوه : المقاربة والملاينة، أو المساترة والمخافتة، أو المكاشفة والمحاربة. ويتوخى سيرة الرسول.","kind":"hikma","topic":"السياسة والقيادة","note":"لعل الصلاة على النبي سقطت بعد «الرسول»","source":"شذرات المطوع، ص42"},{"id":"m616","text":"يستحسن في الحرب ما يستقبح في السلم : الخديعة والمكر والكذب، والتبذير والجهل والتهور، وترك النظر في العواقب والعنف والكيد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m617","text":"الجهل في الحرب خير من العقل، والمحرض خير من المقاتل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m618","text":"الحرب يقدمها الكلام.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m619","text":"الحرب سجال، وعثراتها لا تقال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m620","text":"المكيدة أبلغ من النجدة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص42"},{"id":"m621","text":"المكر حيلة من لا حيلة له.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص42"},{"id":"m622","text":"الليل جنة الهارب.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m623","text":"الهارب لا يعرج على صاحب.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m624","text":"الفر في حينه كر.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m625","text":"اتقوا الله، وكونوا أبناء من شئتم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص43"},{"id":"m626","text":"ألذ الأشياء ما كان بعد الحرمان : ألذ الطعام ما أعقب الجوع الشديد، وألذ الشراب ما أعقب الظمأ، وألذ النوم ما أعقب السهر، وأطيب النكاح ما كان بعد عزوبة، وعلى هذا جميع ملاذ الدنيا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص43"},{"id":"m627","text":"من رأى وجهه جميلا، فلا يشنه بقبيح من فعله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m628","text":"من رأى وجهه قبيحا، فليحسن فعله، ولا يجمع بين قبيحين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m629","text":"الشرف في التغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m630","text":"التغافل من عادات الملوك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m631","text":"أهل المروءات ينخدعون للسؤال.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m632","text":"من كمال مروءة الرجل أن يجر ذيله على الخدائع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m633","text":"من صفات سيد القوم التغابي.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m634","text":"من أمارات العاقل أن لا يكثر نظره في محقرات الأمور، لأنها تشغله عن جلائلها ومهماتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص43"},{"id":"m635","text":"من خدم الملوك خدم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص43"},{"id":"m636","text":"من نصح في خدمته، نصح في مكافأته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص43"},{"id":"m637","text":"قليل التوفيق أجدى عليك من كثير الاجتهاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص43"},{"id":"m638","text":"اللهم إن أعنتنا فوفقنا، وإن خذلنا فلا تحرمنا.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص43"},{"id":"m639","text":"لا تقل كل ما لديك في أول الجلسة، حتى لا تجد موضعا للمزيد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m640","text":"لا تمنح صديقك معروفك كله، ودع للمزيد موضعا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m641","text":"لا تبذل المجهود كله، ودع شيئا للطوارئ والطوارق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص44"},{"id":"m642","text":"لا تجالس المسخوط عليه، ولا الظنين، ولا صاحب نحلة هو بها ضال، إلا أن تكون ناصحا أو مصلحا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m643","text":"حسن الاستماع يميل نحوك قلب المتحدث إليك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m644","text":"سوء الاستماع يبين عنك قلب المتحدث إليك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص44"},{"id":"m645","text":"الزكمة سيئة الجوار.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص44"},{"id":"m646","text":"المريض يعاد ولا يجالس، ويسأل عنه، ولا يسأل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص44"},{"id":"m647","text":"وعد البخيل مزاح، ومزاح الكريم وعد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m648","text":"وعيد الجبان مزاح، ومزاح الشجاع وعيد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m649","text":"موائد الملوك للتشريف لا للتشبيع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m650","text":"إذا حضر طعام، فلا تسافر يدك على الخوان، ولا ترعى عشب الجيران، ولا تبادر هتك الألوان.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m651","text":"جودة الأكل إنما تحسن مع من لا يحتشم منهم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m652","text":"قلم أظافرك، ونظف كمك، وصغر لقمتك، وكل مع من شئت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص44"},{"id":"m653","text":"ما سكن الغضبان، ولا استعطف السلطان، ولا سلت السخائم، ولا وضعت المغارم، ولا استميلت القلوب، ولا توقي المرهوب، بمثل الهدايا والهبات.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص44"},{"id":"m654","text":"الحرب تقع بين حوارين : حوار يتصاعد يسلم إلى الحرب، وحوار يتنازل يسلم إلى السلم. وكذلك الخصومات، والاختلافات. على هيئة الذي يرقى جبلا أو قبة، يبدأ من الحضيض ثم السفح ثم القمة، ثم من القمة إلى السفح ثم الحضيض.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص45"},{"id":"m655","text":"مادح البخيل يحرث الماء، ويطحن الهواء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m656","text":"مادح الكريم يهز الأشجار المثمرة، ويلتقط الثمار اليانعة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m657","text":"لا تسترضعوا الحمقاء، فإن اللبن يفسد النسب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص45"},{"id":"m658","text":"والمرء يفسده الجليس الفاسد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m659","text":"من أساء إلى نفسه كيف لا يسيء إلى غيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m660","text":"الحرب تبدأ بالكلام، وتنتهي بالكلام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص45"},{"id":"m661","text":"الحرب والسلم يبدأن بالكلام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص45"},{"id":"m662","text":"اتق دعوة اليتيم والغريب، والأرملة والضعيف، ومن لا حيلة له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص45"},{"id":"m663","text":"خير العلم ما لاكته بلسانك، ووعاه قلبك.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص45"},{"id":"m664","text":"من أبدى لنا زيا حسنا، أحسنا به الظن، فيما غاب به عنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m665","text":"من أبدى لنا زيا سيئا، أسأنا به الظن، فيما غاب به عنا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص45"},{"id":"m666","text":"ترك الفخر أبقى للثناء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m667","text":"أسرع جرم عقوبة البغي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m668","text":"من سوء الأدب كثرة العتاب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص45"},{"id":"m669","text":"المسألة أرذل المكسبة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص45"},{"id":"m670","text":"الانقباض يكسب المقت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m671","text":"الاسترسال يدعو جليس السوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m672","text":"كن في الناس بين المنقبض والمسترسل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m673","text":"الغريب بكل مكان ذليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m674","text":"العزة مع الكثرة، والذلة مع القلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m675","text":"من يبحث العيب يجده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m676","text":"نفى اللوم عن نفسه الرسول.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m677","text":"الشر يبدؤه صغاره.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص46"},{"id":"m678","text":"المكثار كحاطب ليل.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m679","text":"خير الكلام ما يستعاد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص46"},{"id":"m680","text":"الأنس يذهب المهابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m681","text":"تناءوا في الديار، وتواصلوا في المزار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص46"},{"id":"m682","text":"من طاب فعله، طاب ذكره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m683","text":"طيبوا أخباركم بحسن أعمالكم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص46"},{"id":"m684","text":"لن ترى في ولدك ما تحب، حتى ترى في نفسك ما تكره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص46"},{"id":"m685","text":"من أسعده ولده، أشقاه بدنه.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص46"},{"id":"m686","text":"لا تكثر الوعد، فإن فيه شائبة رق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص47"},{"id":"m687","text":"المرض ضعف عارض، والهرم ضعف مقيم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص47"},{"id":"m688","text":"من أكل ما يشتهيه فقد أكل، ومن أكل ما لا يشتهيه فقد أكل.","kind":"hikma","topic":"الصحة والنفس","note":"لعل الثانية: أُكل","source":"شذرات المطوع، ص47"},{"id":"m689","text":"من جاد لك بمودته، فقد جعلك عديل نفسه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m690","text":"توق الإفراط في المحبة، فإن الإفراط يدعو إلى التقصير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m691","text":"المحبة المتنامية خير من المحبة المتناهية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m692","text":"اقتصد في حبك وبغضك، فإنك لا تدري متى تتغير الأحوال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m693","text":"من أكثر العتاب لم يكترث بسخطه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m694","text":"تناس مساوي الإخوان، يدم لك ودهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m695","text":"التواصل يحتاج إلى التغافل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص47"},{"id":"m696","text":"العاقل فطن متغافل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص47"},{"id":"m697","text":"تثمير المال يعين على اصطناع الرجال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m698","text":"من استصلح عدوه، زاد في أصدقائه، وانقص من أعدائه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص48"},{"id":"m699","text":"تستصلح الأعادي بحسن الأيادي.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص48"},{"id":"m700","text":"ذكروا عباد الله، بإحسان الله وإنعامه، فإن الناس لا يحبون إلا من أنعم عليهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص48"},{"id":"m701","text":"السخي قريب من الله، قريب من الناس، قريب من الجنة، بعيد من النار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m702","text":"البخيل بعيد من الله، بعيد من الناس، بعيد من الجنة، قريب من النار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m703","text":"سادات الناس في الدنيا الأسخياء، وفي الآخرة الأتقياء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m704","text":"الحرص : المبالغة في طلب الشئ. والشره : الاستكثار لغير الحاجة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m705","text":"مثل الاقتصاد والإسراف مثل الصديق والعدو.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m706","text":"الإسراف : ما زاد عن الحاجة. والتبذير : ما كان لغير حاجة فالتبذير أشد من الإسراف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m707","text":"كل سرف بإزائه حق مضيع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m708","text":"في إعطاء من لا يستحق، حرمان من يستحق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m709","text":"البذل الجائر يعدل المنع الجائر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m710","text":"الإسراف يهدر الحقوق، والاقتصاد يحفظها.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m711","text":"حسن الظن قبل التجربة غرر، وسوء الظن قبل التجربة حذر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص48"},{"id":"m712","text":"ترك الإسراف يحفظ الأكرمين : الدين والعرض.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m713","text":"من اتخذ التبذير رداء خرج من بحبوحة الحلال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m714","text":"الاقتصاد يصون ماء الوجه، والتبذير يبذل.","kind":"hikma","topic":"المال والاقتصاد","note":"لعلها: يبذله","source":"شذرات المطوع، ص48"},{"id":"m715","text":"المسرف لا يسعه الحلال، والمقتصد لا يضيق عليه الحلال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص48"},{"id":"m716","text":"من تمام السخاء أن لا تستشرف نفسك إلى ما في أيدي الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص48"},{"id":"m717","text":"شر النكاح نكاح الغلمة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص49"},{"id":"m718","text":"لقاء الإخوان جلاء الأحزان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m719","text":"الغريب من ليس له حبيب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m720","text":"الأضداد لا تتفق، والأشكال لا تفترق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m721","text":"التشاكل قرابة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m722","text":"مراتب الإخاء : التجانس ثم المواصلة ثم المؤانسة، ثم المصافاة ثم المودة ثم المحبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m723","text":"رب صديق أقرب من شقيق.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m724","text":"اسبر تخبر.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m725","text":"الرجل يعرف من فعله لا من كلامه، ومن عينه لا من لسانه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m726","text":"يظن بالمرء ما يظن بقرينه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m727","text":"مصارمة قبل اختبار، خير من مؤاخاة على اغترار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m728","text":"لا تثق قبل الخبرة، ولا تتقدم قبل القدرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m729","text":"المدح والذم بعد التجربة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m730","text":"زيادة العقل بمجالسة العقلاء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m731","text":"العاقل يعاشر بالمعروف من لم يجد من معاشرته بدا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m732","text":"خيار كل شئ قليل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص49"},{"id":"m733","text":"أول مراتب الإخوة التجانس والمشاكلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص49"},{"id":"m734","text":"فساد الزمان وأهله، يوجب شكر من قطع شره، ومنع خيره.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص49"},{"id":"m735","text":"صلاح الزمان وأهله، يوجب ذم من قطع شره، ومنع خيره.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص49"},{"id":"m736","text":"أقسام الإخوان أربعة : منهم يعين ويستعين، ومنهم لا يعين ولا يستعين، فهذان سواء، فهذه بتلك. ومنهم من يستعين ولا يعين، فهذا أرذلها. ومنهم من يعين ولا يستعين، فهذا أفضلها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m737","text":"التارك للإخوان متروك، والمعتزل معزول.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m738","text":"العاقل لا يزهد في الصديق لخلق أو خلقين، إذا رضي سائر أخلاقه وحمد أكثر شيمه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m739","text":"يكفيك من أخيك أكثره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص50"},{"id":"m740","text":"نفسك التي بين جنبيك، لا تعطيك قيادها في كل ما تريد، فكيف بنفس غيرك؟","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص50"},{"id":"m741","text":"أدوم الأعمال أيسرها.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص50"},{"id":"m742","text":"الجمال والقبح إذا اقترنا زادا، وإذا افترقا نقصا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m743","text":"الجمال والجمال إذا اقترنا نقصا، وإذا افترقا زادا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m744","text":"كل مقيم شاخص، وكل زائد ناقص.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص50"},{"id":"m745","text":"أسمى درجات التفكير في مسائل القدر ترك التفكير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m746","text":"التسليم في مسائل القضاء والقدر أجدى على الإنسان من التفكير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m747","text":"في مسائل القضاء والقدر الإعراض عن التفكير تفكير.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المستخرج: الأعراض","source":"شذرات المطوع، ص50"},{"id":"m748","text":"الطير أكثر توكلا من الإنسان في قضية الرزق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m749","text":"الحيوان أسعد من الإنسان في قضية الإيمان بالقضاء والقدر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m750","text":"الحيوان أعقل من الإنسان في مسائل القضاء والقدر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص50"},{"id":"m751","text":"ترك التفكير تفكير، وترك الرأي رأي.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص50"},{"id":"m752","text":"ليس السعي في طلب المعاش من طلب الدنيا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m753","text":"إذا كان في البيت بر فتعبد، وأن لم يكن فأطلبه بالعمل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m754","text":"يا بن آدم حرك يديك ورجليك، يفتح لك باب من رزق.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m755","text":"ليس من إيثار الدنيا على الآخرة، اكتساب ما يصون العرض، ويحفظ ماء الوجه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص51"},{"id":"m756","text":"السلطان قد يفسد، وما يصلح الله به أكثر، فإن عدل فله الأجر، وعليكم الشكر، وإن جار فعليه الوزر، وعليكم الصبر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص51"},{"id":"m757","text":"إذا أحب الله عبدا حببه إلى خلقه، فاعرف منزلتك من الله تعالى بمنزلتك من الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m758","text":"مالك عند الله، مثل ما لله عندك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m759","text":"من اتقى الله، أطاعه في خلقه، وطاعته في خلقه تبعث على محبته، فكانت محبتهم له أمارة على محبة الله له.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m760","text":"أخش الله في الناس، ولا تخش الناس في الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m761","text":"بئس الزاد إلى المعاد، العدوان على العباد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص51"},{"id":"m762","text":"إذا انحاز المختلفان إلى العدل، لم يحتاجا إلى القوة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m763","text":"إذا قصد المتنازعان الإصلاح منحا التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m764","text":"نية الإصلاح تجلب التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m765","text":"إرادة الإصلاح أمارة التوفيق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m766","text":"ينال التوفيق على قدر إرادة الإصلاح.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص51"},{"id":"m767","text":"من أراد الله أن يوفقه هداه إلى أحمد السبل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص52"},{"id":"m768","text":"ويبقى الائتلاف ما بقي الإنصاف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m769","text":"أول درجات الائتلاف الإنصاف.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m770","text":"العدل ميزان الله في أرضه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص52"},{"id":"m771","text":"حلية العالم قلة الطمع وكثرة الورع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص52"},{"id":"m772","text":"أشتهي أن أرى عالما قليل الطمع كثير الورع.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص52"},{"id":"m773","text":"إذا رأيت الرجل يداري الناس كلهم، فاعلم أنه تام العقل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص52"},{"id":"m774","text":"دار الناس كلهم فأنت في دار المداراة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص52"},{"id":"m775","text":"معرفة مقدار النعمة منوط بمقاساة ضدها.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص52"},{"id":"m776","text":"عندما ابتليت، علمت أن الله لم يبتلني قبل ذلك، ولا أكثر من ذلك، ولا في غير ذلك، ورجوت أن يرفعه عني، فأعانني ذلك على الصبر، وصرت من الشاكرين لا الشاكين.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص52"},{"id":"m777","text":"إذا كثر المطر، كثر الخصب، وإذا كثر الخصب كثر الغنى، واذا كثر الغنى، كثرت الأمانة والسخاء.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص52"},{"id":"m778","text":"جمع خير الدنيا والآخرة في التقى والغنى، وجمع شر الدنيا والآخرة في الفقر والفجور.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص52"},{"id":"m779","text":"الفرق بين الآمال والأماني ترك العمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص52"},{"id":"m780","text":"الدنيا مقلوبة، فإذا انقلبت استوت.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص52"},{"id":"m781","text":"لا ترج من الناس الطاعة، ونفسك تمنعك الطاعة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص52"},{"id":"m782","text":"إذا عصاك هواك، فكيف تطمع أن يطيعك من يهواك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص52"},{"id":"m783","text":"من تفكر أبصر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص52"},{"id":"m784","text":"الولد ثمرة الفؤاد، وهو به أنوط.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m785","text":"شر الأبناء للآباء من دعاه التفريط للعقوق.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m786","text":"شر الآباء للأبناء من دعاه البر إلى الإفراط.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m787","text":"إن الله تعالى رضي الآباء للأبناء، فحذرهم فتنتهم، ولم يوصهم بهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m788","text":"إن الله تعالى لم يرض الأبناء للآباء، فأوصاهم بهم، وحذرهم من الإساءة إليهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m789","text":"حق الوالد أعظم، وبر الأم ألزم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m790","text":"ولد الولد الصفوة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m791","text":"رحم الله امرأ أعان ولده على بره.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m792","text":"البعيد قريب بمودته، والقريب بعيد بعداوته.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص53"},{"id":"m793","text":"العقوق ثكل من لم يثكل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m794","text":"امش وراء الأسد، ولا تمش وراء المرأة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m795","text":"إن صاحبت غير المحمود، لم يصحبك المحمود.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص53"},{"id":"m796","text":"قال حكيم لأبنائه : قد أحسنت إليكم قبل أن تولدوا، قالوا : كيف ذلك ؟ قال : أحسنت اختيار أمكم وأخوالكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m797","text":"أول إحسان الأب لأولاده، اختيار أمهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص53"},{"id":"m798","text":"أنجب النساء الفروك.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m799","text":"ولد الغيرى لا ينجب.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m800","text":"إذا أكره الرجل المرأة، وهي مذعورة، ثم أذكرت أنجبت.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات المطوع، ص53"},{"id":"m801","text":"الجاه بالبذل ينمي ويزيد، وبالكف ينقص ويبيد.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص54"},{"id":"m802","text":"الخلق عيال الله وأحب خلق الله إليه، أحسنهم صنيعا إلى عياله.","kind":"hikma","topic":"الإيمان والعبادة","note":"في المستخرج: عيال","source":"شذرات المطوع، ص54"},{"id":"m803","text":"اصنع الخير عند إمكانه يبق لك حمده عند زواله.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج: زوال","source":"شذرات المطوع، ص54"},{"id":"m804","text":"أحسن والدولة لك، يحسن إليك والدولة عليك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص54"},{"id":"m805","text":"اجعل زمان رخائك عدة لزمان بلائك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص54"},{"id":"m806","text":"من أمارات تحسين الحال اصطناع الرجال.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m807","text":"بذل الجاه أحد الحباءين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m808","text":"ليس حسن الجوار كف الأذى، بل الصبر على الأذى.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m809","text":"من أحسن إلى جاره فقد دل على حسن نجاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m810","text":"أشبه أفعال الناس بأفعال الله تعالى، الإحسان إلى الناس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m811","text":"من أمرك لأداء الفرائض، أمرك بمداراة الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص54"},{"id":"m812","text":"إن الله تعالى أمر بالعبادة، وأمر بحسن الخلق.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص54"},{"id":"m813","text":"لا تقطع أخاك إلا بعد نفاد الحيلة في استصلاحه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m814","text":"في الخير البادئ خير من المكافئ، وفي الشر المكافئ أعذر من البادئ، وان كان الصفح أجمل وأنبل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m815","text":"من فعل ما شاء لقي ما لم يشأ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m816","text":"اعتزل الشر يعتزلك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m817","text":"أقرض الناس من عرضك ليوم فاقتك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m818","text":"العاقل الكريم صديق كل أحد إلا من ضره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m819","text":"الجاهل اللئيم عدو كل أحد إلا من نفعه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m820","text":"شر ما في الكريم أن يمنعك خيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m821","text":"خير ما في اللئيم أن يكف عنك شره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m822","text":"أعداؤك داؤك، وفي البعد عنهم شفاؤك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m823","text":"من شرف الكريم تغافله عن اللئيم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m824","text":"إذا سلم الناس منك، فلا عليك ألا تسلم منهم، فإنه قلما اجتمعت هاتان النعمتان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m825","text":"نماء المودة بكثرة التعاهد.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m826","text":"لا تهجر صديقك الأول، فلا يطمئن لك الثاني.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m827","text":"العفو والعقوبة، كالجود والبخل، فاختر أيهما شئت.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص54"},{"id":"m828","text":"إذا جفاك أخوك لملل لا لزلل، فدعه على ملله، حتى يمل الجفاء كما مل الإخاء، فيعود لسابق عهده.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص54"},{"id":"m829","text":"كل ما أصميت، ودع ما أنميت.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص55"},{"id":"m830","text":"لا تمثلوا بنامية الله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m831","text":"إن أساء إليك أخوك، ثم ظهر ندمه، وبان خجله، فاجعل ندمه اعتذارا، ولا تكلفه ذل الاعتذار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص55"},{"id":"m832","text":"آخر ما نزل من القرآن : ( واتقوا يوما ترجعون فيه إلى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون ).","kind":"hikma","topic":"الإيمان والعبادة","note":"سقطت «لا» من المستخرج فأثبتت من نص الآية","source":"شذرات المطوع، ص55"},{"id":"m833","text":"وآخر ما نزل من التوراة : إذا لم تستح فاصنع ما شئت.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m834","text":"وآخر ما نزل من الإنجيل : شر الناس من لا يبالي أن يراه الناس مسيئا.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m835","text":"وآخر ما نزل من الزبور : من يزرع خيرا يحصد زرعه غبطة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m836","text":"من خان هان.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص55"},{"id":"m837","text":"من يذنب ويشعر بالندم، خير ممن يذنب ولا يشعر بالندم ومن يذنب ولا يشعر بالندم، خير ممن يذنب ويتباهى بالذنب. فالأول يرجى له والثاني يرجى له ويخشى عليه، والثالث يخشى عليه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص55"},{"id":"m838","text":"لا يحملنكم إبطاء الرزق، على أن تطلبوه بمعاصي الله تعالى، فإن الله لا يدرك ما عنده إلا بطاعته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m839","text":"إذا لم يشق المرء إلا بما عمل فقد سعد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص56"},{"id":"m840","text":"من حسن ظنه بمن لا يخاف الله فهو مخدوع.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص56"},{"id":"m841","text":"يسير المال مع حسن التدبير، أجدى نفعا من كثيره مع سوء التدبير.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m842","text":"المضارب في مال كالباذر في أرضه إذا روعي يسيره زكا، وإن أهمل كثيره اضمحل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m843","text":"لا تكن على أحد كلا، فتزداد ذلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص56"},{"id":"m844","text":"الكاسب خير من الوارث، لأن الكاسب ينفع غيره، والوارث ينتفع من غيره.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص56"},{"id":"m845","text":"أحفظ ماء وجهك بالقناعة واذكر الله تعالى في كل ساعة، فنعمت البضاعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص56"},{"id":"m846","text":"إن استطعت أن لا يكون بينك وبين الله ذو نعمة فافعل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m847","text":"لا تكن عبد غيرك وقد جعلك الله حرا، فإن اليسير من الله تعالى أكرم وأعظم من الكثير من غيره، ويسير الله تعالى أكثر من كثير غيره.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص56"},{"id":"m848","text":"قدم لحاجتك، بعض لجاجتك، فإنه لا يظفر بحاجته إلا الملح الصبور.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص57"},{"id":"m849","text":"رق الدين أيسر من رق الإفضال.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص57"},{"id":"m850","text":"من ألف المسألة ألف المنع.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص57"},{"id":"m851","text":"العاقل إن منع عذر، وإن منح شكر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m852","text":"الخير كثير، وقليل فاعله.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m853","text":"أصحاب المال والاقتدار كثيرون، والمعين منهم قليل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص57"},{"id":"m854","text":"كريم الطبع يساعد، ولئيم الطبع يعاند.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص57"},{"id":"m855","text":"المخذول من كانت له إلى اللئام حاجة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص58"},{"id":"m856","text":"من أوغرت صدره، استدعيت شره.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص58"},{"id":"m857","text":"لا تطلب الحوائج من غير أهلها، ولا تطلبها في غير حينها، ولا تطلب ما لست له مستحقا، فإنك إن فعلت ذلك كنت حقيقا بالحرمان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m858","text":"كل شيء يحتاج إلى العقل، والعقل يحتاج إلى التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m859","text":"قليل الحيلة أجدى عليك من كثير الشدة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m860","text":"قليل التأني أنفع من كثير العجلة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m861","text":"المستشير معان، والمستشار مؤتمن.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m862","text":"الخيرة في ترك الطيرة، وكفارتها التوكل على الله، وان يقول : اللهم لا يأتي بالخير إلا أنت، ولا يدفع الشر إلا أنت، ولا حول ولا قوة إلا بالله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص58"},{"id":"m863","text":"إن البلاء موكل بالمنطق. شكا يوسف عليه السلام طول الحبس، فأوحى الله تعالى إليه : يا يوسف أنت حبست نفسك، حيث قلت : ( رب السجن أحب إلي) ولو قلت العافية أحب إلي لعوفيت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص58"},{"id":"m864","text":"العقل يأمرك بالأنفع، والمروءة تأمرك بالأجمل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m865","text":"لا تصغرن هممكم، فإني لم أر أقعد عن المكرمات من صغر الهمم.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m866","text":"الهمة راية الجد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m867","text":"علو الهمة يدعو إلى الرفعة، ويأنف من الضعة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m868","text":"اتقوا الإفراط في الأكل، فإنه يؤدي إلى السمنة، والسمنة تخفي جمال البدن.","kind":"hikma","topic":"الصحة والنفس","note":"«السمنة» و«تخفي» على الترجيح من «السمىن» و«ختيف»","source":"شذرات المطوع، ص58"},{"id":"m869","text":"السمنة راية الخمول.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص58"},{"id":"m870","text":"من طال كسله، خاب أمله.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص58"},{"id":"m871","text":"عاجز تزوج كسلانه، ورزق منها ببنتين، حسرة وندامة، وابنين : تعبان وخايب.","kind":"mathal","topic":"الحياة الزوجية","source":"شذرات المطوع، ص58"},{"id":"m872","text":"شرف النفس مع صغر الهمة، خير من علو الهمة مع دناءة النفس.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m873","text":"من علت همته واتضعت نفسه، منع ما يجب عليه وطلب ما لا يستحقه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m874","text":"من شرفت نفسه وصغرت همته، أعطى كل ما يجب عليه، وترك بعض ما يستحق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m875","text":"المروءة : مراعاة المرء لأقوال وأفعال وأحوال ليبلغ بنفسه أفضل منازلها، وينفي عنها القبيح والذم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m876","text":"أحب العفاف إلى الله تعالى : عفاف الفرج، واللسان والبطن.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m877","text":"عار الفضيحة أربى على لذتها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m878","text":"النظرة بعد النظرة، تزرع في القلب الشهوة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m879","text":"العيون سهام الشيطان، يصطاد بها الغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص58"},{"id":"m880","text":"العاقل الحازم من ملك نفسه، حين يرغب وحين يرهب وحين يشتهي وحين يغضب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص58"},{"id":"m881","text":"الشهوة تخدع العقل، فتحسن له القبيح وتزين الباطل بالمديح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص59"},{"id":"m882","text":"ما أمر الله تعالى بشيء إلا وأعان عليه، ولا نهى عن شيء إلا وأغنى عنه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m883","text":"الفتنة نائمة فمن أيقظها صار طعاما لها.","kind":"hikma","topic":"السياسة والقيادة","note":"في المستخرج «ممن»","source":"شذرات المطوع، ص59"},{"id":"m884","text":"كل خاطب كلامه يشوبه الكذب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص59"},{"id":"m885","text":"إن كان الكلام ترغيبا فاقرنه باللين واللطف، وإن كان ترهيبا فاقرنه بالخشونة والعنف.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص59"},{"id":"m886","text":"الاعراض عن الفحش احد النكيرين","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص59"},{"id":"m887","text":"لا تتعجل هما لم يات، فإن أكثر الهموم كاذبة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m888","text":"من قوى صبره لم يفارقه رأيه، ومن ضعف صبره، عزب عنه رأيه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m889","text":"أشد البلاء المفاجئ، وأهونه المنتظر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص59"},{"id":"m890","text":"التوقع يخفف التوجع.","kind":"hikma","topic":"الصبر والشدائد","note":"في المستخرج «يفف»","source":"شذرات المطوع، ص59"},{"id":"m891","text":"المنح والمحن لا تتحرر في الدنيا، ويشوب بعضها بعضا.","kind":"hikma","topic":"الحياة والزمن","note":"«تتحرر» كما في المستخرج، وربما كانت «تتجرد»","source":"شذرات المطوع، ص59"},{"id":"m892","text":"اذكروا أهل البلاء، فتعظم نعم الله في قلوبكم، ويتجدد شكركم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m893","text":"أقروا النعم بالشكر، ولا تنفروها بالجحود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص59"},{"id":"m894","text":"دعوا الأضغان مدفونة، ولا تبعثوها بالتذكر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص60"},{"id":"m895","text":"دعوا الدموع قارة في مآقيها ولا تستفزوها بالتذكر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص60"},{"id":"m896","text":"تذكر الاشجان يبعث الاحزان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص60"},{"id":"m897","text":"من ترك المشورة فقد ودع الحزم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m898","text":"إنما يستشار ذو الرأي الناصح، وذو العقل الراجح، وأهل الخبرة، وأصحاب التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m899","text":"تنجيز الأعمال يحتاج إلى العزم، والعزم يحتاج إلى المشورة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m900","text":"المشورة حصن من الندامة وأمان من الملامة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص60"},{"id":"m901","text":"أمر الله تعالى نبيه صلى الله عليه وسلم بمشاورة أصحابه، ( وشاورهم في الأمر ) في الشئون المهمة، تألفا لهم، وتطيبا لأنفسهم، ولبيان فضل المشاورة، وليستن به ولاة الأمر، والمسلمون، ولتنقية الرأي من الشوائب، وتزكيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص60"},{"id":"m902","text":"من استشار قبل الشروع، فقد أحرز شطر النجاح.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص61"},{"id":"m903","text":"نعم المؤازرة المشاورة، وبئس الاستعداد الاستبداد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m904","text":"المشاورة والمناظرة يجليان الرأي، وينفيان عنه الشوائب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m905","text":"من اتهم رأيه شاور، ومن أعجب برأيه لم يشاور.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m906","text":"من استبد برأيه، أخطأ طريق الصواب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m907","text":"من ابتدأ عمله بالاستشارة، فقد وضع قدمه على أول الطريق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص61"},{"id":"m908","text":"من لم يشاور فهو يرى أول عمله، ومن شاور فهو يرى أول وآخره.","kind":"hikma","topic":"العقل والحكمة","note":"«أول وآخره» كما في الأصل، ولعلها «أوله وآخره»","source":"شذرات المطوع، ص61"},{"id":"m909","text":"من استبد برأيه عميت عليه العاقبة، ومن استشار اتضحت له العاقبة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص61"},{"id":"m910","text":"من استشار أمن من العثار، ومن استغنى برأيه لم يأمن الأخطار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص62"},{"id":"m911","text":"إذا أعجبتك قدرتك على المخلوق، فاذكر قدرة الله عليك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m912","text":"اذا قدرت على خصمك، فقبل الانتقام والعقاب، اذكر الذي أنت بين يديه، أذل منه بين يديك، والذي هو أقدر على عقابك منك على عقابه، فإذا أنت يستهويك العفو.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m913","text":"علاج قسوة القلب : تشييع الجنائز، وزيارة القبور، عيادة المرضى، كفالة اليتيم، مجالسة المساكين وفقراء المسلمين، كثرة ذكر هادم اللذات، حضور مجالس العلم، وحلق الذكر، قراءة الرقائق، عدم الإكثار من أكل اللحوم، الصيام، مسح رأس اليتيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m914","text":"كان أحد الملوك يردع غضبه، بان يلقي بين يديه مفاتيح قبور الملوك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m915","text":"من أكثر من ذكر الموت رضي من الدنيا باليسير.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m916","text":"ليس من عادة الكرام سرعة الانتقام.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m917","text":"ليس من شروط الكرم قطع النعم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m918","text":"ذو المروءة قدره فوق ذنبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m919","text":"إدراك ما عند الله بالعفو، أرجى من العقوبة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص62"},{"id":"m920","text":"إن عاقبت من ظلمك فلك نظير، وإن عفوت عنه فلا نظير لك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص62"},{"id":"m921","text":"برك وإحسانك قرب منك المحسن، وشجع المسئ على الاعتذار.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص62"},{"id":"m922","text":"الكذاب لص العقول، لأن اللص يسرق مالك، والكذاب يسرق عقلك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص62"},{"id":"m923","text":"من اشتهر صدقه كثر صديقه، ومن قل صدقه قل صديقه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص62"},{"id":"m924","text":"رب صدق أربى على الكذب، في القبح والمعرة، والأذى والمضرة، كالغيبة والنميمة، والسعاية والوشاية.","kind":"hikma","topic":"الكلام والصمت","note":"في المستخرج «والمضة»","source":"شذرات المطوع، ص62"},{"id":"m925","text":"الغيبة مرعى اللئام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m926","text":"الغيبة فاكهة النساء.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m927","text":"الغيبة شرُ لا خير فيه : شرُ لقائلها، ولا خير فيها لمن قيلت فيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m928","text":"سئل رجل : ما الشر الذي لا خير فيه ؟ فقال : ما ضرني ولم ينفع غيري، أو ضر غيري ولم ينفعني.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص63"},{"id":"m929","text":"قيل في موارد الحكم : لا تبد من العيوب، ما ستره علام الغيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m930","text":"اللئيم إذا غاب عاب، وإذا حضر اغتاب.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m931","text":"ازرع المحبة في قلوب الناس بالتحية والسلام، واسقها بالهدايا ولين الكلام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص63"},{"id":"m932","text":"المؤمن يغبط، والمنافق يحسد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m933","text":"احذروا فضول المنطق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m934","text":"تجنب في كلامك، ما يسخط السلطان ويوحش الإخوان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m935","text":"مقتل الرجل بين فكيه.","kind":"mathal","topic":"الكلام والصمت","source":"شذرات المطوع، ص63"},{"id":"m936","text":"استحي من الله تعالى، استحياءك من ذوي الهيبة من قومك.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص63"},{"id":"m937","text":"احتمال السفيه خير من التحلي بصورته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m938","text":"الإعراض عن الجاهل خير من مشاكلته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m939","text":"ما أفحش حليم، ولا أوحش كريم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص63"},{"id":"m940","text":"قيل لملك : فلان يطعن فيك، فلو عاقبته، فقال : هو بعد العقوبة أعذر في طعني، فكان هذا تفضلا وتأليفا منه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص64"},{"id":"m941","text":"من خاصمك إن كان فوقك، فاعرف له قدره، وان كان دونك، فارفع قدرك عنه، وان كان نظيرك فتفضل عليه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص64"},{"id":"m942","text":"أحمق الناس من ظن أنه أعقل الناس.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص64"},{"id":"m943","text":"أعقل الناس من لم يتجاوز الصمت في عقوبة الجهال.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص64"},{"id":"m944","text":"قال الشعبي : ما أدركت أمي فأبرها، ولكن لا أسب أحدا فيسبها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص64"},{"id":"m945","text":"في إعراضك صون أعراضك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m946","text":"اردع السفيه بالحلم، والظالم بالعفو، والقاطع بالوصل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m947","text":"أكرم الشيم أرعاها للذمم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m948","text":"من أتسع غضبه ضاق كيده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m949","text":"غضب الجاهل في قول، وغضب العاقل في فعله.","kind":"hikma","topic":"العقل والحكمة","note":"«قول» كما في المستخرج، ولعلها «قوله»","source":"شذرات المطوع، ص64"},{"id":"m950","text":"أبلغ جواب على السفيه الصمت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص64"},{"id":"m951","text":"الحلم ضبط النفس عند هيجان الغضب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m952","text":"أكرموا سفهاءكم، فإنهم يقونكم العار والشنار. ( العيب ).","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص64"},{"id":"m953","text":"لا يعدم مسئ مكافئا، ولا يعدم محسن مجازيا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m954","text":"دخل بيتا ما خرج منه. أي : إن خرج منه خير دخله خير، وإن خرج منه شر دخله شر.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص64"},{"id":"m955","text":"من كثر شططه كثر غلطه. ( الشطط : مجاوزة الحد )","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص65"},{"id":"m956","text":"في إغضائك راحة أعضائك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m957","text":"الغضب يتحرك من داخل الجسد إلى خارجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m958","text":"الحزن يتحرك من خارج الجسد إلى داخله.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m959","text":"الحادث عن الغضب السطوة والانتقام، وهو لا يقتل صاحبه لبروزه وخروجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m960","text":"الحادث عن الحزن المرض والأسقام لاستقراره، وقد يقتل صاحبه، أو يذهب ببصره لكمونه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m961","text":"يا ابن آدم اذكرني حين تغضب، أذكرك حين أغضب.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص65"},{"id":"m962","text":"الغضب يتناقص قبل الحزن، والحزن يتزايد ثم يتناقص.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m963","text":"موارد تسكين الغضب : ذكر الله تعالى، الاستعاذة، الوضوء، تغيير المكان، تغيير الهيئة من قيام إلى الجلوس مثلا، التذكير بقدرة الله تعالى، التذكير بفضل العفو وثواب التجاوز، التذكير بمغبة الغضب، وما يلحقه من الندم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص65"},{"id":"m964","text":"العجب ثمرة التفوق والكبر ثمرة العجب، والكفر ثمرة الكبر.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m965","text":"آفة التفوق العجب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m966","text":"أول الكفر التكبر، وأول التكبر العجب، وأول العجب التميز.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص65"},{"id":"m967","text":"الكبر من المنزلة، والعجب من الفضيلة.","kind":"hikma","topic":"الأخلاق والآداب","note":"في المستخرج «املنلة»","source":"شذرات المطوع، ص65"},{"id":"m968","text":"الإنسان ابن التراب، ويأكله التراب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص65"},{"id":"m969","text":"قابل المدح كمادح نفسه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص65"},{"id":"m970","text":"لما وصفت بالكرم سررت مع علمي بأني لست بكريم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m971","text":"لما وصفت بالبخل، حزنت مع علمي بأني بخيل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m972","text":"إياكم والتمادح فإنه الذبح الخفي.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص66"},{"id":"m973","text":"النفس يستهويها الثناء، وتميل إلى استماع المدح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m974","text":"الإنسان بطبعه يحب المدح وان لم يوافق الحق. ويكره القدح وإن وافق الحق.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص66"},{"id":"m975","text":"لم يكد يسلم مادح ولا قادح من شوائب الكذب في ثنائه وتعداده.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص66"},{"id":"m976","text":"عاشر أهلك بأحسن أخلاقك، فإن الثواء فيهم قليل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص66"},{"id":"m977","text":"من حسنت أخلاقه كثر أصدقاؤه، وقل أعداؤه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص66"},{"id":"m978","text":"حسن الخلق وحسن الجوار تعمران الديار، ويزيدان في الأعمار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص66"},{"id":"m979","text":"من تاه في ولايته، ذل في عزله.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m980","text":"من ولي فقد عزل، لأن العزل لا يكون إلا بعد ولاية.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m981","text":"الولاية حلوة الرضاع، مرة الفطام.","kind":"mathal","topic":"السياسة والقيادة","source":"شذرات المطوع، ص66"},{"id":"m982","text":"جند الله الأعظم : الفقر والمرض والهم والهرم والموت، يذل الله بهم كل جبار عنيد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص66"},{"id":"m983","text":"لولا أن الله أذل ابن آدم بثلاث ما طأطأ رأسه لشيء : الفقر والمرض والموت","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص66"},{"id":"m984","text":"إذا أقبلت عليك جيوش الهموم، فادفعها بجيوش الرجاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m985","text":"إذا أحدق بك الغم، وأحاط بك الحزن، فاطرده بجميل الأمنيات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m986","text":"إذا تتابع البلاء، فقعقع له باب الدعاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص67"},{"id":"m987","text":"الأماني رأس مال المفلس.","kind":"mathal","topic":"العقل والحكمة","source":"شذرات المطوع، ص67"},{"id":"m988","text":"زينة الحياة : الصحة والشباب.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص67"},{"id":"m989","text":"من كساه الحياء ثوبه لم ير الناس عيبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m990","text":"افعل ما تحب أن تراه من غيرك، واجتنب ما تكره أن تراه من غيرك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m991","text":"من هتك ستر الله عنه فلا غيبة له.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m992","text":"من خلع جلباب الحياء فلا غيبة له.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m993","text":"الإحسان رق، والمكافأة عتق.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص67"},{"id":"m994","text":"السخاء حسن الفطنة، واللؤم سوء التغافل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص67"},{"id":"m995","text":"من بذل ماله أدرك آماله.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص67"},{"id":"m996","text":"بالإحسان يسترق الإنسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص67"},{"id":"m997","text":"من بذل مرافقه أحبه مرافقه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m998","text":"تهوى الرجل حيث يهوى القلب.","kind":"mathal","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m999","text":"قال المسئول للسائل : أعدك اليوم، وأحبوك غدا، لتذوق حلاوة الأمل، وأتزين بثوب الوفاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1000","text":"قيل لكريم أتعد وأنت قادر على الإنجاز ؟ فقال :إن الحاجة إذا لم يتقدمها وعد يرجى، لم يعظم سرورها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1001","text":"الإنجاز بعد الوعد، كالطعام بعد الذوق، فليس من فاجأه الطعام، كمن يجد ريحه وطعمه ثم ينال منه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1002","text":"دع الحاجة تختمر بالوعد، ليكون لها طعم عند الممنوح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1003","text":"لطف الله بالمخلوقات، سبق الآباء والأمهات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1004","text":"من كثر حياؤه كثر أحباؤه، ومن قل حياؤه قل أحباؤه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1005","text":"البشر ولين الكلام أيسر مبذول، لاكتساب الأصدقاء، والوقاية من الأعداء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m1006","text":"من فتح له باب خير فلينتهزه، فإنه لا يدري متى يغلق عليه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص68"},{"id":"m1007","text":"الكريم يستر معروفه، وينشر معروف غيره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1008","text":"لا خير في معروف يعدَّد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1009","text":"المن يفسد المعروف، كما يفسد الخلُّ العسل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1010","text":"الإنسان أسير الإحسان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص68"},{"id":"m1011","text":"الشكر أبقى للنعم، والكفر يزيلها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1012","text":"المحراث مفتاح خزائن الأرض.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1013","text":"انتظار الفرج من الله بالصبر عبادة.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1014","text":"من رضي من الله بالقليل من الرزق، رضي الله منه بالقليل من العمل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1015","text":"قد يعصي العبد خالقه ليدرك الغنى، ويهرب من الفقر، ولا ينعكس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1016","text":"يعصى الله لطلب الغنى، ولا يعصى لطلب الفقر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1017","text":"من جمع الفضول حسابه يطول.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1018","text":"إن المكروه يسهل بالتمرين.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1019","text":"من أراد الله به خيرا، جعل شهوته منقادة له.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1020","text":"من لم يرد الله به خيرا جعله منقادا لشهوته.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1021","text":"إذا أراد الله أن يرذل عبده سلط عليه شهوة البطن والفرج.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1022","text":"لن يفلح من كان همه في شهوة بطنه وفرجه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص68"},{"id":"m1023","text":"المال آلة للمكارم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1024","text":"نعم العون على المجد اليسار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1025","text":"المال يكسب صاحبه الهيبة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1026","text":"الفقر مخذلة، والغنى مجذلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1027","text":"من أحسن الظن بربه أراح قلبه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1028","text":"الرجاء حسن الظن، والقنوط إساءة الظن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص68"},{"id":"m1029","text":"قتل القنوط صاحبه.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص68"},{"id":"m1030","text":"الدنيا إن بقيت لك، لا تبقى لها.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات المطوع، ص68"},{"id":"m1031","text":"من حسن عزاء الورثة، كثرة ما خلف لهم ميتهم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1032","text":"الغنى البخيل كالقوي الجبان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص68"},{"id":"m1033","text":"كف بصرك عن عورات الناس، ولسانك عن عيوبهم، فإن لك فيها شغلا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص68"},{"id":"m1034","text":"القناعة عز المعسر، والصدقة حرز الموسر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1035","text":"القناعة حلية الفقر، والشكر حلية الغنى.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1036","text":"من رضي بالكفاف تزين بالعفاف.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1037","text":"من رضي برزقه قرَّت عينه، وطابت نفسه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1038","text":"خير الرزق ما كان فوق الإقتار، ودون الإبطار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص70"},{"id":"m1039","text":"الأدب مكتسب، ولكل قوم مواضعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1040","text":"قيل لحكيم : من أدبك ؟ فقال ما أدبني أحد، ولكني رأيت في الناس خصالا حميدة فحاكيتها، وخصالا رذيلة فجانبتها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1041","text":"من أدب أبناءه، فقد أدب أحفاده.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1042","text":"الأدب أدبان : تأديب الوالدين لأولادهم في الصغر، ثم تأديب الأولاد لأنفسهم في الكبر.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1043","text":"أثني على أحفاد حكيم في أدبهم وأخلاقهم، فقال : أنا أدبتهم وعلمتهم، فقيل له : كيف وأنت لم تساكنهم وتخالطهم، فقال : أنا أدبت آباءهم، وآباؤهم أدبوهم، فكأني أدبتهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1044","text":"الأدب يورث.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1045","text":"بادروا بتأديب الأطفال، فطينتهم لينة، سريعة القبول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1046","text":"تداركوا تعليم الأطفال قبل تراكم الأشغال.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1047","text":"اتهم نفسك، ولا تجعلها موضع ثقة منك، إذا زينت لك وطوعت.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1048","text":"احترز من نفسك، كما تحترز من عدوك، فهي أعدى أعدائك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1049","text":"كيف يسلم الإنسان من عدو بين ضلوعه ؟.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1050","text":"( نعوذ بالله من شرور أنفسنا، ومن سيئات أعمالنا ) رقية الاحتراز من غوائل النفس.","kind":"hikma","topic":"الإيمان والعبادة","note":"دعاء","source":"شذرات المطوع، ص70"},{"id":"m1051","text":"من رضي عن نفسه كثر الساخطون عليه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1052","text":"الشديد من غلب نفسه، والقوي من غلب هواه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص70"},{"id":"m1053","text":"لا تغتر بثناء من يجهل سرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص70"},{"id":"m1054","text":"من أشرك أو تكبر فقد حجب نفسه عن رحمة الله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص70"},{"id":"m1055","text":"من أطاع الله تعالى فقد استقبل الجنة، ومن عصى الله فقد استدبرها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص70"},{"id":"m1056","text":"لا يغرك ثناء من يخفى عليه سرك، عمن لا يخفى عليه سرك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص70"},{"id":"m1057","text":"قال حكيم : فلان أدب أولاد أولاده بعد رحيله، قيل له : كيف ذلك ؟ قال : هو أدب أولاده، وأولاده أدبوا أولادهم، فكأنه هو الذي أدبهم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص70"},{"id":"m1058","text":"ينشأ الكبر من الشعور برفعة المنزلة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1059","text":"ينشأ العجب من الشعور بالأفضلية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1060","text":"الكبر يكسب المقت، والعجب يكسب الاحتقار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص70"},{"id":"m1061","text":"أصلح نفسك لنفسك يكن الناس أتباعا لك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1062","text":"أفضل الملوك من أبقى بالعدل ذكره، واستعمله الناس بعده.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1063","text":"من غلب نفسه غلب غيره ومن غلبته نفسه غلبه غيره.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1064","text":"كن من مباح الشهوات بين منع وتمكين، لتضبط شهوتك، وتنال لذتك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1065","text":"من قوي على نفسه عظمت قوته ومن صبر على شهوته عظمت مروءته.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص72"},{"id":"m1066","text":"الإستئثار يدعو إلى البغضة، والمواساة تدعو إلى المحبة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص72"},{"id":"m1067","text":"ما أحببت أن توصف به فأته، وما كرهت أن توصف به فاجتنبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص72"},{"id":"m1068","text":"عدل الوالي يعدل خصب الزمان.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1069","text":"من ستر زلته، حفظ هيبته، ومن عرفت زلته نقصت هيبته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص72"},{"id":"m1070","text":"الدين يصلح سرائر القلوب، ويمنع من ارتكاب الذنوب، ويبعث على العدل والتناصف، ويدعو إلى الألفة والتعاطف.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص72"},{"id":"m1071","text":"أي بلد كثرت ثماره ومزارعه، استقل بخيره، وفاض على غيره، فصارت الأموال إليه تجلب، والأقوات منه تطلب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص72"},{"id":"m1072","text":"أطوار الدولة : تبدأ بقوة وبطش لحمل الناس على الطاعة والانقياد، ثم تتوسط باللين والاستقامة، لاستقرار الأمر واستتباب الأمن، ثم تختم بإنتشار الجور والضعف والاضمحلال.","kind":"hikma","topic":"السياسة والقيادة","note":"في الأصل «واستباب»","source":"شذرات المطوع، ص72"},{"id":"m1073","text":"من عمر بيت المال من ظلم رعيته، كمن طين سطحه من قواعد بيته.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1074","text":"أحسنوا إلى المزارعين، فإنكم لا تزالون سمانا ما سمنوا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1075","text":"سعادة الرعية في طاعة الوزراء، وسعادة الوزراء في طاعة الملك، وسعادة الملك في طاعة ملك الملوك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1076","text":"الجند أعداء ينتقم بهم من أعداء. أي أعداء إن فسدوا، وينتقم بهم من أعداء إذا صلحوا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1077","text":"قال حكيم لملك : جنودك أعداؤك، وأعداء أعدائك. قال كيف ذلك : قال إن أسأت إليهم وأهملتهم فهم أعداؤك، وإن أحسنت إليهم وراعيتهم فهم أعداء أعدائك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1078","text":"من تنعم بإحسانك، أشفق على سلطانك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1079","text":"المطالب بحقه جرئ، وصاحب الحاجة أرعن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص72"},{"id":"m1080","text":"لا يكون الظلم علة لوجود الصلاح.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1081","text":"لا يكون العدل علة لوجود الفساد.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1082","text":"لا يستغنى الملك عن الكفاة ولا الكفاة عن الإفضال، ولا الإفضال عن المادة، ولا المادة عن العدل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص72"},{"id":"m1083","text":"من غفلة السلطان، الرضا عمن يستوجب السخط، والسخط على من يستحق الرضا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص73"},{"id":"m1084","text":"العينان دليلان، والأذنان مخبران، واللسان ترجمان، واليدان آلتا معالجة وعمل، والرجلان آلتا مواصلة وحمل، والعقل آلة كف ولجام، والبطن وعاء الوقود والطاقة، والحواس أجهزة استكشاف وتعرف، والقلب ملك الجوارح.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص73"},{"id":"m1085","text":"من أعتمد على كفاة السوء، فسد رأيه، وكذب ظنه، وطمع فيه عدوه.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1086","text":"التغاضب أحمد مغبة من الغضب، لأن المتغاضب يملك نفسه، ويقف عند الحد المطلوب، والغضبان لا يملك نفسه، ولا يقف عند الحد المطلوب.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص74"},{"id":"m1087","text":"عقوبة الأدب محمودة، وعقوبة الغضب مذمومة.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1088","text":"بالصبر على المكروهات، تدرك المرغوبات.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص74"},{"id":"m1089","text":"لن تنال ما تحب، حتى تصبر على ما تكره.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات المطوع، ص74"},{"id":"m1090","text":"الحوائج تطلب بالعناء، وتدرك بالقضاء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص74"},{"id":"m1091","text":"يجب على الناصح الاجتهاد ولا يجب عليه ضمان النجح، لأن أقضية الله خافية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1092","text":"المستشار مؤتمن وليس بضامن.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1093","text":"من لام المشير، بقي بلا مشير.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص74"},{"id":"m1094","text":"لو علم الملوك، مقدار حاجتهم إلى أهل الرأي والعلم، لما كان عجبا أن ترى مواكب الملوك على أبواب العلماء.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص74"},{"id":"m1095","text":"الطبيب الذي يرحم عليله من مرارة الدواء، كالأب الذي يرحم ابنه من عناء التعليم، فكلاهما يضر من حيث يرى أنه ينفع.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1096","text":"الفضائل والأخلاق لها مقادير ومواضع، فإن صادفت مقاديرها وحلت في مواضعها حمدت، وإن لم تصادف مقاديرها أو لم تحل في مواضعها لم تحمد.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص74"},{"id":"m1097","text":"روادع الظلم والاعتداء : • الوازع الديني : التقوى والخوف من الله تعالى، والخوف من العقاب الأخروي. • الوازع الأخلاقي : المحافظة على سمعته، وسمعة عشيرته، وعلى مكانته في المجتمع. • العجز فلا يستطيع أن يظلم، وعدم القدرة من العصمة. • الخوف من العقوبات، وإقامة الحد الشرعي، والخوف من بطش السلطان.","kind":"hikma","topic":"الأخلاق والآداب","note":"في الأصل «وسمعت عشيرته»","source":"شذرات المطوع، ص74"},{"id":"m1098","text":"شرعت العقوبات، والحدود والتعزيرات، للقادر الذي ليس لديه رادع من نفسه، و ليس لديه وازع ديني، ولا وازع أخلاقي.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1099","text":"عقوبة الأدب أحمد عاقبة من عقوبة الغضب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات المطوع، ص74"},{"id":"m1100","text":"تعطيل الحدود، وإهمال العقوبات، يثير المفسدين، ويجرئ المجرمين.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص74"},{"id":"m1101","text":"الرأفة لا تحمد، إذا أفضت إلى ترك الحدود، وإضاعة الحقوق.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1102","text":"الحزم : أن تحذر المكروه الذي يمكن حدوثه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1103","text":"العجز : أن تأمن المكروه الذي يمكن حدوثه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1104","text":"تجاوز الحد نقص في المحدود. مثال : الكرم إذا جاوز حده صار إسرافا، فيصير نقصا في صفة الكرم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1105","text":"من عادة الملوك أن لا تعد ولا تتوعد، لأنها قادرة على ثواب المحسن، وعلى عقاب المسئ في الحال.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1106","text":"الملوك تستغني بالفعل عن القول، وإذا قالت فإنما هي تأمر بتنجيز الفعل فمآل أقوالها أفعال حاضرة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص76"},{"id":"m1107","text":"الخيرة في ترك الطيرة.","kind":"mathal","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1108","text":"من أصلح نفسه أرغم أنف عدوه.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1109","text":"أصلح نفسك لنفسك، تكن متبوعا.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1110","text":"إذا كان الزهد يضعف صاحبه، عن الطاعات وإتيان القربات، كان الزهد في الزهد هو الزهد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1111","text":"إذا كان الزهد يضعف عن فعل الطاعات أو يؤدي إلى الرياء، كان ترك الزهد هو الزهد.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص76"},{"id":"m1112","text":"الزهد يمنع من المباح، والحمية تمنع من الطيب، والحياء يمنع من القبيح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1113","text":"الإفراط في الأكل، يؤدي إلى البطنة، والبطنة داعية للسقم والكسل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1114","text":"نعم الدواء الوقاية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1115","text":"نعم الدواء تقدير نسب الغذاء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1116","text":"نعمت الحمية الاقتصاد في الأكل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1117","text":"إطعام الطعام حلية المروءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1118","text":"موائد الكرام مقابر العيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1119","text":"ما رأيت أستر للعيوب، من إطعام البطون، وملء الجيوب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1120","text":"رب أكلة أضرت بالآكل، وحرمته أطيب المآكل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1121","text":"يكفيك من الطعام ما ملأ ثلث بطنك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1122","text":"من أكل بثلث بطنه، أمن البطنة والكسل، ومن أمن من البطنة والكسل، لازمته الصحة والعمل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1123","text":"اتق لبستين : المشهورة، والمحقورة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1124","text":"ليس العزة في حسن البزة.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1125","text":"جنبوا ثيابكم العري الفادح، والزي الفاضح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1126","text":"البس من الثياب ما يخدمك، لا ما يستخدمك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1127","text":"البس من الثياب ما يقيك لا ما تقيه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص76"},{"id":"m1128","text":"نومة الصبحة معجزة منفخة مكسلة، مورمة مفشلة منساة للحاجة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1129","text":"قليل الرقاد يعين على تحقيق المراد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص76"},{"id":"m1130","text":"الليل أجمع للفكر، وأخطر للخاطر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1131","text":"من كثر اعتباره، قل عثاره.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1132","text":"طوبى لمن تأمل في أفعال غيره، فاقتدى بأحسنها، وتجنب سيئها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1133","text":"نفسك مطيتك فأرفق بها، ولا تتعبها ، حتى تبلغك غايتك.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص76"},{"id":"m1134","text":"ربما كان حكم الإنسان على غيره، أصوب من حكمه على نفسه، لأن حكمه على نفسه لا ينفك من هوى النفس، ومن حسن الظن بها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1135","text":"طلب ما لا يدرك عجز.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1136","text":"إذا هممت بأمر ففكر في عاقبته، فإن كان رشدا فأمضه، وإن كان غيا فانته عنه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص76"},{"id":"m1137","text":"لا تجاهر الناس بالمخالفة فيعادوك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1138","text":"من عرف عيوبه، فلا يلم من عابه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1139","text":"من أعمل جده بلغ أمنيته.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص78"},{"id":"m1140","text":"كفى بما يعتذر منه تهمة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1141","text":"شفيع المذنب إقراره، وتوبته اعتذاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1142","text":"من لم يقبل توبة من أساء، فقد أساء .","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1143","text":"عفو الكريم أوسع من ضيق المعذرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1144","text":"من كانت أغلب خصاله الحدة، فلا تغتر منه بالمودة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1145","text":"المحسن على المسئ أمير.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1146","text":"الكف عن الإساءة إحدى التوبتين، والإقلاع عن الباطل أحد العذرين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1147","text":"وقوف المرض أحد البرءين، وكفه عن الزيادة إحدى الصحتين.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص78"},{"id":"m1148","text":"من سقم منه عضو من أعضاءه، فإن لم يعالجه، سرى السقم إلى الأعضاء الصحيحة وإن عالجه سرت الصحة إلى العضو السقيم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص78"},{"id":"m1149","text":"من سل سيف البغي كان غمده.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1150","text":"تسامحوا في الحقوق، فإن الاستيفاء موحش، والاستقصاء منفر.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1151","text":"جبلت النفوس على مقت من شاحها وشاقها، وعلى حب من ياسرها وسامحها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1152","text":"أولى الأمور بالشرف والمروءة، استعطاف النفوس بالمياسرة والمسامحة، وتألفها بالمقاربة والمساهلة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1153","text":"عبدي حرك يديك ورجليك، أكسو بدنك، وأطعم شفتيك.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات المطوع، ص78"},{"id":"m1154","text":"من عاشر الناس بالمسامحة، أمن شرهم، ونال ودهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1155","text":"من المروءة التغابن للضعيف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1156","text":"إذا كان البائع ضعيفا، دع الاستقصاء في السوم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1157","text":"الآداب ميراث الأشراف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص78"},{"id":"m1158","text":"إذا أراد الحاكم أن تطاوعه الرعية على شيء من الحق، فعليه أن يبسط لهم شيئا من الدنيا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص78"},{"id":"m1159","text":"إذا أردت أن تطاع في إخوانك وتحترم، فاسلك بهم طريق الجود والكرم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص78"},{"id":"m1160","text":"إن الله تعالى أحسن إلى الناس قبل أن يأمرهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات المطوع، ص78"},{"id":"m1161","text":"صونوا أحسابكم بأموالكم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1162","text":"ذبوا بأموالكم عن أحسابكم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص78"},{"id":"m1163","text":"منزلة المال من العرض، منزلة الخادم من المخدوم.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات المطوع، ص80"},{"id":"m1164","text":"اقطع لسان الشاعر بالمال.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات المطوع، ص80"},{"id":"m1165","text":"بر الشاعر من بر الوالدين، حتى لا يتعرض لهما بسوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص80"},{"id":"m1166","text":"من صنف كتابا أو عمل ديوانا، فقد استهدف، فإن أحسن فقد استعطف، وان أساء فقد استقذف.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات المطوع، ص80"},{"id":"m1167","text":"من استعان بأصاغر رجال، على أكابر أعمال، فقد ضيع العمل، وأوقع الخلل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات المطوع، ص80"},{"id":"m1168","text":"بالمعالجة يصلح الفاسد، وبالإهمال يفسد الصالح.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص80"},{"id":"m1169","text":"عذل يكفك عن سوء، خير لك من ثناء يجعلك تتمادى في السوء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات المطوع، ص80"},{"id":"m1170","text":"من ملك نفسه عند الشهوات والشبهات والهفوات، فقد حاز شطر المروءة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1171","text":"الحصر خير من الهذر، لأن الحصر يضعف الحجة والهذر يتلف المهجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1172","text":"فوائد الصمت : يكسبك صفو المحبة، ويؤمنك سوء المغبة، ويلبسك ثوب الوقار، ويكفيك مؤونة الاعتذار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1173","text":"قال حكيم : ندمت على الكلام، ولم أندم على السكوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1174","text":"كلام المرء يعبر عن عقله.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1175","text":"الأصل في الإنسان الصمت، والكلام عارض للحاجة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1176","text":"الكلام بالقصد والمعالجة، والسمع بلا معالجة، وقد يحصل بلا قصد.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1177","text":"كلام الرجل رسول عقله، ووافد أدبه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1178","text":"من كثر كلامه، ظهر خلله، وبان زلله، إلا أن يكون ملهما مفوها.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1179","text":"الصمت نوم، والكلام يقظة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1180","text":"ما أشبه الجاهل الصامت بالحكيم الساكت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1181","text":"من رام الإكثار، لم يأمن العثار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1182","text":"من لم يكن كلامه حكما فهو لغو.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1183","text":"ومن لم يكن سكوته تفكرا فهو سهو.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1184","text":"ومن لم يكن تفكره اعتبارا فهو لهو.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات المطوع، ص80"},{"id":"m1185","text":"من تكلم ورام الإكثار لم يأمن الإضجار.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1186","text":"كثرة الأيمان من قلة الإيمان.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1187","text":"دع ما يسبق إلى القلوب إنكاره، وإن كان عندك اعتذاره.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1188","text":"أعظم الخطايا اللسان الكذوب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1189","text":"يجب مراعاة التناسب بين المعاني والمباني وطريق الأداء.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1190","text":"في الوعد والترغيب يراعى عذوبة الكلام، ولين الصوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1191","text":"في الوعيد والترهيب يراعى غلظة الكلام، وجهارة الصوت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1192","text":"لا توعد على ذنب بأكثر من عقوبته، لأنك إن فعلت أثمت، وإن تركت كذبت.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات المطوع، ص80"},{"id":"m1193","text":"إذا غضب الرجل ذهب شطر عقله، فلا يأمن من الزلل.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات المطوع، ص80"},{"id":"m1194","text":"من لم يقبل التوبة، فهو أحوج إلى التوبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات المطوع، ص80"},{"id":"m1195","text":"إن أردت السعادة وراحة البال، فلا تقف عند كل مقال، ولا تجعل من كل موقف نزاع، ولا تُمعن النظر في زلّات من حولك، ولا تكشف ما سُتر، ولا تفتح ما أُقفل، ولا تُفتّش عن النوايا، ولا تُرهق نفسك بتفاصيل لا تنفع، خذ من الناس ظاهر خيرهم، ودع خفاياهم لربهم، وسِرْ في الحياة مطمئنَّ القلب، واسع البال، قليل النقد والتعليق والمقال، لين العريكة سهل الطبيعة والطريقة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1196","text":"الرحمةُ والتواضعُ والكلمةُ الطيبةُ، زادُ القلوبِ الطاهرة، وأجملُ ما يتركهُ الإنسانُ في أرواحِ الآخرين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1197","text":"اقتراحُ الشيءِ على الكمالِ شيء سهلٌ، لكنَّ إيجاده على ذلك صعبٌ، فالتمنّي صفاءُ النَّفس، وأمّا نيلُ المُتمنّى فهو صفاءُ العَقل مع الجِدِّ، إذ بين الحُلمِ والبلوغِ مسافةُ جِدٍّ، لا يقطعُها إلا من جمعَ نُورَ الرؤيةِ إلى صبرِ السعي.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1198","text":"الوقاية خير من العلاج والاحتياط خير من الألم والندم والعياط.","kind":"hikma","topic":"الصحة والنفس","note":"قالها تعقيبًا على حديثي تغطية الإناء وإيكاء السقاء","source":"شذرات (ملف وورد)"},{"id":"m1199","text":"‏التدقيقُ في كلِّ صغيرةٍ وكبيرة، والمحاسبةُ على النقيرِ والقطمير، والمقاصّةُ في كلِّ موقفٍ وكلمة، تُفسدُ صفوَ العِشرة، وتُبدِّدُ وُدَّ الأزواجِ والأصحاب. فالسكوتُ أحمدُ عاقبة، والتغافُلُ عقلُ الحكماءِ، يُطفِئُ نارَ الشرِّ، ويُبقي على نورِ المودَّة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1200","text":"اجماع العلماء حجة قاطعة، واختلافهم رحمة واسعة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1201","text":"قليلُ الخبرةِ يسقطُ في الحفرة وقليلُ الحيلةِ حبالهُ قصيرة وقليلُ البصيرةِ تضلُّهُ المسيرة وقليلُ التدبيرِ يسقطُ في البير قليل الهمة لا يبلغ القمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1202","text":"العلم نور والجهل ظلمات","kind":"mathal","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1203","text":"بالعلم ترقى الأمم وبالأخلاق تبلغ القِمم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1204","text":"أركان الشكر: شكر القلب: بتصور النعمة من الله. شكر اللسان: بالثناء والحمد على الله. شكر الجوارح: ألا يستعملها في معصية الله. وهذه كلها تجتمع بقول (الحمد لله)","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1205","text":"الحرية الإيجابية تاجٌ على الرؤوس، لا يُقدَّر بثمن ولا يُشترى بذهب، بها يُشرق الوجه وتزدهر الحياة. فإذا أُسرت الأرواح خلف القضبان، ضاقت الأرض بما رحبت، وغدت القيود حدودًا وسدودًا، تكسر الإرادة وتُطفئ الشعلة. الحرية حياة ونشاط، والسجن موتٌ بطيء، فمن عاش بلا حرية فكأنما عاش بلا نفس ولا وجود.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1206","text":"منهجُ القرآن دقيقُ البناء، بديعُ الأسلوب، يجمع بين التحفيز والترهيب في توازنٍ لا يختلّ؛ فهو يحفزك على عمل الصالحات لتكون من أهل الجنات، ويرسم لك طريق الرحمة والرضوان، ويُزجرك عن المعاصي والسيئات صيانةً لك من العذاب والهوان، فمنهجه قائمٌ على الترغيب والترهيب؛ ترغيبٍ يفتح أبواب الأمل، وترهيبٍ يغلق سُبل الزلل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1207","text":"إذا ابتُليت بجار السوء، فادعُ الله له في سجودك: ( اللهم أسعده وأبعده، اللهم أدخله الجنة )","kind":"hikma","topic":"العلاقات والناس","note":"تعقيب على حديث الشاكي من جاره","source":"شذرات (ملف وورد)"},{"id":"m1208","text":"نبي الله يوسف عليه السلام، لم يتعجل الخروج من السجن، وإن فُتحت له الأبواب، حتى يُعلن للناس براءته أولًا، فيخرج طاهر السيرة نقي السريرة، أراد أن يغادر القيدَ مرفوع الرأس والهامة، لا مطأطأه، وأن يخرج بعزّ الحق لا بعفو السلطان، ليبقى مثالًا لمن آثر الكرامة على العجلة، والبراءة على الحرية الناقصة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1209","text":"الصغير بالقرآن كبير","kind":"hikma","topic":"الإيمان والعبادة","note":"تعقيب على قصة عمرو بن سلمة في إمامته قومه صغيرًا","source":"شذرات (ملف وورد)"},{"id":"m1210","text":"ما خاب من استخار ولا ندم من استشار ولا ضَلَّ من سأل ولا جهل من تعلم ولا زاغ في الظلماء من شاور الحكماء ولا عَلِقَ في الطين من سأل المجربين ولا ضاع في الصحراء من عرف نجوم السماء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1211","text":"وهكذا كثير من الناس، يرفضون الفكرة لا لخطئها، بل لأن قائلها بلا لقب بارز مشهور، ولو جاءت الفكرة الخاطئة من مشهور لقبلها، بدون تفكير ولا تدبر.","kind":"hikma","topic":"العقل والحكمة","note":"تعقيب على قصة الأعرابي والحمل","source":"شذرات (ملف وورد)"},{"id":"m1212","text":"إذا أردت أن يختفي العيب والشيب، ويكون العدو صديقا، والبعيد قريبا، فأخرج ما في المحفظة والجيب، فتجلب الثناء في المحافل والحضور والغيب.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1213","text":"لا تُصَدِّقِ المَدْحَ لِحَلاوَتِهِ، ولا تُكَذِّبِ القَدْحَ لِمَرارَتِهِ، ولكنِ اجتهِدْ لِتَكونَ أَهْلًا لِلمَدْحِ، وتَنْفِيَ عنكَ أَسْبابَ القَدْحِ، فخيرُ الثناءِ ما صدّقه العملُ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1214","text":"اطْلُبْ مَحَبَّةَ الناسِ بالإحسانِ إِلَيْهِم، وتَوْقيرَهُم باحترامِهِم، وثناءَهُم بإكرامِهِم، فالكلمةُ الطيبةُ صدقةٌ، وأَسْرَعُ طريقٍ إلى القلوبِ حُسْنُ الخُلُقِ.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1215","text":"ما تَتَمَنّى عِندَ حُضُورِ أَجَلِكَ لو أَنَّكَ فَعَلْتَهُ، فافعَلْهُ الآن، وما تَتَمَنّى لو أَنَّكَ أَقْلَعْتَ عنهُ، فاقْلَعْ عنهُ الآن، فالعُمْرُ ظلٌّ زائل، والسعيدُ من تابَ قبلَ الفواتِ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1216","text":"إن الله ضمن للطيور أرزاقها، فوهب لها الأجنحة وحاسة الشم والبصر، كي تهتدي إلي أرزاقها، وغدوها ورواحها أنفع لها ولصحتها، من أن يرزقها في أعشاشها، لأنه سيؤول بها إلى العجز والخمول والوهن، فمن وهب الطير الجناحين، فقد أمره قدرا بالغدو والرواح، ليسعى على نفسه وفراخه، وهكذا تسير عجلة الحياة، وفق الحكمة الإلهية.","kind":"hikma","topic":"الإيمان والعبادة","note":"تحت عنوان: تعرف على حكمة الله من مخلوقاته","source":"شذرات (ملف وورد)"},{"id":"m1217","text":"المعنى واحد، لكن الأسلوب والصياغة تصنع الفارق البين، في التعبير ووقع الكلام على نفس ومشاعر السامع.","kind":"hikma","topic":"الكلام والصمت","note":"عبرة قصة الملك ومعبّرَي الرؤيا","source":"شذرات (ملف وورد)"},{"id":"m1218","text":"لا تعتمدوا على الوتساب في اقتراح العلاجات والوصفات، فالوتسابُ يُحاول أن يُقتعك في توصيف العلاجات والتوصيات، لكنه رديءٌ في تشخيص الحالات والتوقعات؛ يُجيد النصح من بعيد، ويُخفق عند الاختبار والنتائج غالبا، فاحذروا وصفات الوتساب، ولا تبادروا في تطبيقها.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1219","text":"لا تُرِي زوجك اللحمَة النيَّة، ولا الزبدةَ الطريَّة","kind":"mathal","topic":"الحياة الزوجية","note":"فإنهما بعد الطبخ ينكمشان، فيظنّ بك ظنَّ السوء، ويحسبُ أنكِ أرسلتِ بعضَهما إلى أمكِ أو أُختك.","source":"شذرات (ملف وورد)"},{"id":"m1220","text":"شينُة النساء زينُة الرُمَّان","kind":"mathal","topic":"العقل والحكمة","note":"أي إن تشقّقَ قدمِ المرأةِ عيبٌ يُذم، وتشققَ قشرِ الرمانِ حُسنٌ يُحمَد.","source":"شذرات (ملف وورد)"},{"id":"m1221","text":"الدنيا غنيمة الأكياس الفطنون، وغفلة الجهال السادرون، لم يعرفوها حتى أُخرجوا منها، فسألوا الله الرجعة فلم يُرجعوا، فخسروا أنفسهم، وذلك هو الخسران المبين.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1222","text":"رسالتي لكل من تصدّر للدعوة إلى الإسلام: اجعل خُلقك قبل حُجّتك، وأدبك قبل منطقك، ولينك قبل برهانك. أَشعِر من تُحاور أنك تُريد له الخير لا الغلبة، واهدأ في دعوتك؛ فمَن وُلِدَ على معتقدٍ ونشأ عليه لا يُغيِّره الجدال بسهولة، بل يُليّنه الحِلم، ويهديه الصدق، ويجذبه حُسن الخلق، إذا بدأت بها، ودمت عليها، مع النقاش الهادئ، والبرهان الساطع.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1223","text":"زلةُ قدمٍ يتبعُها ندم، وزلةُ لسانٍ تَجرُّ نَدماً أشدَّ وألزم، فلا تُبادرْ بالقناعةِ لما تسمعُ من رأي، حتى تسمعَ من يُعارِضُهُ في الفِكرِ والمَسعى. فبالاختلافِ يتبيَّنُ الصواب، وبتصادمِ الحُجَجِ يَنجَلي الضباب، ومن سمعَ وجهًا واحدًا، رأى نصفَ الحقيقة، ومن سمعَ الوجهين، أبصرَ الحكمةَ على وجه الصواب والحقيقة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1224","text":"لا تَكرهي زوجك لتقصيره وعيوبه، واصبري واحتسبي، ولا تَكره زوجتك لتقصيراتها وعيوبها، فاصبر واحتسب، فما من بشرٍ إلا وفيه نقص، والمعروض من النوعين غالبًا غير كاملٍ ولا مُرضي، فمن رضي عاش هانئًا، ومن دقّق تعب، ومن صبرَ ظفر، ومن شكرَ استبشر.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1225","text":"احترموا كبيركم، واعطفوا على صغيركم، ووقروا عالمكم، وأطيعوا أميركم، وأنعشوا فقيركم، وأشفقوا على يتيمكم، وصِلوا أرحامكم، ولا تحتقروا غريبكم وضعيفكم، وحافظوا على أخلاق دينكم، تكسبوا رضا ربكم، ومحبة الناس وأهلكم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1226","text":"العالِم مُبصر ولو كان أعمى، والجاهل أعمى ولو كان مبصرا، فأعينوا أولادكم على طلب العلم، فما ضاع من مالك ما أنفقته على تعليم عيالك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1227","text":"من أراد كنوزَ الحكمة، فعليه بالقرآن، فهو نبعُها الصافي، ومعدنُها الوافي. ومن أراد كنوزَ العلم، فعليه بالقرآن، فهو بحرٌ لا يُدرك له شاطئ، ولا يُنزف له معين. ومن أراد كنوزَ مكارمِ الأخلاق، فعليه بالقرآن، ففيه تزكو النفوس، وتتهذّب القلوب، وتسمو الأرواح. ومن أراد كنوزَ معرفةِ أبوابِ الخير، فعليه بالقرآن، فهو الدليلُ الهادي، والنورُ البادي، والطريقُ إلى رضوانِ ربِّ العالمين. ومن أراد كثرة الحسنات، بقدر حبات رمال الصحراء، وقطرات ماء السماء، فعليه بالقرآن، فإن له بكل حرف حسنة، والحسنة بعشر أمثالها. فمن أقبل عليه فُتِحت له الأبواب، ومن أعرض عنه، حُجِب عن الأنوار والأسرار،","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1228","text":"من أعاجيب الإنسان المدهشة! وغفلته الموحشة، يبذل جهده، ويسخّر ما أنعم الله به عليه لتزيين دنياه الفانية وزخرفتها، ويغفل كلية عن آخرته الباقية، فيبالغ هنا ويقصّر هناك، كمن يُجيد ويتفنن في تزيين وتجميل فندقه الذي سيمكث فيه يومين فقط، ويُهمل بيته الذي سيقيم فيه عمره كلّه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1229","text":"التجارة في الدنيا لا تخلو من مخاطر وكساد، ومن خسارةٍ أو غشٍّ أو احتيال. أمّا التجارة مع الله، فهي تجارةٌ لا تبور، مضمونةُ الأرباح، مأمونةُ العواقب، محفوظةٌ من السوس واللصوص، ومن الحوادث والكوارث والوارث. لا تحتاج إلى مستودعات ولا تأمينات، ولا حراساتٍ ولا إجراءات. بل يكفي فيها نيةٌ صادقة، ويدٌ منفقة، وقلبٌ مُخلِص. وفوق هذا وذاك، أرباحها مضاعفةٌ مضمونة، تُخزَّن في ميزانٍ لا يضيع، وتُؤتى أحوجَ ما يكون العبدُ إليها، يوم تُوزن الأعمال، وتُقرّر الأحوال. فأكثروا من الصدقات والوقفيات والمشاريع الخيرية، فطوبى، ثم طوبى، لمن تاجر مع الله، وبذل الأموال في سبيل رضاه، ويلقى الثواب يوم يلقاه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1230","text":"كنت مطأطئ الرأس أراقب نملةً تمضي في طريقها، فتعلمت منها أن العمل أبلغ من القول، وأن النظام سرّ النجاح، وأن الصمت أهيب من الضجيج بما أُنجز. ومن يومها، أيقنت أن من تعلّم من النملة، علّمته كيف يكون عظيمًا في صغره، كبيرًا في أثره، وأيقنت أن من تعلم من النملة، وفقه الله في إنجازاته وجمع شمله وأشتاته.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1231","text":"وطنوا أنفسكم على أن تتحملوا من الناس: الجحود والصدود والسدود والبرود، فلا تغيروا عاداتكم الجميلة لتصرفاتهم القبيحة، فلنجعل الفضيلة تنتصر على الرذيلة، والأخلاق الحميدة تدحر الأخلاق القبيحة، فتجملوا بالأخلاق والآداب، قبل أن تتجملوا بالزينة وفاخر الثياب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1232","text":"التلميح يُغني عن التصريح، واللبيب بالإشارة يفهم","kind":"mathal","topic":"الكلام والصمت","note":"ورد في قصة (حرب السفن)","source":"شذرات (ملف وورد)"},{"id":"m1233","text":"حين يتقدّم بك العمر ستندم على قسوتك، حين وجب اللين، وعلى صمتك حين وجب القول، وعلى وقتٍ ضاع بين مالٍ وعمل، وعلى والِدَين وأولاد لم تنعم بقربهم، وعلى خيرٍ أخّرته حتى فات، ياليت الزمان يعود يوما، لأتدارك ما فاتني دوما.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1234","text":"الوتساب كسوق الجمعة؛ يزدحمُ فيه الغثُّ والسَّمين، فيه الزهرة تعبقُ بالعطر، وفيه البعرة تفوحُ بالنتن، تجول فيه الإشاعاتُ والوهم، كما تجولُ فيه الحقائقُ والبَيِّنات، فلا تُصدِّقْ كلَّ ما يُعرَض عليك، ولكن الزم ميزانَ العقل واليقين، ولا تنطقْ إلا صدقًا، ولا تنشرْ إلا خيرًا، صونًا للعرض والدين، فالكلمة سَهم، إن خرجَت من فمك لم تعُد إليك، فاحذر أن تُصيبَ بها بريئًا أو تُشعلَ بها فتنةً، وتحسبونه هينا وهو عند الله عظيمة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1235","text":"فلا تُبادر بالاتفاق حتى تضيق الآفاق","kind":"hikma","topic":"العقل والحكمة","note":"خلاصة قصة من خرج من عيادة الطب النفسي","source":"شذرات (ملف وورد)"},{"id":"m1236","text":"من أولويات الحكومات أن تراعي مصالح شعوبها، وعند تعارض مصلحة العامة مع الخاصة تُرجح مصلحة العامة، مع الاهتمام بمصلحة الخاصة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1237","text":"وفي الفتاوى الشرعية عند تساوي الحكمين، يُرجح التيسر على الورع، لأنه أوفق لطبيعة التشريع، وللضعف البشري، ولأن الورع للخاصة والتيسير للعامة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1238","text":"رُبَّ رجلٍ يعدل ألفَ رجل","kind":"mathal","topic":"العلاقات والناس","note":"قالها في د. عبدالرحمن السميط رحمه الله","source":"شذرات (ملف وورد)"},{"id":"m1239","text":"النظافة من الإيمان، والقذارة من إهمال الإنسان الكسلان، وتثبيط الشيطان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1240","text":"الندرة أصل الاقتصاد، فكل ما ندر غلا، وكل ما كثر رخص.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1241","text":"العرض والطلب ميزان السوق، يرفع الأسعار أو يخفضها.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1242","text":"الوقت رأس مال خفي، من ضيّعه خسر أرباحه دون أن يشعر.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1243","text":"المال إذا لم يُستثمر تآكل، فالجمود عدو القيمة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1244","text":"الادخار وقاية، والاستثمار نماء.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1245","text":"المخاطرة بقدر الخبرة تُثمر، وبقدر الجهل تُفقر.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1246","text":"الثقة رأس مال معنوي، إذا فُقد انهارت التجارة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1247","text":"الاحتكار يفسد السوق، والمنافسة تنعشه.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1248","text":"الاستهلاك بلا وعي يُولّد الفقر، والإنتاج الواعي يُنبت الثراء.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1249","text":"لا تُنفق كل ما تملك، ولا تُقرض من لا تثق.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1250","text":"الربح العاجل قد يُنسي الخسارة الآجلة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1251","text":"من راقب ميزانيته ملك قراره.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1252","text":"الاقتصاد في المعيشة نصف الغنى.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1253","text":"الديون سلاح ذو حدين: ترفع حين تُحسن إدارتها، وتُسقط حين تُهمل.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1254","text":"الاستقرار المالي ثمرة الانضباط لا الصدفة.","kind":"hikma","topic":"المال والاقتصاد","note":"من (مجموعة مختصرة من القواعد الاقتصادية والحكم والمبادئ)","source":"شذرات (ملف وورد)"},{"id":"m1255","text":"الثروة ليست لمن جمعها، بل لمن أنفقها في مرضاة الله تعالى، فصانها من السوس واللصوص، والحاسد المنحوس، والحرق والغرق، والحوادث والكوارث.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1256","text":"الوتساب ليس قناة إخبارية، أو محطة رياضية، أو نشرة صحية، أوجامعة علمية، فالتكرار غالبا يُولد الملل والنَّفَار، الوتساب سوق أو مجمع تجاري أو جمعية، فيه العطور والذهب، وفيه الفحم والحطب، وفيه الخوخ والرمان وفبه البصل والباذنجان، فالوتساب لجميع الآراء والأحباب، باللين والحب والآداب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1257","text":"في القرونِ الأولى، كان الهمُّ الأكبرُ ترسيخَ أركان الإيمان، وتهذيبَ النفس بفقه العبادات والمعاملات، وصقلَ أخلاقِ الإنسان. أمّا في عصرنا، فقد انصرف كثيرٌ من الخلق إلى فقهِ الشراب والطعام، وإلى ملاذِّ الأجسام ومتاعِ الأنام، حتى صار ما يُشبِع البطون مقدّمًا على ما يُحيي القلوب والعقول. فيا لها من مفارقةٍ تُنبّه، وحقيقةٍ تُؤسّف، وتذكيرٍ بأنّ الدين أولى وأعلى، وأنّ العاقل من أقام ميزانَه بين غذاء الروح وغذاء البدن؛ فلكلٍّ قدرُه، ولكلٍّ مقامُه.","kind":"hikma","topic":"الإيمان والعبادة","note":"تحت عنوان: فقه الطعام وفقه الإسلام","source":"شذرات (ملف وورد)"},{"id":"m1258","text":"إن لم تستطع أن تجود على الناس بمالك، فجد علىهم بكلامك، فاجعل على عَذْبَة لسانك لُعاب النحل، وكن لين العريكة، سهل الطريقة، سمح الطبيعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1259","text":"إذا تعاون أعضاء القروب، فبشرهم بتآلف القلوب، ووضوح الدروب، ورفع الكروب، وحلول السلام بدل الجدال والحروب، وبدل النزاع والمكروه، يحل الحب والمحبوب.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1260","text":"ليست العلّة في عدم زيادة الرواتب فحسب، بل في موجة الأسعار التي تواكب الزيادة، فترتفع كلما ارتفعت الرواتب، تغذّيها شهيةُ التجار وجشعُهم. فالمواطن هو الجسر التى تمر عليه زيادة الرواتب، لتنهال في جيوب التجار الجشعين. فإذا اجتمع ضعف الدخل مع جشع السوق، ضاق العيش على أهله، فلا نجاة إلا بحكمةٍ في النفقة، ورقابةٍ تُلجم الطمع، واقتصادٍ يكبح سَعَارَ الارتفاع.","kind":"hikma","topic":"المال والاقتصاد","note":"بعنوان: زيادة الرواتب","source":"شذرات (ملف وورد)"},{"id":"m1261","text":"لم يبق من العمر كثر ما فات، فلا متسع للعتابات، شبنا فاخترنا الحكمة والسكينة، وقللنا اللوم والملاحظات، وهجرنا كثرة التفاصيل والانتقادات، واستبدلناها بالتسامح وقلة الموآخذات، إبقاء على حسن العلاقات والمودات، وصفاء النفوس من الفضائل والمكرمات، وهي دماء تجري في عروق أهل المروآت، والتوفيق يُطلب ويُدرك من رب الأرض والسماوات، وكل داء له دواء إلا الهرم والحماقات.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1262","text":"بعضُ أزماتِ المجتمع إنما تُولدُ حين نجاوز هديَ الإسلام، بينما دواؤها مبثوثٌ في شرعه المستقيم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1263","text":"القرآنُ نزلَ في الحجاز، وقُرئ في مِصرَ بالتجويد والإعجاز، وحُمِل في الصدور، وسار في الأمصار، وطُبِّق في القرون الأولى، بلا تقصيرٍ ولا انحياز، فصار هدايةً لكل العصور، يُبدد الظلام وينشر النور.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1264","text":"كان الشعر في الجاهلية له نور يسطع، وسطوة تُخضع، وسلطان يُخيف ويُقنع، فلما نزل القرآن، خَبَا نوره، وخَفَت ضياؤه، وزالت شوكته وسطوته، وذابت منزلته وهيبته، وانحنى أمام نورٍ أعظم، وبيانٍ أبلغ، ووحيٍ أبهى ضياءً وسناءً، فانحنى له الشعراء، وخضع له الأدباء، وأقرت له العلماء، في التفوق والعلياء، فالقرآن العظيم كنز العلوم والمعارف، والأسرار والأخبار، تفوق البحار والأنهار، في الوفرة والكثرة، فهو مفتاح العلوم، وكنز الأخبار والأسرار، لا تنقضي عجائبه على مَرِّ العصور وتتابع الدهور، ولا يخلق على كثرة الرد والتكرار، في الليل النهار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1265","text":"زكاة نعم الله الكثيرة، الجود على الفقير والفقيرة. زكاة قوة الأبدان، مساعدة الضعفاء من بني الإنسان. زكاة علوم الدين، تعليم الناس والطالبين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1266","text":"الرقابةُ الشعبيّةُ على أداء الحكومة، أو على طائفةٍ من الناس، إذا جاءت في وقتهاومحلها، وبأسلوبٍ رفيعٍ يخلو من التجريح تصريحًا وتلميحًا، ومن الإسفاف والاستخفاف والإلحاف؛ كانت رقابةً راشدةً تُصلح ولا تفضح، وتُقَوِّم ولا تُهَدِّم. فهي رقابةٌ إيجابيّةٌ ذاتُ أثرٍ نافع، تعصم مسيرةَ الدولة من التمادي في السلبيات، والانجرار إلى المخالفات. وما أحوج الأمم إلى صوتٍ ناصحٍ يحمل الحق بأدب، والصدقَ بميزان، وبأسلوب راقٍ في التوضيح والبيان.","kind":"hikma","topic":"السياسة والقيادة","note":"بعنوان: الرقابة الشعبية","source":"شذرات (ملف وورد)"},{"id":"m1267","text":"الحرب قتال بين طائفتين من الشباب، يقتل بعضهم بعضا، ولا يعرف بعضهم بعضا، بأوامر فريقين من الشيوخ، يعرف بعضهم بعضا، ولا يقتل بعضهم بعضا.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1268","text":"الرئاسة مشغلة ومسؤولية، وهموم وتقييد حرية، وإكراه لمجاوزة القانون، والمحاباة والحيف، لصالح أقربائك وأصدقائك.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1269","text":"بعض التجار مثل الآلة الحاسبة، ما عندها ضمير، ولجمع المال كل شيء يصير.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1270","text":"النفوسُ تُقبِل وتُدبِر؛ فإذا أقبلت فاغتنموها بالصالحات والوقفيات والتبرعات، وإذا أدبرت فأمسكوها على الفرائض والواجبات؛ فبها النجاة، وعند الله عظيم الثواب والهبات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1271","text":"لو ربَّى الناسُ أبناءهم جميعًا على القيادة، فمن يُقاد؟ ولو طلبوا لأنفسهم ذروةَ التعليم، فمن ينهض بأعمال الحفر والبناء، والهدم والكشط، والنظافة وتسليك المجاري، وسائر المهن الشاقة والخطرة؟ إن سنّة الله في خلقه التنوعُ والتكاملُ؛ فلا تستقيم الحياةُ إلا بالغني والفقير، والعالم والمتعلّم، والرئيس والمرؤوس… يقوم بعضُهم بحاجات بعض، ويُكمل بعضُهم بعضًا، في نسقٍ محكم، وحكمةِ عليمٍ خبيرٍ رؤوفٍ رحيم.","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: حكمة الله في التنوع","source":"شذرات (ملف وورد)"},{"id":"m1272","text":"هؤلاء القُصّاص لا تُؤخَذ عنهم معالمُ الدين؛ غيرُ مُؤتمنين، يخلطون الواهي بالصحيح، ويرون المخترَع الذي لا أصل له، ويُلبِسون على الناس بأحاديثَ ضعيفةٍ تُعَكِّر صفوَ اليقين وصريحَ الشرع، وما كان هكذا فلا يُستقى منه، ولا يُعوَّل عليه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1273","text":"أفضل هدية تقدمها إلى أهلك، وأنت قادم من السفر، هي صحتك وسلامتك","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1274","text":"لا تفعل ما لا تريده، ولا تريد ما لا غاية له، ولا تكون الغاية صائبة إذا صدرتَ عن عاطفة جياشة تُعميك عن تبعات القرار. فحرّر نفسك أولًا من اندفاع الهوى المُضلل، والحماس الطائش، ثم انظر بعقلك فيما سيؤول إليه اختيارك، من سلبيات وإيجابيات، واحتطْ لتجنّب أسوأ الظنون، ليصدر فعلُك عن بصيرة لا عن جزاف، وحماس أهوج أعور أعرج.","kind":"hikma","topic":"العقل والحكمة","note":"بعنوان: اتخاذ القرار","source":"شذرات (ملف وورد)"},{"id":"m1275","text":"الحياة هي المدرسة الكبرى، فمسيرة الحياة مليئة بالتجارب، فيها الصواب وفيها الخطأ، والصواب ابن الخطأ، ونتيجة التجارب لا تُخطئ، ودلالتها يقينية، فاطلب العلم النظري من علمائه، واطلب العلم العملي والصناعي والتجريبي من علمائه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1276","text":"ما أروع وأبدع منشورات الصالحين، وتغريدات العلماء والحكماء والملهمين، في وسائل التواصل الاجتماعي وغيرها، هذا يذكرك بآية، وآخر بحديث، وثالث يهديك فائدة، ورابع ينصحك ويرشدك، وهلم جرَّا. فبدونهم لا طعم للمواقع ولا فائدة من المنشورات،","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1277","text":"لا تجعل كل اهتماماتك في جمع الثروة، وتنمية الأموال، وتصريف البضاعات، ولكن اجعل بعض اهتماماتك في دينك وآخرتك وعبادتك، لتربح الدارين، وتكسب الحياتين.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1278","text":"لا تفرح كثيرا بالأموال الهائلة، التي تأتيك من طرق مشبوهة، ومن طريق الغش والسحت والإختلاس والحرام، فإن عاقبة الحرام وخيمة، واحذر المحق الخفي، فحبل الحرام قصير، وحسابه طويل.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1279","text":"النقاشُ والتلقينُ ركنان في بناءِ العلم؛ فالنقاشُ يفتحُ الآفاق، ويوقظ العقول، والتلقينُ يُؤسِّسُ الأصول، ويُثبِّتُ المعلومةَ في محلّها. وكثيرٌ من الناس يُهوِّنون شأنَ التلقين، وهم لا يعلمون أنّه الجذرُ الذي يسبقُ الثمر، وأنّ النقاشَ بلا أصلٍ كغصنٍ بغير جذر، وأنّ العقولَ لا تُشرق إلا إذا اجتمع لها غرسٌ راسخ وفهمٌ نافذ وسؤالٌ مُستنير. والتلقين يسبق النقاش، وبالأخص في تربية الصغار، ومع غير العالم، وفي من هو خالي الذهن عن الموضوع. هكذا يكتمل نور المعرفة، ويبدو العلمُ في أحسن صوره.","kind":"hikma","topic":"العلم والثقافة","note":"بعنوان: النقاش والتلقين","source":"شذرات (ملف وورد)"},{"id":"m1281","text":"البلدان المتحاربان كلاهما خاسر؛ يخسران الرجال والمال، ويغرقان في التدمير بدل التعمير، فتتعطل مسيرة التقدم والعمران. ومن يُعدّ رابحًا فيهما، إنما ربحه نقصان خسارته، لا تمام نصره. ولو رَجعا إلى التفاهم، وقَبِلا بشيءٍ من التنازل، لجنّبا أنفسهما الخسران، وحفظا للأمة أمنها وعمرانها وسلامتها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1282","text":"إن عجزتم أن تردوا الجميل بالأجمل أو بالجميل، فردوه بالشكر والدعاء والثناء الجزيل، والفضل للمبتدي ولو أجاد المقتدي.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1283","text":"موتُ الأبِ سقوطُ عمودِ خيمةِ الأبناء، وانهيارُ صرحِ البناء، وتصدّعُ جدرانِ الفناء، وتنحلُّ عُرى ترابطِ الأُسرة، ويزدادُ الحزنُ والحسرة، ويغيبُ الحِمى، ويضعف الإخاء، ويتسعُ جُرحُ الرجاء، تخفتُ الملامح، وتبهتُ الصور، وتضيقُ في العيونِ السماء، فالأبُ ليس رجلاً فحسب، بل هو أُنسُ الحياةِ وثوبُ الدفءَ والهناء، ومهد الأرض وظل السماء. فعلي الاولاد أن يتواصلوا ويتعاونوا ويتفاهموا ويتسامحوا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1284","text":"نصائح وضوابط المعاملة مع رئيسك في العمل: نفذ أوامره التي تلزمك في العمل. احترمه دون تزلّف. بادر قبل أن يَطلب منك. كن صادقًا لا مداهنًا. لا تنقل إليه ولا تُنِمّ. اجعل همَّك العمل، لا مجرد نيل الرضا. افعل ما يجعله يثق بحسن تصرفك وامانتك. وفي المقابل سوف يتعاون معك، ويثق بك، ويقدمك في الترشيحات والمميزات التي في صالحك، لأنك تستحق ذلك.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1285","text":"المحافظة على الرياضةِ قوّةٌ في الأبدان، ونشاطٌ في الأركان والأذهان. وتقليلُ الطعامِ صفاءٌ للأذهان، وتخلّصٌ من الدهون، وجمالٌ للأبدان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1286","text":"لا يَحسُن بالآمر بالمعروف والناهي عن المنكر أن يُكرِه الناس على اجتهاده، أو يُلزمهم بمذهبه، فإنما وظيفته أن يُبيّن الحق بدليله، ويُرشد برفقه ولينه، ويُغيّر ما أُجمِع على إنكاره، أو ثبت بالنص تحريمه وإحداثه، أمّا المختلف فيه فمجاله السعة، وميدانه العذر، ومقامه الرحمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1287","text":"لو اجتمع جملٌ من فجر الإنسانيّة بجملٍ من عصرنا، لما رأيتَ بينهما كبير اختلاف؛ فطبعه واحد، وصبره واحد، وقوّته واحدة، وقدرته على احتمال القحط لم تتبدّل، فيألف أحدُهما الآخر سريعًا. ذلك لأن الله خصّ الإنسان بتعليم الأسماء، فجعلها أصل المعرفة، ومفتاح التفكير، وسرّ التطوّر والتراكم الحضاري، أمّا الحيوان فهدايته غريزيّة محدودة، لا تنمو ولا تتجاوز حدّها، ليبقى مسخَّرًا للإنسان، لا مزاحمًا له في العقل ولا منافسًا في البناء. وهذا من عظيم فضل الله على الإنسان، الذي فضله الله علي كثير من خلقه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1288","text":"القول إن حفظ القرآن لا يتم إلا في ظلّ المشكلات، قول غير دقيق؛ فالحفظ في الصغر أيسر وأرسخ، مع خلو القلب من الهمّ، وصفاء الذهن، وقوة الذاكرة. أما الكبار، فالمشكلات قد تحرّكهم، لكنها لا تُعينهم، بل تشتتهم وتُضعف قدرتهم على التركيز. فالحفظ لا يُربط بالمحن، بل بالعزيمة والانضباط. وكل مرحلة عمرية صالحة، متى وُجدت الهمّة، وصحّ القصد، والصغر أفضل مرحلة للحفظ.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1289","text":"فالصغير أصغر عقلا لكنه أقل شغلا، والكبير أكبر عقلا لكنه أكثر شغلا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1290","text":"كن عظيمًا ودودًا، قبل أن تكون عِظامًا ودودًا. كن كريمًا وجوادًا، قبل أن تصير رُفاتًا وجمادًا. كن حيًّا شاهدا، قبل أن تصير ميتًا غائبًا.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1291","text":"لا تجعل أُذُنَك قِمْعاً تُبادر بقبول الكلام، من غير ان تتحقق وتتيقن، من سؤال شايبين أصلعين عالمين متخصِّصَين.","kind":"hikma","topic":"الكلام والصمت","note":"القِمْع: ما يُصَبُّ فيه السوائل.","source":"شذرات (ملف وورد)"},{"id":"m1292","text":"دموع النساء أقوي من عضلات الرجال الأقوياء، لأن تأثير العضلات على الأبدان، وتأثير الدموع على الجَنَان.","kind":"hikma","topic":"العلاقات والناس","note":"الجَنَان: القلب.","source":"شذرات (ملف وورد)"},{"id":"m1293","text":"كفرانُ العشيرِ: ثمرةُ لحظةٍ غلبت فيها العاطفةُ الذاكرة؛ فيغيب تاريخُ الإحسان بزلةٍ حاضرة، ويُقاس العمرُ بالموقف الحاضر، فإذا ثقلت التوقّعات واشتدّ الضغط، ضاق ميزانُ العدل، فرُئي النقصُ وغاب الفضل، والعلاجُ تذكيرُ العقل بما نسيه الشعور.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1294","text":"تَسْعد النفوس بالخروج إلى البرّ الواسع لأسبابٍ: سعة البر تُوسّع الصدر وتخفّف الكدر. جمال الطبيعة يُهدّئ النفس ويذهب ضغوط الحياة. البساطة والفطرة تجلب التوازن والطمأنينة. الابتعاد عن الضجيج يستدعي التأمّل والسكينة. اجتماع الأصدقاء يزيد في الأُنس والمودّة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1295","text":"الطبيعة خَلْقُ الله قبل آدم، وآيةُ التوحيد قبل الرسل؛ تشهد للخالق ذاتًا وصفاتٍ، ويُحال إليها في القرآن دعوةً للإيمان. فهي أولُ داعيةٍ إلى الله، وآخرُ من يطوي عروش الملوك وقصورهم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1296","text":"ما استُعمل قوي، وما أُهمل ضَعُف. والاعتدال هو سرّ السلامة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1297","text":"لكل طريق طويل لوكيشن فلوكيشن الجنة السُّنَّة فمن ضيع السُّنَّة فقد أخطأ طريق الجنة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1298","text":"يكثر الغش في المدن أكثر من القرى؛ لأن القرى تضبطها السمعة، والمدن تحكمها المصلحة. ففي القرى تردعك العيون، وفي المدن تُغريك الظنون؛ هناك تُعرف فتُحاسَب، وهنا تُجهل فتُغرَى. فإذا غابت الرقابة وضعف الضمير، استشرى الغش واستوطن الخداع والتحايل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1299","text":"من خالفَ السُّننَ الكونيّة، والقواعدَ الصحيّةَ البدنيّة، وأراد أن يُنقِصَ وزنَه بسرعة؛ فقد أخطأ الطريق، وخالف الحكمة. فما بناهُ الجسدُ على مَهَلٍ، لا يُهدمُ في عَجَل، وما تراكمَ في سنين، لا يزولُ في أسابيع. ومن طلبَ النتائجَ بلا مُقدِّمات، حصدَ العواقبَ بلا سلامة.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1300","text":"الصوابُ ابنُ الخطأ، والتجاربُ مُعلِّمٌ لا يُخطئ، والحِكمةُ بنتُ الصبر، والعجلةُ أختُ الندامة. والتغييرُ الحقيقيُّ ليس قفزةً عابرة، بل مسيرةٌ ثابتة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1301","text":"البَعرةُ تدلُّ على البعير، والأثرُ يدلُّ على المسير، فسماءٌ ذاتُ أبراج، وأرضٌ ذاتُ فِجاج، وبحارٌ ذاتُ أمواج؛ ألا تدلُّ على اللطيفِ الخبير؟","kind":"mathal","topic":"الإيمان والعبادة","note":"قالته العرب في أوضح براهين العقل","source":"شذرات (ملف وورد)"},{"id":"m1302","text":"فالعقلُ لا يَخلقُ الإيمان، لكنه يدلُّ عليه، ولا يُنشئُ الهداية، لكنه يُرشدُ إليها، ولا يستغني عن الوحي، ولا يستغني الوحيُ عن عقلٍ يفهمه.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1303","text":"السياسةُ وجهان: مُعلَنٌ للناس، وخفيٌّ يُدار خلف الأستار، وعودُها تُقال، وأسرارُها تُكتم، وما يُظهَر فيها جسورٌ لما يُبطَن، ورسائلُ تُفهَم بقدر ما يُراد لها. تُحاك في الغرف المظلمة، وتُنفَّذ في الساحات المعلَنة، ويخالطها المكرُ طلبًا للغَلَبة والمطامع، والله أعلم بما فيها من الكبد والفظائع.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1304","text":"عند طلب الحقوق، ابدأ باللين والرجاء، واطرق الباب بالأدب والحياء، فإن لم يُفتح، فأَعِد الطرق بالإلحاح والمساءلة، فإن أُغلق في وجهك، فاصدع بالمحاججة، واطلبه بالضجيج والجعجعة، فبعض الحقوق لا تُهدى، بل تُنتزع بالمخاشنة بعد المحاولة والملاينة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1305","text":"السياسة الحكيمة شطر النصر.","kind":"hikma","topic":"السياسة والقيادة","note":"عبرةٌ ختم بها حديثه عن فتح عمرو بن العاص مصر","source":"شذرات (ملف وورد)"},{"id":"m1306","text":"فقه العقول قبل قوة العضلات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1307","text":"فما أُخذ بالحيلة والحكمة، لم يُحتج فيه إلى القتال وسفك الدماء.","kind":"hikma","topic":"السياسة والقيادة","note":"من تعليقه على فتح مكة","source":"شذرات (ملف وورد)"},{"id":"m1308","text":"إيّاكَ والمبالغةَ في الأعشاب للصحة والعلاج ولو في الجرجير؛ فإنّ الاعتدالَ في كلّ شيءٍ هو منهجُ الحكيمِ والبصير، وبه تُحفَظُ الصحّةُ وتَسْلَمُ المعدة والمصير.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1309","text":"الأصلُ أنَّ الرجلَ راعٍ مُوجِّه، والمرأةَ متلقِّية، لذا خوطب الرجالُ بقوله تعالى: {فَعِظُوهُنَّ}. فإذا وقع النشوزُ أو الخطأُ بدأ بالوعظِ قبلَ غيره؛ إذ الحكمةُ أن يبدأ بالأخفِّ قبلَ الأشدِّ، وباللينِ قبلَ الحزمِ، وبالنصحِ قبلَ العتابِ؛ فذلك أرجى للقبولِ، وأليقُ بأمانةِ القِوامة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1310","text":"جيل العقاد والرافعي كان التنافس في الثقافة والقلم والجيل الذي بعدهم أصبح التنافس في الكرة والقدم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1311","text":"لا تقترض لتبدأ مشروعًا. اقترض فقط لتكبير مشروع ناجح.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1312","text":"إن لم يربح المشروع وهو صغير، فلن يربح وهو كبير.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1313","text":"احسب الربح نقدًا لا على الورق. الربح الذي لا يدخل حسابك وهم.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1314","text":"اجعل مصروفاتك أقل من دخلك دائمًا، حتى لا تقع في فخ الديون.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1315","text":"ارفع السعر قبل أن تكثر البيع. الكثرة مع هامش ضعيف تُهلكك.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1316","text":"احفظ رأس المال قبل أن تبحث عن الربح.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1317","text":"لا تدخل تجارة لا تفهمها.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1318","text":"لا توسّع حتى تستقر.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1319","text":"الدخل الواحد خطر. ابحث عن مصدر ثانٍ ولو صغير.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1320","text":"الديون للضرورة لا للرفاهية.","kind":"hikma","topic":"المال والاقتصاد","note":"من «قواعد اقتصادية»","source":"شذرات (ملف وورد)"},{"id":"m1321","text":"غالبا الوتساب يدهشك بالوصفات العلاجية، ويخذلك بالنتائج الصحية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1322","text":"الطفل يرضع من أُمه سنتين، ويشرب بقية عمره من البقرة سبعين عاما، فالحمد لله على نعمه التي لا تُحصي، وعلى فضائله التي لا تفنى.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1323","text":"كثيرٌ من الأسماء في العربية ليست اعتباطية، بل بين اللفظ ومعناه نَسَبٌ ووشيجة، وهذا من دقائق حكمة هذه اللغة وجمالها.","kind":"hikma","topic":"العلم والثقافة","note":"خلاصة باب موافقة الاسم للمسمّى في العربية","source":"شذرات (ملف وورد)"},{"id":"m1324","text":"لم تُشرَعِ الحُدودُ لتُقام على المستتر، وإنما شُرعت لزجرِ المُجاهر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1325","text":"فالتفاحةُ الفاسدة تُفسِدُ السَّلَّة، والدجاجةُ المريضة تُعدي الحظيرة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1326","text":"لهذا شُرعت الحُدود: وقايةً قبل أن تكون عقوبة، وحمايةً قبل أن تكون إيلامًا، ورحمةً بالمجتمع قبل أن تكون شدّةً على الفرد. فهي لم تُشرَع لِتُكثِر التنفيذ، بل لِتُقلِّل الجريمة؛ إذ إن إقامةَ حدٍّ واحدٍ أبلغُ في الردع من ألف موعظة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1327","text":"صانعُ الشيء أدرى بما يُصلحه ويصونه.","kind":"hikma","topic":"العقل والحكمة","note":"قالها عقب قوله تعالى: ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾","source":"شذرات (ملف وورد)"},{"id":"m1328","text":"أفضل صفات المتقاعد: 1.الرِّضا: يقبل مرحلته الجديدة بلا تذمّر ولا تحسّر. 2.القَصْد: يُحسن تدبير وقته وماله بلا إسراف ولا تقتير. 3.النَّشاط: لا يترك نفسه للفراغ والكسل. 4.الحِكمة: يُحوِّل خبرته إلى نُصحٍ وإرشاد. 5.العِفّة: يترفّع عن سؤال الناس والتعلّق بما في أيديهم. 6.التوازن: لا ينعزل ولا يضيع وقته في اللهو. 7.الشُّكر: يرى التقاعد نعمةَ فراغٍ لا نقمةَ فراغ.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1329","text":"اتَّقِ ظنَّ المتقي، فإنَّ الله جعل الحقَّ على لسانه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1330","text":"من عرف الله أحبَّه، ومن عرف الدنيا زهد فيها، ومن عرف الآخرة رغب فيها وعمل لها.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1331","text":"التفكُّر قبل العمل يرفع هيبة البديهة وحيرتها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1332","text":"إذا ناقشنا كل الآراء، لم يَبقَ لنا وقتٌ للعمل.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1333","text":"نحن لا نُحب هذا الذئب، لأنَّ ذئبًا أكل نعجتنا، لاتفاقهما في الطبع؛ فالأول أكلها، والثاني عنده استعدادٌ غريزيٌّ ليفعل مثله.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1334","text":"إذا أغلقتَ عليك بابك، فأنت أميرُ نفسك.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1335","text":"(وصايا الملك لابنه الذي سيخلفه) 1. ابدأ بالعدل وإنصاف المظلومين، فالعدل أساس المُلك. 2.قدِّم الخدمات قبل أن تطلبها، فالسلطة تكليف لا تشريف. 3.قدِّم الأكفأ لا الأقرب. فالدولة تُدار بالقدرات لا بالمودّات. 4.اسمع كثيرًا وتكلّم قليلًا. فكثرة السمع تقلّل الزلل. 5.راقب البطانة قبل الرعيّة، فساد الخاصّة أسرع إلى هدم الدول. 6.احفظ المال العام كما تحفظ مالك، فالخيانة فيه خيانة للأمّة. 7.قدِّم الأمن والعدل على الرخاء والرفاهية، فلا عمران بلا أمن ولا عدل. 8.تأنَّ في القرار، حتي يتبين لك الصواب، ثم اعزم بعده، فالتردّد ضعف، والعجلة ندامة. 9.أمسك بالقوّة، ولا تستخدمها إلا في الحق. فالهيبة بلا ظلم، تجلب لك المحبة والطاعة. 10.اذكر أنك راحل والمُلك باقٍ، فأحسن الأثر يُخلِّد لك الذكر في الدنيا، وتُرفع درجاتك في الآخرة. 11.وأفضل ما يخلد لك الذكر الطيب هو: العمران الكبير الذي يخدم الشعب، وبالأخص الفقراء والضعفاء.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1336","text":"أعظم نعمة بعد الإيمان العافية، والعلاج الطبيعي أفضل من العلاج الكيميائي","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1337","text":"نصيحة فاعليتها صحيحة كوب ماء دافئ على الريق، وآخر قبل النوم: يوقظ الأمعاء، ويُليّن الإخراج، يقاوم الإمساك بلطف وأمان، إن ما نفعك ما ضرك.","kind":"hikma","topic":"الصحة والنفس","note":"فيها المثل: إن ما نفعك ما ضرك","source":"شذرات (ملف وورد)"},{"id":"m1338","text":"آداب المحاورة: المحاورة تقوم على حسن القصد، وصدق القول، واحترام المخالف، وترك المكابرة، وطلب الحق لا الغلبة، واللين وعدم المخاشنة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1339","text":"العقل الصحيح لا يعارض الشرع الصريح؛ لأن مصدرهما واحد، فالله خلق العقل وأنزل الشرع، وإنما الخلل في الفهم لا في الأصل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1340","text":"التجارة تقوم على الحساب لا على التمنّي، والربح الحقيقي يُصنع عند الشراء لا عند البيع، وحفظُ رأس المال مقدَّم على تنميته، والسيولة روحُ المشروع، ومن لا يُحسن الأرقام يخسر ولو كثرت مبيعاته.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1341","text":"عوامل تقييم الوزير: تحقيق الأهداف، كفاءة الأداء، رضا المواطنين، النزاهة والشفافية، التطوير المستدام، فتح الأبواب لا غلقها، إنصاف المظلوم، والمتابعة الدقيقة لسير العمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1342","text":"إذا أردت أن تُقنع غيرك برأيك، فكن صادقًا في قولك، واضحًا في حجّتك، هادئًا في نبرتك، عارفًا بمن تخاطب، مستندًا إلى برهان واضح، ومحركًا للعقل والعاطفة معًا؛ فإن الإقناع لا يكون بالصوت العالي، ولا الحماس المتعالي، بل بالحجة والفطنة، والثقة ووضوح الأسلوب، وبيان الأدلة والدروب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1343","text":"شبهات حول الوزير: كثرة المقرّبين من أقاربه ومحيطه الخاص، تنامي أرصدته بشكل لافت، غياب المتابعة الدقيقة لسير العمل، التراخي في المحاسبة، وتفضيل الولاء على الكفاءة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1344","text":"قواعد تربية الأطفال المهمة الإيحاء السلوكي: كن كما تحب أن يكونوا، لأنهم يقلدوك، والتقليد باب عظيم من أبواب العلم، ونقل المعارف والعادات واللغة، واللغة وعاء الفكر. الحنان والانضباط: مزيج من الحب والحزم. الاستماع والتفهم: أصغِ لمشاعرهم واحتياجاتهم باهتمام. التشجيع لا التوبيخ: امدح السلوك الجيد بدل التركيز على السلوك السيئ. الوضوح والثبات: ضع قواعد وضوابط واضحة وثابتة وميسرة. التعليم باللعب والتسلية: التعلم الممتع أخف وأرسخ. الاحترام المتبادل: عامله باحترام ليحترمك ويحترم الناس. تنمية القيم: الدين، الصدق، الأمانة، التعاطف رويدا رويدا، لطرد السآمة. تحفيز الاستقلالية: علّمه الاعتماد على الله ثم على نفسه، مع الاستعانة بالخبير الناصح. الدعاء: ورافق كل هذا بدعاء صادق. الإستمرار على كل ما تقدم ليصبح عادة له، فيخف عليه الإلتزام الدائم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1345","text":"إذا أردت أن ينشأ أطفالك أذكياء، فاحكِ لهم قصصًا قصيرة، بعباراتٍ يسيرة، ومعانٍ مثيرة، تنبض بالحكمة، وتمتلئ بالفطنة، وتزدان بالأخلاق الزكية، والمواقف الذكية، تُغذي عقولهم، وتُنمي معارفهم، وتُشعل خيالهم، وتُقوّي لغتهم، وترتقي بذوقهم، وتصقل شخصياتهم السوية، لتغدو قويةً نقيّةً فتية.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1346","text":"نصائح للمبتدئ بقيادة السيارة تأنَّ قبل التحرك، وركّز عند المفترق، ولا تُسرع عند الزحام، ولا تتردد عند اللزوم، اجعل المرايات عيونك، والإشارات إرادتك، والحذر رفيقك، ويدك على المِقود لا على الهاتف، والزم اليمين إلا للعبور، فسلامتك وسلامة الناس في اتباع الإرشادات ويقظة الحواس، وأفضل هدية تُقدمها إلى أهلك، أن ترجع إليهم سالما.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1347","text":"اقتراحُ الكمالِ يسيرٌ على اللسان، وتحقيقُه عسيرٌ في الميدان، فالكلام لا يُكلفُ جهدا ومالاً، أما الفِعال فتحتاجُ عَزماً ومالا ورجالاً، فليس كلُّ من أشار أجاد، ولا كلُّ من تمنى أنجز وأفاد.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1348","text":"في أول لقاء للمخطوبة، كن خفيف الظل، لطيف القول، بعيدًا عن التكلّف والجدال، وابدأ بالسلام، وعرّف بنفسك باحترام. تحدّث عن القيم والهوايات، لا عن المكاسب والماديات، واسأل عن الطموحات لا عن العقارات والبنايات، واختر من الكلام أعذبه، ومن السؤال ألطفه. واجعل الابتسامة عنوانك، والصدق ميزانك، وحسبك من المديح تلميح بلا تصريح، وأظهر جميل الطباع، فأول لقاء يصنع أقوى انطباع.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1349","text":"ميزان ردود الأفعال: يقاوم الإنسان ردود أفعاله القوية، سواء أإيجابية أم سلبية، عبر ثلاث وسائل جوهرية: 1.الوعي الذاتي: أن يُدرك مشاعره فور نشوئها، ويميز بين ما هو طبيعي وما هو مفرط. فالإدراك أول خطوة للتحكم. 2.ضبط النفس: بالتريث قبل الاستجابة، والتنفس العميق، وذكر الله في النفس، لكبح التسرع والانفعال. 3.إعادة التقييم العقلي: بأن يُعيد تفسير الموقف، فلا يبالغ في الفرح، ولا يُستفز بالحزن أو الغضب، بل يُوازن بين العاطفة والعقل. فالسيطرة لا تعني كبت المشاعر، بل توجيهها بطريقة ناضجة ومناسبة للمقام.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1350","text":"أثر الأذان في النفس والناس الأذانُ يُحيي القلوب بعد غفلة، ويُطمئن الأرواح بعد وحشة، ويبعث في النفس الطمأنينة، ويجعل للوقت بركة وسكينة. هو نداءُ التوحيد والوحدة، وسِرُّ الاجتماع والألفة، به تجتمع الأمة، وتتوحد الكلمة، وتعمّ البركة والرحمة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1351","text":"تقوية الإيمان: أن تجالس وتصاحب من هم أقوى منك إيمانا، وأكثر منك خشوعا، وأوسع منك علما وفقها. فالصاحب ساحب، والرفيق من يسايرك في طريق الحياة، بالرفق والنصح والتوفيق، والمرء يُحشر مع خليله، فلينظر أحدكم من يُخالل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1352","text":"الأذانُ صوتُ السماء، ودعوةُ الصفاء، وفيه إعلان التوحيد، وبثُّ روحِ التجديد. يُرهبُ الشيطان، ويرضي الرحمان، ويُنعشُ الإيمان، وينبه الغفلان، ويربطُ الأرضَ بالسماء، والعبدَ بحب الربّ دون عناء. المؤذِّنُ لسانُ الإسلام، وجنديُّ السلام، أجرُه عظيم، وذِكره كريم. فهو نداءُ الفلاح، وسراجُ الأرواح، يُصلح النفس، ويجمع الناس، ويجعل في المجتمع نورًا وانسجامًا. ويوحد القلوب والأرواح، ويشرح الصدور ويجلب الخشوع والفلاح.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1353","text":"أن النصر مع الصبر، وأن الأخذ بالأسباب لا ينافي التوكل، وأن الغاية النبيلة تستحق التضحية، وأن قلوب المؤمنين تتلاقى على نصرة الحق، ولو تباعدت الأوطان والأعراق.","kind":"hikma","topic":"الإيمان والعبادة","note":"من عِبر الهجرة النبوية","source":"شذرات (ملف وورد)"},{"id":"m1354","text":"مِلْءُ الوِعاء الفاضي أيسر من مِلْءِ الوعاء المَلْيان، كذلك اقناع الذهن الخالي أيسر من اقناع الذهن المَلْيان بالشبهات والضلالات والسفاهات، لأن الثاني يحتاج أولا إلى ابطال الشبهات والضلالات، ثم اقتاعه بالحقائق والمسلمات.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1355","text":"من بالغ في التدقيق حُرِم التوفيق، تغافل تُسْعَد، وتجاوز تُحَب، فليس كل فعل يُفسَّر، ولا كل قول يُحاسَب، ولا كل زلّة تُعاتب، أجمل الرد: الصمت، وأكمل العقل: الحِلم والعفو، فمحبة الناس كنز عظيم فلا تزهد فيه، ولا تفرط فيه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1356","text":"البيوت تُبني على مكارم الأخلاق، ومحاسن العادات، وجمال الطباع، وحلاوة اللسان، وسخاء الأيدي، والتسامح والتغافل، والتجاوز والعفو، وغض الطرف.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1357","text":"الأبُ عزٌّ لا يُجارى، وسندٌ لا يُبارى، هو نورُ الدار، ودرعُ الأخطار، رضاهُ فوز، ودعاؤه لأولاده مستجاب، وكلامه لأبنائه نصح وصواب، وصمته وقار وهيبة لأهل الدار، ولكل ابن مطيع بار.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1358","text":"الأم مهبط الرحمات، ومعراج الدعوات، وموطن البركات، ومصدر السعادات، دعاؤها يصعد إلى السماء، ويُرفع به البلاء، ويُستجلب به الرزق والشفاء، رضاها فلاح، وخدمتها نجاح، وقربها جنّات، وبُعدها حسرات وندامات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1359","text":"لا تُصغِ لكل مُرجف، ولا تقبل كل شائعة، فالأراجيف كثيرة، فلا تأخذ إلا ما جاءك من جهةٍ موثوقة مسؤولة، وإذا أتاك اليقين فعض عليه بالنواجذ، ودع عنك قول المُهوّلين والمشعوذين.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1360","text":"الاعتماد على الله ثم على النفس، هي البداية الصحيحة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1361","text":"أداء الواجب له الصدارة في التقديم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1362","text":"القناعة شطر السعادة، والشطر الثاني تحقيق الأهداف.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1364","text":"من لا يُجَرِّب لا يُخطئ، ومن لا يُخطئ لا يتعلم، ومن لا يتعلم يتخلف عن ركب الحضارة، ومن يتخلف عن ركب الحضارة، يجد نفسه معزولا وحيدا فريدا شريدا.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1365","text":"يكسب الموظف تقدير رئيسه له بحسن سلوكه وتصرفاته من خلال: الصدق والإخلاص في العمل. الاحترام والأدب في التعامل. المبادرة وتحمل المسؤولية. الهدوء والانضباط في المواقف الصعبة. الحرص على التطوير والتعاون بروح الفريق.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1366","text":"من اتقى الله في طلاق زوجته، وهبه الله خيرا منها، ومن لم يتق الله في طلاق زوجته، لم يبدله الله بخير منها.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1367","text":"الزوج المثالي: هو من يتّقي الله في زوجته، كريم الخلق، يحسن عشرتها، ويعطيها حقها، صبورٌ في الشدة، شكورٌ في الرخاء. يُشاورها، ويُقدّرها، ويكون لها أمانًا وحنانًا، يعينها على الطاعة، ويقودها بحكمة لا بقسوة. ويعوضها عن حنان أبويها، وعن العش الذي فيه درجت، والبيت الذي فيه تربت، والحب الذي به تدثرت.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1368","text":"تسعة أشياء بُعْدهم دواء: وَزْنُكَ الزّائِد، أثاثك البائِد، ماؤك الراكد، مالك الكاسد، جارُكَ الحاسِد، قَرِيبُكَ الحاقِد، شريكك المعاند، صديقك الجاحد، ضِرسك الفاسد.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1369","text":"فاذا دعوتم الله فاقرنوا دعاءكم بالصلاح، واشترطوا الفلاح.","kind":"hikma","topic":"الإيمان والعبادة","note":"خلاصة قصة سادن الكعبة","source":"شذرات (ملف وورد)"},{"id":"m1371","text":"يُولد الأطفال مزوّدين بالحواس الخمس: السمع البصر اللمس الذوق الشم، وهي نوافذهم إلى الإدراك، وجسورهم إلى الفهم والمعرفة. فواجب الوالدين أن يُشبِعوا هذه الحواس بما ينفعهم في دينهم ودنياهم، وفي أخلاقهم وآدابهم، وبما يقربهم من الله، ويرفع شأنهم عند الناس.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1372","text":"من أكل أكثر من احتياج جسده، خزن الزائد طاقة في بدنه على هيئة شحم ودهون. ومن أكل أقل من احتياجه، كمَّل احتياجه من مخزون طاقته،الذي هو الشحم والدهون. ومن أكل بقدر احتياجه فقد حافظ على وزنه.","kind":"hikma","topic":"الصحة والنفس","note":"تحت عنوان: فلسفة الريجيم – العلاج بالضد","source":"شذرات (ملف وورد)"},{"id":"m1373","text":"الرأيُ بلا بيِّنةٍ وهمٌ، والحُكمُ بلا حجَّةٍ ظلم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1374","text":"الظنُّ لا يُغني، والوهمُ لا يَبني.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1375","text":"الحُكمُ على الشكِّ باطل، والرأيُ بلا دليلٍ عاطل.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1376","text":"الخيالُ لا يُقيمُ ميزانًا، ولا يُثبتُ برهانًا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1377","text":"الأوهامُ لا تُثمرُ أحكامًا، ولا تُقيمُ نظامًا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1378","text":"من بنى حُكمَه على الهوى، جارَ في القَضا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1379","text":"العقلُ لا يركنُ إلى الحُلم، والعدلُ لا يميلُ إلى الوهم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1380","text":"الدليلُ سلطان، والهوى خُذلان.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1381","text":"الأحكام لا تبنى على الأحلام.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1382","text":"أحكام الدين لا تثبت إلا باليقين، واليقين لا يثبت إلا بالدليل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1383","text":"طِبُّ الضدّ: هو علاجُ الشيءِ بضدّه. يعني: تُعالج السُمنة بتقليل الطعام، والهزالَ بتكثيره، والخمولَ بالحركة، والحزنَ بالفرح، والقلقَ بالإيمان والاطمئنان، والكسلَ بالحركة والنشاط. وهو أصلٌ قديم في الطبّ، ومنهجٌ بسيط في تقويم صحة الإنسان، فبطب الأضداد تحقق التوازن بالأجساد، فالصحة والعافية هي أعظم نعمة بعد الإيمان.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1384","text":"الزوجة المثالية: هي من تجمع بين الدين، والعقل، وحسن الخلق، تحفظ زوجها في نفسها وماله، وتكون له سكنًا ورحمة، تؤازره في الشدة، وتشاركه في الرخاء، وتعينه على الطاعة، وتُدخل على قلبه السكينة والسعادة.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1385","text":"تداركُ زلَّةِ الصمت أهون من استدراك زلَّة النُّطق.","kind":"mathal","topic":"الكلام والصمت","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1386","text":"حِفظ ما في الوعاء بشدِّ الوِكاء.","kind":"mathal","topic":"المال والاقتصاد","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1387","text":"ما في يدك محفوظ خيرٌ مما في يد غيرك مأمول.","kind":"mathal","topic":"المال والاقتصاد","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1388","text":"مرارة اليأس أهون من مذلَّة السؤال.","kind":"mathal","topic":"الأخلاق والآداب","note":"مقتبس من وصية علي بن أبي طالب رضي الله عنه لابنه الحسن","source":"شذرات (ملف وورد)"},{"id":"m1390","text":"ما أعظم توفيق الله لعبده أن يمدَّ في عمر والديه، ويهديه لبرِّهما، فتزداد حسناته، ويتضاعف أجره، ويكونان سببًا لتوفيقه في دنياه، ورفعة درجاته في أخراه، ويرزقه الله ذريةً صالحةً تبره وتصله، فبرُّ الوالدين دينٌ مسترد، والسعيد من وفَّقه الله في الدارين: عملًا صالحًا وثوابًا جزيلًا.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1391","text":"رُبَّ كلمة طيبة أغلقت باب عداوة، وفتحت باب صداقة.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1392","text":"من حسُنت أخلاقه طابت عشرته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1393","text":"من كسب الناس بحسن خُلُقه، طوعهم لمحبته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1394","text":"أثقل ما يُوضع في الميزان بعد الإيمان حسن الخُلُق.","kind":"hikma","topic":"الأخلاق والآداب","note":"في معنى حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m1395","text":"ما عُبد اللهُ بشيء بعد الإيمان، أحسن من حُسن الخُلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1396","text":"حسنُ الخلُقِ ستر للفقراء، وزينة للأغنياء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1397","text":"أول لقاء بين المدرس والطلاب: يُعرِّف بنفسه بهدوء وهيبة، ويُوضح أهداف المقرر وأسلوب التدريس. ويضع قواعد الانضباط والتعامل بوضوح، ويزرع الثقة ويُحفز الطلاب على المشاركة، ويبدأ بمعلومة مشوقة أو قصة تجذب الانتباه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1398","text":"الحريةُ الشخصيةُ أن تختار قهوتك أو شايك، مُحلىً أو مُرًّا، ساخنًا أو فاتِرًا، أمّا فرائضُ الدين وثوابتُ اليقين، فامضِ فيها مستقيمًا كما أُمرت، لا ميلَ فيها ولا تبديل لهوى ولا شَطَط ولا تعليل.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1399","text":"س:كيف نتعامل مع الأطفال لاكتساب التميز والتفوق؟ ج: بالحب والقدوة. بالتحفيز والسؤال واشراكهم بالقراءة معهم ومناقشتهم. بتوجيه حواسهم إلى الملاحظة والتجربة. بتقوية الفضول وتشجيع الأسئلة. بضبط السلوك باللين والحزم. بتوسيع مداركهم بالقصص والأمثال. وبالدعاء لهم دائمًا بالتوفيق. حبّب إليه العلم، وعلّمه كيف يتعلم. وبالاستهواء السلوكي في العادات الحسنة، والأخلاق الحميدة، والذوق الجميل والأدب النبيل.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1400","text":"إذا استقام القلب، طاب القولُ والفعل.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1401","text":"من أصلح ما بينه وبين الله، أصلح اللهُ ما بينه وبين الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1402","text":"لا تركن إلى الأماني، فما حُرثت أرضٌ بالأحلام.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1403","text":"سكوت الحكيم حكمة، وصمت الجاهل حلية.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1404","text":"من خاف اللهَ لم يَخَفْ أحدًا، ومن رجاه لم يَرجُ غيرَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1405","text":"كُن خفيفَ الظلِّ، طيّبَ القولِ، حسنَ الفعلِ، عميقَ الأثرِ الصالح.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1406","text":"فالأرض لا تأكل ولا تشرب ولا تموت ولا تمرض ولاتشيخ ولا تهرم، لكنها قد تنام طويلًا إن لم تحسن اختيارها، وتعرف مستقبلها.","kind":"hikma","topic":"المال والاقتصاد","note":"من كلامه عن التجارة في الأراضي","source":"شذرات (ملف وورد)"},{"id":"m1407","text":"الصبر مع التحسين يزيد الربح","kind":"hikma","topic":"المال والاقتصاد","note":"خلاصة أنواع تربص الفرص لبيع الأرض بثمن أعلى","source":"شذرات (ملف وورد)"},{"id":"m1408","text":"كنتَ في ريعان شبابك تسابق الأيام (بسأفعل وسوف أفعل) وتغرس الأحلام في حقول الغد، حتى غدوت شيخًا كُنْتِيًّا، لا تطرق باب حديثك إلا بـ(كان) و(كنا)، تسترجع الأمس وتُحصي ما ولّى. فاعلم أنّ الأعمار ظلّ زائل، وأنّ الحلم بلا عملٍ وهمٌ عاطل، فاعمل لدنياك كأنك تعيش أبدًا، واعمل لآخرتك كأنك تموت غدًا، ولا تجعل (سوف) ذريعةً للتسويف، ولا (كان)حسرةً على التفريط.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1409","text":"بعد زواج البنت، وانتقالها لبيت زوجها، يكون مبدأ الشوق، ومهوى الوَلَه، ومطلع اللهفة، ومورد السعادة الغامرة… إذ تعود في الزيارات لتلتقى بأمِّها وأخواتها وعائلتها، في العشِّ الذي فيه ترعرعت، ومنه درجت، وفي زواياه ذكرياتٌ ندية، وأحاديثٌ دافئة، وحنينٌ لا يزول.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1410","text":"الاتجار في المواشي: مالٌ يأكل المال، والاتجار في الطعام: مالٌ يفسد بطول الزمان، وأما الاتجار في الأراضي: فمالٌ لا يأكل المال، ولا يفسده طول الأزمان، بل يزيده بالأثمان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1411","text":"من يطلب الزرع فعليه أن يحرث الأرض ويرويها بالماء، ومن يطلب الحرية فعليه أن يطلبها بالاجتهاد والعناء.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1412","text":"من لا يتابع الأخبار لا يعلم، ومن يتابعها لا يعرف أين الحقيقة؟","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1413","text":"إذا أردت أن تُقَيِّم إنسانا، فاجعله رئيسا على رأس عمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1414","text":"افعل كل ما تستطيع من خير، في كل زمان ومكان، فهذه هي صفة الإنسان المتصف بصفات الإنسانية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1415","text":"من عمرَ وقتَه بالذكر، عمرَ اللهُ قلبَه بالإيمان والفكر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1416","text":"من طاب أصلُه، طابَ فرعُه، ومن زكا سِرُّه، زكا علنُه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1417","text":"القلوب أوعيةٌ، وألسنةُ الناس مغارفُها، فانظر ماذا تَغْرِف مِمَّا تعرف.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1418","text":"من خافَ اليومَ أَمِنَ الغد، ومن أصلحَ سرَّه أصلحَ اللهُ علانيتَه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1419","text":"إذا ضاقت بك الدنيا والفضاء، فاتَّسِع بالصبرِ والذكر والدعاء.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1420","text":"من جالسَ الحكماءَ رقَّ قلبُه، ومن صاحبَ الأتقياءَ صفا لُبُّه.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1421","text":"واعظُ اللهِ في قلبِ المؤمن إذا تفكر، خيرٌ من ألفِ ناصحٍ بلسانه إذا عَبَّر.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1422","text":"كن كالنحلة، فالنحلة تقع على الأزهار، فمنها العسل نشتار ( نجني ) ولا تكن كالذبابة، فالذبابة تقع على الأقذار، فتنشر الوباء والأضرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1423","text":"الوقت نفحة من العمر، والعمر أنفسُ من أن يُهدر، فلا تُبدّد دقائقك في همٍّ مقيم، أو حزنٍ عقيم، ولا في سفاسف الأقوال والأفعال، فما مضى منه لا يُشترى، وما بقي رأسُ مال، لا يُقدر بأثمان، واستعن بالله الرحيم الرحمن.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1424","text":"رجلٌ افتتح مطعمًا يلقى رواجًا وإقبالًا، فقال له صديقٌ له: إن عمّالك يسرقونك. فقال: أعلم. قال: فلِمَ لا تستبدلهم؟ قال: أولًا، هم يُرَبِّحونني رغم ما يأخذون، وثانيًا، لا أضمن أن من يأتي بعدهم يكون أصلح منهم، فدعك من هذه المغامرة الفاشلة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1425","text":"الصقور تُعرَف بحدّة بصرها وسرعة انقضاضها، لا بزُخرُف ألوانها ولا ببهاءِ هيئتها. وكلاب الصيد تُمدَح ببأسها وسرعتها وخَطْفها، لا بجمال خِلقتها. والأسود تُهاب بأنيابها ومخالبها، لا بجلودها ولَبَدِها. والرجال تُكرَم بسخائها ومروءتها، وسموّ أخلاقها ونُبل سجاياها، لا بجمال مظهرها وهندامها.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1426","text":"تاجرٌ كبير يملك معرضًا عامرًا بالبضائع الواردة إليه من كل صوب، وله مديرٌ ناصحٌ أمين، بارعٌ في عمله غاية البراعة، يدفع له صاحب المعرض مليون دينار في السنة. فعجب أصحابه من كِبَر الأجرة، فقال لهم: إنه يُكسبني في العام أحد عشر مليونًا وأنا مطمئنٌ مستريح، فأدفع له مليونًا، وأحظى بعشرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1427","text":"وصية ذهبية لتربية الذرية تُغنيك عن المجلدات التربوية إن نشأ الطفل العربي في بيتٍ صيني تشبَّع بلسانهم وأخلاقهم وعاداتهم، وإن نشأ الصيني في بيت عربي تشبَّع بلسانهم وأخلاقهم وعاداتهم، تلقائيا من غير معاناة ولا تكلف ولاقصد. العبرة: تربية الذرية خُلطَةُ ومعاشرة ومساكنة، ومحاكاةٍ، واقتباسٍ، واستهواءٍ سلوكيّ. النتيجة: تربية الأولاد تبدأ من تربية الوالدين، فإذا كان الوالدان مستقيمين استقام الأولاد، وإذا كانا منحرفين انحرف الأولاد، فأحسنوا تربية أولادكم باستقامتكم وحسن أخلاقكم. فباستقامة الوالدين يَستقيم الأولاد، وبانحرافهما ينحرف الأولاد.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1428","text":"فالتقليد باب كبير وعظيم لنقل المعارف والثقافات بطريق مُعَبَّد ومُيسر.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1429","text":"اجتماع العائلة الأُسبوعي: يُكسب الأبناء مهارات الحوار والإصغاء واحترام الرأي. ينقل القيم والأعراف والعادات الطيبة بين الأجيال. يربطهم بهوية العائلة وأصولها وجذورها، الذي يقوي عوامل التواصل وأواصر القربى، وصلة الرحم. يفتح لهم أبواب الآداب والأخلاق والأعراف والتجارب.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1430","text":"زار صديقَه الذي افتتح محلًا لبيع الأحذية، فوجده يشكو كساد السوق، وفتور البيع. فألقى نظرةً على الأسعار، فإذا هي زهيدة لا تثير في النفس قيمةً ولا رغبة. فقال له: ارفع الأسعار! فلما زاره بعد شهرين، وجده مسرورًا مُبتهجًا، والبضاعة تُصَرَّف. وهنا يتجلى السِّرُّ: فبعض الناس لا يلتفتون إلى الرخيص، ويظنون أن انخفاض السعر علامة ضعفٍ وقلّة جودة، فإذا ارتفع السعر ارتفعت القيمة في أعينهم، واطمأنوا إلى جودة المعروض فاشتروه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1431","text":"دخل مدير المشتريات لديوان أميرٍ إلى محل بخور، فقال للبائع: أريد أطيب بخورٍ عندك. فأخرج له بخورًا سعر التولة منه ثمانون دينارًا. فقال المدير: أريد ما هو أطيب وأندر. فقال البائع: غدًا يصلني بخورٌ فاخر، لم أعرضه بعد. فلما جاءه في الغد، وانتظر حتى خرج الزبائن البسطاء، فتح البائع خزانةً مقفلة، وأخرج منها وعاءً أنيقًا، فيه البخور نفسه، وقال: هذا التولة بمئتي دينار. فاشترى المدير عشر تولات راضيًا. وما تغيّر البخور ولا نوعه، إنما تغيّر الوعاء، وحُجب عن الأعين، والدهاء في العرض، فغلا ثمنه عند من يظن أنه للأمير أطيب وأثمن.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1432","text":"زلة العالم يُضرب بها الطبل، ويُبخر بها أهل السوق، ويُنفخ بها في البُوق، وتَسير بها الركبان والنوق، وزلة الجاهل كضياء شمعة بعد الشروق.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1433","text":"المرأة تترقب من زوجها كلمات الحب والإعجاب في كل مناسبة وفي كل لحظة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1434","text":"عندما علَّم الله تعالى آدم عليه السلام الأسماء، اكتسب آدم صفة قابلية التَّعَلُّم، وعندما أمره أن يُعلم الملائكة عليهم السلام الأسماء، اكتسب صفة التعليم ونشر العلم، فَوَرَّثْهما لأولاده، فصارتا فَطرة في ذريته. فالطفل في فصل الربيع، إذا وجد فراشة زاهية بألوانها، يراقبها ويتتبعها، فهذه صفة طلب العلم والمعرفة. ثم يرفع صوته: سعد نوح وداد، تعالوا انظروا إلى هذه الفراشة، فهذه صفة نشر العلم والتعليم.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1435","text":"ليس كل خطيبٍ مِصْقَع، ولا داعيةٍ بليغ، ولا واعظٍ مؤثر، ولا مثقف فصيح، ولا مفكرٍ إسلامي مُلهم، أهلًا أن يتصدر للفتوى الشرعية؛ فإن لكل علمٍ رجاله، ولكل فنٍ أهله، ولكل مقامٍ مقال، واحترام التخصص واجب عقلي وعلمي واجتماعي، فالعلم تخصص عمودي عميق، والثقافة تخصص أُفقي شامل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1436","text":"الطريق المستقيم لهداية الملحدين، إلى الإيمان برب العالمين، ومحاورتهم بالعلم والبرهان المبين، ومناقشتهم بالحلم واللين، والاستعانة بدعاء الرحمن الرحيم، فهو الهادي إلى الصراط المستقيم، وكرر المحاولة لعل الله يهديه ولو بعد حين، فتنال مثل ثواب أعماله يوم الدين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1437","text":"الصيد رزقٌ لمن جاع، لا لهوٌ لمن شبع. أباحه الله تعالى لحاجةٍ ونهى عنه لعبثٍ.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1438","text":"يا من أسقط حمامةً بريئةً بلا جوعٍ ولا ضرورة، أتدري أنك تُسهم بتخرب ميزان الطبيعة بطلقةٍ عابثة؟ الصيد الجائر يقتل أجيالًا ويُفني أسرابًا، وما أكثر المخلوقات التي ذهبت ضحية العبث والتفاخر! فاتق الله، ودع ما لا تأكله حيًّا في مأواه، يُسبّح مولاه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1439","text":"إذا أردت أن تُقَيِّمَ قولا أو فعلا، فتفاعل مع القول، ولا تتفاعل مع القائل، فقد يُبهجك الصغير، ويخذلك الكبير.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1440","text":"مقاولو البناء، يقتات بعضهم على جهل الناس بتفاوت الأسعار وجودة المواد، فيسوقون الحيلة ويزرعون الخداع.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1441","text":"لا تتعامل إلا مع مقاول مشهود له بالجودة والأمانة والصدق في المواعيد، ولو كان سعره أغلى، فهو أولى، وعاقبته أحمد وأحلى.","kind":"hikma","topic":"المال والاقتصاد","note":"في سياق الحديث عن مقاولي البناء","source":"شذرات (ملف وورد)"},{"id":"m1442","text":"من حسن اللقاء التحية والاستبشار، ومن حسن الفراق: الدعاء والمحافظة على الأسرار.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1443","text":"اختلاف وجهات النظر ظاهرة صحية، يتقبلها ذوو النفوس النقية، والطباع السوية، والعقول الذكية.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1444","text":"تتعرّف على شخصية الإنسان من خلال: دينه وأخلاقه: لتعرف ظاهره وباطنه. كلامه: فحديثه يكشف فكره وطباعه. سلوكه: فالأفعال أصدق من الأقوال. تعامله مع الآخرين: خصوصًا مع من دونه، ومع من لا مصلحة له معهم. رده في المواقف الصعبة: فالشدة تكشف المعادن. اختياره لأصدقائه: فالمرء على دين خليله.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1445","text":"إن عزمت على الزواج، فالتمس الخُلق والأدب والدين. وإن هممت بالبناء، فالتمس المقاول الأمين الناصح المنجز بشهادة من بنى لهم من العالمين. وأما دينه وعمله وتصرفاته فحسابها عليه، لا عليك. فخذ منه ما صفا لمقاصدك، ودع له ما كدر لنفسه لا لك.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1446","text":"الفقه الإداري، في التعامل المثالي إن كنت جديدا في موقع عمل، كيف تستطيع أن تُعطي فكرة إيجابية عن نفسك: لرؤسائك وزملائك ولم دونك؟ مع رؤسائك: كن منجزًا ودقيقًا، استمع جيدًا، نفّذ بذكاء، واطرح أسئلة تدل على فهمك واهتمامك. مع زملائك: كن متعاونًا، لبقًا، مُبادرًا بالمساعدة، وتجنب الغيبة والنزاعات. مع من دونك: عاملهم باحترام، شجّعهم، قِدْهم بالقدوة، وكن عادلًا ولينًا في آنٍ معًا.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1447","text":"نصيحة للمتقاعد: اشغل وقتك بذكر الله، وبما تُحب وينفعك، ولا تعتزل الناس والمشي والجديد، حتى تواكب العصر.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1448","text":"أسباب شيطانية لمن يعبد الحجر أو البقر أو الشمس والقمر، ويكفر بالله رب المخلوقات والبشر، ورب السماوات والأرض والنجوم والقمر، إما جهلًا أو تقليدًا، أو هوًى، أو استكبارًا، أو هروبًا من الحق خشية التكاليف والقيود، أو طلبا للمحرمات والشهوات وانتهاك الحدود.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1449","text":"الوتساب ما يُحب التغريدات الطويلة ولا الكتاب، يُحب الشذرات والنتف من أولي العقول والفهم والألباب.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1450","text":"الرجل أوتي بنية جسدية أقوى، وصبرا على المشقة، وميلا للاقتحام والمخاطرة، فكان أقدر على الكسب والسعي. والمرأة جُبلت على الرقة، والصبر، والحنان، وحسن الاحتواء، فكانت أقدر على التربية ورعاية شؤون البيت. فسبحان من أعطى كل نفس هداها، وأعانها على القيام بشؤون دينها ودنياها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1451","text":"بعض الكلاب أوفى من بعض الأصحاب","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1452","text":"أصعب ما يواجه الحُرُّ أن يُقنع من عاش عبدًا دهرا أنه يستطيع أن يكون حرًّا. لأن العبد حين يصدق أنه عبد، يريح نفسه من همّ القرار والتفكير. فيطمئن للقيد أكثر من خوفه من الحرية. وهكذا يصير التكيّف نعمة حين يُسكِّن الألم، ونقمة حين يُسكِت صوت الحرية. فيحتاج إلى مهلة لإقناعه أنه حُرٌّ، مع بيان مساوئ العبودية، ومحاسة الحرية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1453","text":"الاستعجال في اتخاذ القرارات الجسيمة، والمبادرة إلى الأفعال العظيمة، وأنت في أتون انفعالٍ جامحٍ، قبل رويةٍ ونظرٍ في العواقب، سبيلٌ إلى الندامة ومظنّةٌ للحسرة. فالعجلة أمُّ الندامة، وبنتُ الخيبة، والقرار ابنُ الرويّة، وثمرةُ التأني والبصيرة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1454","text":"فكّر إذا هممت، وتأنَّ إذا عزمت، فما ندم متأنٍّ قط، ولا سلم مستعجلٌ اشتط.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1455","text":"أفضل وقت لشراء العقار هو أمس.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1456","text":"لا تنتظر لشراء العقار، اشتر العقار ثم انتظر.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1457","text":"الأرض لا تأكل ولا تموت.","kind":"mathal","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1458","text":"اشتر العقار لأولادك الصغار.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1459","text":"اشتر الأراضي فسوف تبيعها وأنت راضي.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1460","text":"ما أعظم نعم الله على الإنسان وما أعظم غفلة الإنسان عن الحمد والشكر الشمس تُضيء العالم في جميع الزمان بالمجان الحمد لله ثم الحمد لله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1461","text":"الهداياُ الغاليةُ تفتحُ الأبوابَ الموصدة، وتقرِّبُ القلوبَ النائيةَ، وتُلَيِّنُ النفوسَ النافرة، وتُحيي الودَّ، وتزرعُ البسمةَ، فهي مفاتيحُ القلوب، ورسائلُ حبٍّ بلا حروف، تُحَسِّنُ الظنَّ، وتزيل الصدود.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1462","text":"التصرّف الأمثل للزوج إذا غضب، أو للزوجة إذا زعلت: كظمُ الغيظ قبل أن يستفحل، وضبطُ اللسان قبل أن يزل، وحُسنُ الظن إذا اختلطت الظنون، ولينُ الخطاب إذا اشتدّ العتاب. بادرْ بالصلح، ولو كنتَ المُحقّ، فإن الشيطان يُؤجّج، ويُوسوس، ويُفرّق. لا تُنشر الغسيل خارج البيت، فالستر أكرم، وأحكم. وتذكّر لها من المحاسن أجملها، ومن المواقف أطيبها، لتبقى المودّة موصولة، والقلوب صافية، والبيت محفوظًا عامرًا بالعفو والعافية.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1463","text":"بعض الزوجات تشتري فستانا من المعارض بمائة دينار من مال زوجها لتتزين به للناس، وتشتري من البسطات فستانا بعشرة دنانير لتلبسه لزوجها. والواعية تلبسه أولا لزوجها مرة أو مرتين، وتشكره وتدعو له، لِتَسُرَّ خاطره وتُسعده.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1464","text":"اليد هي التطبيق العملي للحضارات والثقافات والتقدم والرقي.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1465","text":"فالإسلام يحرص على تأليف القلوب، ويرفض كل ما يُشعل العداوة، أو يَزرع البغضاء، ويأمر بالتواصل، والتهادي، والتعاون بين ذوي القربى.","kind":"hikma","topic":"الإيمان والعبادة","note":"في سياق تحريم الجمع بين المرأة وعمتها أو خالتها","source":"شذرات (ملف وورد)"},{"id":"m1466","text":"إذا كانت جنةُ المتقين عَرضُها السماواتُ والأرضُ، فكم يكون طولُها؟ وإذا كان لكل مؤمن فيها نصيبٌ، فكم يبلغُ نصيبُه؟ وعلى قدر سعيك يكون نصيبك. جنةٌ بهذه السَّعة، ألا تستحقُّ أن نُسارِع إليها سَعيًا، لا مشيًا؟ بادر قبل أن يُحال بينك وبين الطاعات، فإن الجنة عظيمة، والسعي يزيد في نصيبك منها.","kind":"hikma","topic":"الإيمان والعبادة","note":"تأمل في قوله تعالى: (وسارعوا إلى مغفرة من ربكم وجنة عرضها السماوات والأرض)","source":"شذرات (ملف وورد)"},{"id":"m1469","text":"القروب الذي يخلو من التعليق والتعقيب، والثناء والتصويب، والمشاركة والمناقشة، والفائدة والشاردة، والمثل والحكمة، والفكاهة والبسمة؛ قروب خامد كجمرٍ هامد، باهت كصدى خافت، كسول كمريض شاحب هافت.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1470","text":"ما عجزتَ عن جلبه من رزقٍ أتاك كما يأتيك المطر، لأنك لا تقدر على إنزاله فهو يأتيك. وما قدرتَ عليه فلا يأتيك وأنت قاعدٌ حتى لا تُصاب بداء العجزة. فمن وهبك العقل واليدين والرجلين فقد أمرك بالسعي لطلب الرزق أمرًا قدريًا.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1471","text":"السعيُ مفتاحُ الرزق، فمن سعى رُزق، ومن لزم البيت حُرم الخبزَ والتمرَ والزيت، ومن قنع استراح، ومن طمع لم يسلم من الانتقاد والجراح.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1472","text":"من جدَّ وجد.","kind":"mathal","topic":"النجاح والإبداع","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1473","text":"من صبر ظفر.","kind":"mathal","topic":"الصبر والشدائد","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1474","text":"قليل دائم خير من كثير منقطع.","kind":"mathal","topic":"النجاح والإبداع","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1475","text":"لا تؤجل عمل اليوم إلى الغد.","kind":"mathal","topic":"الحياة والزمن","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1476","text":"الصدق منجاة.","kind":"mathal","topic":"الأخلاق والآداب","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1477","text":"لكل مقام مقال.","kind":"mathal","topic":"الكلام والصمت","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1478","text":"الكذب حبله قصير","kind":"mathal","topic":"الأخلاق والآداب","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1479","text":"القناعة كنز لا يفنى.","kind":"mathal","topic":"المال والاقتصاد","note":"من «عشر حكم» أوردها","source":"شذرات (ملف وورد)"},{"id":"m1480","text":"من فوائد الحكمة: تعينك على ترتيب الأولويات. تجعلك تحسن اتخاذ القرار. تحفظك من الزلل والعجلة. تبصّرك بعواقب الأمور. تكسبك احترام العقلاء. تهديك إلى خير الأقوال والأفعال. تقيك الندم وسوء العاقبة. تنير لك دروب الحياة. تزيدك وقارًا وهيبة. تقرّبك من رضا الله ثم رضا الناس. علموا أولادكم الحكمة.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1481","text":"إنَّ اللهَ امتنَّ على الإنسان بنعمةِ العقل، وأعضاءٍ متينة، ومفاصلَ مرنة، بها يُحسن التصرّف ويتكيَّف مع المستجدات، فيسعى لجلب المنافع والمصالح، ويجتهد في دفع المضار والمفاسد. فسبحان الله المُنعم المُتفضل على جميع مخلوقاته، بجليل النِّعم، وعظيم المِنَنِ","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1482","text":"طلب الرزق طاعة وعبادة إذا اقترن بالوجه المشروع والنية الصالحة، وإلا فهو غريزة من الغرائز يشترك فيها الإنسان وسائر المخلوقات والحيوان.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1483","text":"مَن حُرِمَ الانتفاعَ بعلمِه، وقعَ أسيرَ ضررِ جهلِه.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1484","text":"فِقهُ الاقتصادِ في الإسلام قائمٌ على بَسطِ الثروةِ وتوسيعِ دائرتها بين الناس، بفرائضَ محكمةٍ كالزكوات، ونوافلَ جليلةٍ كالصدقات، وكفّاراتٍ مُطهِّرة، ومواريثَ مقسومة، ووصايا مشروعة، وغنائمَ مقسَّمة، وأوقافٍ دائمة، ليظلَّ المالُ دُولةً بين أفرادِ المجتمع، لا حِكرًا على أغنيائِه.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1485","text":"ربو أولادكم بتربية أنفسكم، منذ نعومة أظفارهم، فهم يحاكونكم فطرة، ويقلدونكم طبيعة، فعيونهم ترقبكم لتفعل مثل فعلكم.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1486","text":"التقليد والمحاكاة من أقوى وأوسع وأيسر أبواب العلم، التي أودعها الله في المخلوقات، وجعلها فطرة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1487","text":"المرأة كالفراشة الرقيقة، والزهرة الناعمة، فتعامل معها بلطفٍ ولينٍ ورقّة، وابتعد عن كل ما يجرحها أو يخدش كبرياءها وحياءها. فهي تزهر بالودّ والاحتواء، وتذبل بالقسوة والجفاء.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1488","text":"أفضل وأيسر طريق لتحويل العدو لصديق: كظم الغيظ، والعفو عن الزلات، وإظهار الإحسان عند القدرة، ومقابلة السيئة بالحسنة، مع الصدق والثبات على ذلك حتى يرحل الجفاء ويحل محله التقارب والود والوفاء.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1489","text":"فالقلب يفتح بالمحبة، والعقل يقتنع بالبرهان، والروح تهتدي إذا اجتمعا مع النصح والصبر.","kind":"hikma","topic":"الإيمان والعبادة","note":"خلاصة كلامه في أفضل طريقة لمناقشة الملحد لهدايته","source":"شذرات (ملف وورد)"},{"id":"m1490","text":"أهم صفات علماء السوء: ١-بيع الدين بعرض من الدنيا. ٢-ليّ النصوص لخدمة السلطان أو الهوى. ٣-كتمان الحق وتزيين الباطل. ٤-حب الظهور والجدال للرياء. ٥-الانشغال بالشهرة والمال عن العلم والعمل.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1491","text":"بعض القنوات لا تستضيف إلا أهل الأهواء، وعلماء السوء والشذوذ، لتُزيّن الباطل وتستدرّ المشاهدين، وتجعل من الانحراف بضاعة، ومن الفتنة صناعة، ومن تضليل العقول وسيلة لبلوغ غاياتها الربحية والمادية والكسبية، إنهم ينشرون التشكيك في اليقينيات، ويثيرون الشبه حول المسلمات.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1492","text":"أقوى بواعث العناد والعصيان، والجحود والكفران: الجهل، واتباع الهوى، وإغراء الشهوات، والاغترار بالدنيا، وتأثير رفقاء السوء، وكبرياء النفس عن الحق، ووسوسة الشيطان… وهذه تجتمع فتغشي البصيرة، وتجرّ صاحبها لمعاداة طريق السلامة، وهو الإسلام.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1493","text":"إن أطلقْتَ لسانَك بغير حقّ، كَثُر عليك الخصام، وزاد عليك الملام، وسَخِطَ عليك الملكُ العلّام، واضطرب قلبُك وقلَّ الأمان، أمّا إن نطقتَ بالحقّ ابتغاءَ وجهِ الرَّحمن، فلك الثواب والأمان، من الكريم المنان، وأثنى عليك الأنام.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1494","text":"أخطر أنواع الصراع هو الصراع الداخلي، حين يتنازع الإنسان مع نفسه بين ما يعرفه حقًا وما يفعله باطلا، أو بين ما يريده وما يخاف منه، أو بين قناعاته وواقعه، وبين نوازع الخير ونوازع الشر، بين الأنسان وبين قرينه الشيطان، هذا نزاع دائم ولاينقطع، فاستعن عليه بذكر الله تعالى، والأذكار المأثورات والمعوذات، ومصاحبة الأخيار والصالحين من الأفراد والمجموعات.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1495","text":"القناعة رأس السعادة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1496","text":"الأمانة تاج الصيانة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1497","text":"النزاهة سبيل العزة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1498","text":"الشجاعة عزّ المناعة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1499","text":"الصدق نعم الرفيق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1500","text":"الحِلم زينة العلم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1501","text":"العدل عماد الحُكم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1502","text":"الصبر مفتاح الظفر.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1503","text":"الكرم عنوان الشِّيَم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1504","text":"الوفاء أصل الصفاء.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1505","text":"التواضع سبب المحبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1506","text":"من صور التعاون والتكامل بين الشعب والحكومة: 1.التشريع والتنفيذ: الحكومة تضع القوانين وتنفذها، والشعب يلتزم بها ويشارك في تطويرها. 2.الأمن والاستقرار: الحكومة توفر الحماية، والشعب يتعاون بالانضباط والوعي. 3. النهضة والاقتصاد: الحكومة تهيئ الفرص والموارد، والشعب يسهم بالعمل والإنتاج.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1507","text":"تربية الأطفال على المشاركة في أعمال المنزل حسب أعمارهم. مشاركته تزيده في تحمل المسؤولية والترقي شيئا فشيئا. جهد يمنحه القوة والنماء. تعاون يغرس المودة والصفاء. نظام يورثه الهِمّة والارتقاء واستعداد يبني المستقبل بالرقي والاستعلاء. وغيرها كثير من الخصال الجليلة، والأعمال النبيلة، والصفات الكريمة، فتصبح له عادة فتخف على نفسه مزاولتها والقيام بها.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1508","text":"كثيرٌ من الناس إذا سمع بفاكهة أو عصير فيه فوائد، بالغ في تناوله كما وكيفًا، حتى تنقلب الفائدة ضررًا؛ والنصيحة: خذ من الطعام والشراب بقدر، ولا تُسرف فتجلب الضرر؛ فالاعتدال دواء، والإفراط خطر وداء.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1509","text":"الزوجة وعموما المرأة، متقلبة الأطوار، وسريعة في اتخاذ القرار، ولا تقدر على حفظ الأسرار. فالنصيحة: خالطها بالحلم، ودارها بالحكمة، وأحطها بالمودة، فإن صبرك عليها دواء، وحلمك شفاء، ورفقك بها بقاء.","kind":"hikma","topic":"الحياة الزوجية","source":"شذرات (ملف وورد)"},{"id":"m1510","text":"عند الاضطراب الأمني يُخزّن الناس حاجاتهم في البيوت، أما في حال الأمن، فاعتبروا كل ما في الجمعيات ملكًا لكم، يصل إليكم بالهاتف متى شئتم. فلا داعي للمبالغات في كثرة الثلاجات- والفريزرات- وكثرة المعاناة، وفساد بعض المخزونات.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1511","text":"النصيحة الذهبية للموظف الجديد: أخلص العمل، واضبط الوقت، وأتقن المهام، وتعلّم بعينيك ولسانك وأُذنيك، واطلب العون بلطف، واحترم النظام، وحافظ على الأخلاق، ووسّع علاقاتك الإيجابية، وكن صبورًا مثابرًا، فهذه مفاتيح النجاح والرفعة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1512","text":"من أرقى صور العدالة وحسن التدبير، أن تُشرك الحكومةُ مواطنيها على مختلف طبقاتهم، في كل ما يمس حياتهم، من قوانين وعقوبات وقرارات ومزايا. فتعرضها على نُخبة منهم؛ لتستضيء بآرائهم، وتستفيد من ملاحظاتهم، فتضمن العدل في مضمونها، والقبول في تطبيقها، والاستمرار في أثرها. فالإشراك في الرأي، فطنةٌ وكياسة، وهو من حق المواطن وواجب الحكومة، وعدم الإشراك مزلة قدم، يعقبها حسرة وندم، وطعن في الأمانة والذمم.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1513","text":"اكسب ودَّ زوجتك بلين الكلام، وطيب المعاملة والسلام، وحسن الدلال وترك الملام، وصِدق الوفاء مع الاحترام، وإشعارها بالمودة والاهتمام، فإن القلب يُملك بالرحمة والحب على الدوام.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1514","text":"كثير من الناس ميّالون إلى التهويل والمبالغة والتفخيم، فيعرضون آراءهم في صورة قطعية إلزامية، لا تقبل نقاشًا ولا تدقيقًا، ولا تعقيبًا ولا تمحيصًا، وعند المراجعة والتدقيق، يظهر الأمر خلاف ذلك، فعلى الإنسان أن يجعل له خط رجعة ومراجعة، ولا يُبالغ في الجزم، وفوق كل ذي علم عليم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1515","text":"أعنِ الشاب المنطوي بالرفق واللين والاحتواء، وإشعاره بالأمان والسلامة والاهتمام، وجذبه بلطف الحديث والكلام، ومشاركة اهتمامات الأنام، حتى يألف الانبساط والخروج من طي الظلام، شيئًا فشيئًا بسلام.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1516","text":"اكسب ودَّ جارك بالسلام والابتسام، وبذل السلامة والإهداء والإكرام، وكفِّ الأذى وتحمّل الخطأ، والمشاركة في السرّاء والضرّاء، فإن القلوب تأسرها المودة والاحترام.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1517","text":"أيها المسلمون، المسلم أخو المسلم، ينصره ولا يخذله، فنصرةُ المظلومين منكم فريضة واجبة، ولكلٍّ قدرُه ونصيبُه؛ فالمدني بالدعاء والتبرع والكلمة والمقاطعة. والحكومات بما أُوتيت من سياسة واقتصاد وإعلام ودبلوماسية ومقاطعة وسلاح وجنود. فللنصرة أبوابٌ شتى، وعلى المسلمين جميعًا، حُكّامًا ومحكومين، أن يسعوا إليها بكل وسيلة متاحة، حتى تُرفع المظلمة وتُبرأ الذمّة.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1518","text":"الحاجة أمُّ الاختراع، والمضطر يركبُ الخطر، والشدّة تُلهمُ الحيلة، والفاقةُ تُخرجُ الحلول الدخيلة.","kind":"hikma","topic":"الصبر والشدائد","note":"يتضمن المثل المعروف: الحاجة أم الاختراع","source":"شذرات (ملف وورد)"},{"id":"m1519","text":"فلسفة الريجيم: من أكل أكثر من احتياج بدنه فهو يبني، ومن أكل أقل من احتياج بدنه فهو يهدم، ومن أكل بقدر احتياج بدنه فهو لا يبني ولا يهدم.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1520","text":"ثمرة التجارب لا تكذب، فنتائجها يقينية، ودروسها واضحة، وثمرتها مرضية، توفر عليكم الوقت والمال والمعاناة المضنية، فاغتنموها ولا تفرطوا بها، أقل مجهودا، وأكثر علما، وأوثق نتائجا. فجالسوا كبار السنِّ من العلماء والخبراء والأتقياء، لتستفيدوا من تجاربهم وخبراتهم ونصائحهم.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1521","text":"القوانين التي وُلدت في ظروف استثنائية أو تحت ضغط الانفعال وردود الأفعال، أحوج ما تكون إلى مراجعة هادئة متأنية، إذ العجلة تورث الخلل، والانفعال يطغى على ميزان العقل. وما شُرع في ساعة اضطراب قد لا يصلح لزمن استقرار، فالمراجعة هنا ليست نقضًا ولا نقصا، بل تصويبٌ وعدلٌ ورحمة بالناس، وحُسنُ سياسةٍ يرفع الحرج ويعيد الأمور إلى نصابها، والنفوس إلى قناعتها واستقرارها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1522","text":"الماضي أقدارٌ قد خُطّت، وأيامٌ قد مضت، لا يُعاد زمانها، ولا يُسترجع فقدانها، فلا تذرف دمعًا على ما لا يعود، ولا تُشغل قلبك بندم لا يُجدي، واجعل من عِبر الأمس سُلَّمًا للغد، ومن حكمة التجربة نُورًا للطريق. فمن اتخذ الندم مركبًا، طال مسيره وتاه مصيره، ومن جعل الحكمة زادَه، والعبرة دليله، رَسَت سفينته، وبلغ مأمنه، وأدرك غايته.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1523","text":"تكسبُ الأصدقاءَ بحُسن الخُلُق، ولين الطبع، وسلامة الصدر، وعذوبة اللسان، وصدق المعاملة، وكفِّ الأذى، وبذلِ الندى، وتقديم المساعدة عند الشدائد، وإظهار الشكر عند الموائد، وقلة الجدال، وترك الفضول من الكلام، وغض الطرف عن الزلل، والثناء على محاسن العمل، والحفاظ على المودة والتجاوز عن الخطأ والخلل.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1524","text":"اختلاف وجهات النظر نعمةٌ جليّة، وسنة بشرية، وسمة انسانية، لا يعي قدرها إلا ذوو النفوس الزكيّة، والطباع السويّة، والعقول الذكيّة. فهي بابُ آفاقٍ بهيّة، وجسورُ روابط قويّة، وثمارُ نتائج مرضيّة، ومدخلُ حلولٍ عصريّة، تحفظ الحقوق الشرعيّة، وترعى المصلحة العليّة. فطوبى لمن جعل الخلاف وسيلةً سويّة، ورحمةً خفيّة، وحكمةً ربّانيّة، وأخلاق ذهبية، وهداية لأفضل الآراء السنية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1525","text":"أفلح من جمع بين الخوف والرجاء، والطاعة والإخلاص، والتوبة والاستغفار، والعزة والتواضع، وحسن الظن والحذر، والصبر والشكر، والعدل والإحسان، والعلم والعمل، والقناعة والرضا، والزهد والورع، والرحمة والرفق، والشجاعة والحلم، والحياء والكرم.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1526","text":"( العزائم والرخص ) الدين مبني على العزائم، لصيانة أحكامه من التفريط، واتقاء الشبهات، والاحتياط من التساهل في التطبيق. والرخص يُلجأ إليها لرفع الحرج عند المشقات، وكلا الاتجاهين صحيح إذا استندا إلى الدليل، وإنما الخطأ في الإفراط أو التفريط.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1527","text":"الأمر إذا ضاق اتسع، وهذه قاعدة محكمة، دلّ عليها قول الله: وما جعل عليكم في الدين من حرج. فمنها: المشقة تجلب التيسير، و الضرورات تبيح المحظورات، و الحاجة تنزل منزلة الضرورة، والحرج مرفوع، و ما لا يدرك كله لا يترك جله، وغيرها. فالشريعة جاءت بالعدل والرحمة، لا بالعنت والمشقة، فإذا ضاقت السبل فتح الله باب الرخصة، وإذا زالت المشقة عاد الحكم إلى أصله.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1528","text":"كُلْ في بيت أخيك، ولا تنم عنده. ونَمْ في بيت أُختك، ولا تأكل عندها.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1529","text":"اشتر الجار قبل الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1530","text":"طِيب الدار من طِيب الجار. سُوء الدار من سُوء الجار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1531","text":"لولا طِيب جاري لبعت داري. لولا سُوء جاري لما بعت داري.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1532","text":"طِيب الجار يزيد في ثمن الدار. سُوء الجار يُنقص من ثمن الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1533","text":"اسأل عن الجار قبل الدار.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1534","text":"جاري كَرَّهَني في داري. جاري حَبَبَ إلى داري.","kind":"mathal","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1535","text":"الدين أصول ثابتة نصوصها قطعية، تصون الملة من التغيير والتبديل، وله فروع قائمة على القياس والاجتهاد، لا تعارض الأصول ولا تخرج عنها. فالأصول حصن راسخ لا يزول، والفروع مرنة تمكنه من مواكبة الزمان والمكان وتحقق المصالح المأمولة. ومن ثم فالدين صالح لكل عصر، باقٍ على مر الدهور، مهما تطور الإنسان وطال الزمان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1536","text":"البيت يقوم على أساس متين، وأركان راسخة، وعُمد مسلّحة بالحديد تحفظ بنيانه من السقوط، وعلى جدران وحواجز قابلة للتغيير والتحريك وفق الحاجة. وكذلك الدين: أصول قطعية ثابتة، تحفظ الملة وتصون حقيقتها، وفروع اجتهادية عقلية منبثقة من تلك الأصول، تواكب النوازل والحاجات، وترسم الحدود والأحكام المستنبطة من النصوص. فالدين ثابت بأصوله، متجدد بفروعه واجتهاداته، مستمدة دومًا من ينابيعه الصافية؛ صالح لكل إنسان، ولكل زمان ومكان.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1537","text":"ولأن النصوص محدودة، وحاجات الناس غير محدودة، شُرع الاجتهاد والقياس ليستنبط العلماء من الأصول ما يحقق المصلحة، ويحفظ المقاصد، ويصون الحقوق، ويرفع الحرج والعنت عن الناس.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1538","text":"طوبى لمن لازم الذكرَ والدعاءَ والاستغفار، في الليلٍ والنهار، فقد أحاط نفسَه بحصنٍ حصين، يقيه كيدَ الشيطان وشرَّ الأشرار، وفوق هذا هو جليس الوهاب المَنَّان، وتظلله ملائكة الرحمن.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1539","text":"الأطفال جُبلوا على حبّ المعرفة، وولِدوا بشغف الاكتشاف والفهم، فلا يزالون يكثرون من السؤال والاستفسار، ويغترفون من التفهيم والتلقين، ويتعلمون بالمحاكاة والتقليد، ثم يترقَّون بالحوار والنقاش، والتجربة والشرح، حتى يكتمل العقل، ويصفو الإدراك، ويشرق القلب بنور الفهم. ومن ثَمّ، فواجب الأبوين أن يفتحوا أمامهم الأفق، ويُرووا عطشهم، ويُغذّوا شغفهم؛ فإنها الخطوة الأولى إلى النبوغ، ومفتاح العبقرية، وبذرة التميّز في قادم العمر.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1540","text":"الكلُّ حكيمٌ ما دامتِ القصةُ ليست قصتَه، وكريمٌ ما دام المالُ ليس مالَه، وصبورٌ ما دامتِ المصيبةُ ليست مصيبته، وبطلٌ ما دامتِ المعركةُ ليست معركته. فلا تحكمْ قبل أن تتخيل نفسك في الظروف نفسها، ولا تذمْ غريقاً وأنت على اليابسة، فلا تَلوم الناسَ وأنت تجهلُ ظروفهم. واعلمْ أن سعادةَ غيرك لا تُنتقصُ من سعادتك، وغناه لا يحرمُك رزقك. فكن عادلاً تقياً، عاقلا سخيا.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1541","text":"من الغُبن والجَور أن نُقيم ندوةً نُهوِّل فيها سلبيات الخدم ونتعامى عن إيجابياتهم، ونذمُّ من نستقدم ونبذل في سبيلهم المال، بلا صوتٍ يُدافع عنهم، ولا ندوةٍ تُبين سلبيات المخدومين، وهم الأشد تقصيرًا والأعظم تجاوزًا؛ فذلك ظلمٌ بواح، وحكمٌ غير راجح ولا راشد، إن الله لا يُحب الظالمين، ويكره المعتدين.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1542","text":"آفة الكذَّاب النسيان.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1543","text":"الصدق يُنجي صاحبه والكذب يفضح صاحبه.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1544","text":"الصدق طُمأنينة والكذب ريبة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1545","text":"الكذَّاب يحتاج إلى ذاكرة قوية.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1546","text":"الكذَّاب يفقد ثقة الناس به، ويخسر سمعته.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1547","text":"الكذاب لا يصلح أن يقود الجماهير.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1548","text":"الحياة مدرسةٌ كبرى، دروسها التجارب، والإنسان فيها يتعلّم من نجاحه كما يتعلّم من إخفاقه؛ فكل تجربة تزيده خبرة، وتمنحه عبرة، وتقوّي عزيمته. ثم يجعلها الله سبيلاً لتيسير أمره، وشرح صدره، وتعويضه خيرًا مما فاته أو أُخذ منه.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1549","text":"فلسفة المخالفات والعقوبات، تقوم على التناسب، فالعقوبة وسيلة للردع والتقويم، لا للانتقام أو الجباية، فتقدّر بقدر جسامة الفعل وخطره. ووجه عدم التناسب، إذا زادت العقوبة كثيرًا عن حجم الضرر، صارت ظلمًا أو وسيلة ابتزاز، وفقد القانون هيبته وصار مثارًا للسخط. وإذا نقصت العقوبة كثيرا عن حجم الضرر، صارت وسيلة لارتكاب المخالفات، وعدم المبالات. الخلاصة: العدل في العقوبات أن تردع المخالف بلا ظلم، وتؤدبه لمنع الاستهتار بالقوانين والنظام، ويتقبلها العقلاء وعامة الأنام. وأن لا يُقرر المُشَرِّع العقوبة وهو متأثر بردود الأفعال، فيرجح عاطفة الحماس على حكمة العقل، فيقع في الزلل والخلل والقصور في ثمرة العمل.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1550","text":"بعض ضعاف النفوس إذا أرهقته بالعقوبات المالية، سوف يتجه إلى الطرق الملتوية، ليسد الفجوة المالية، فالكلب إذا حُوصر عقر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1551","text":"الحكمة الشرعية والكونية من مشروعية صلاة الكسوف والخسوف: تذكيرٌ للعباد بقدرة الله وعظمة سلطانه، وأن هذه الآيات الكونية الجارية على نواميسٍ محكمة سنَّها الخالق سبحانه، وسخَّرها لمنافع خلقه، إنما يجعلها الله تخويفًا لعباده وتنبيهًا لقلوبهم، ليهرعوا إلى الصلاة والذكر والدعاء والخشوع والتوبة، فيزداد يقينهم، وتعلّقهم بمسبب الأسباب وخالقها جل شأنه.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1552","text":"( فَنُّ التعامل مع الزوجة ) إذا غيرتْ لون شعرها، ثم قالت لك: ما رأيك؟ لا تخبرها برأيك لأنها لا تريد رأيك، بل تريد أن تقول: أنت جميلة والآن أصبحت أجمل. إذا أردت أن تسافر يومين، فقلت: ماذا تريدين مني هدية؟ قالت: لا داعي للهدية، معناها: لازم تأتيني بهدية. إذا قالت: قل رأيك بصراحة، ما أزعل، لا تقل رأيك، بل قل ما تحب أن تسمعه هي. إذا شعرتَ أنها حزينة، فسألتها فقالت: أنا زينة، فاسكت، ولا تحاول أن تنكشها.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1553","text":"زوج ابنتك صهرك، وهو ستر وغطاء لابنتك، فأكرمه واحترمه، ليحفظ لك ذلك في إكرام ابنتك، ولا تُخاشنه أو تحتقره فينعكس وبال ذلك على ابنتك، فِلْذَةُ كَبِدِك.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1554","text":"من طابت قهوتُه، وعَبِقَت رائحتُها، وسطع شذا بخورِه، وحَسُن ترحيبُه وحضورُه، وتهللت أساريرُه ووجوهُ زُوَّاره، عَمُرَ ديوانُه، وكثر إخوانُه وخِلَّانُه، ودامت له المحبةُ والبركة، وتتابع عليه الخير والنعمة المشتركة.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1555","text":"اجعل زيت الزيتون والعسل جزءًا ثابتًا من غذائك، لكن لا تعتمده كعلاج مباشر أو سريع، بل كوسيلة وقاية ودعم للصحة العامة.","kind":"hikma","topic":"الصحة والنفس","note":"بعنوان: النصيحة الذهبية","source":"شذرات (ملف وورد)"},{"id":"m1556","text":"الأطعمة كلها فيها منافع، لكن العافية في الاعتدال، والتنوع مفتاح السلامة، وما زاد عن الحد انقلب إلى الضد، فخذوا من كل شيء بقدر، تهنؤوا بالصحة وتغنموا العافية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1557","text":"القرآن هو الموسوعة الكونية العلمية الإلهية الخالدة، جمع كمال البيان مع كمال البرهان، أتى بأقصى المعاني في أوجز الألفاظ، وبأيسر النطق في أبلغ الجمل، وفي تلاوته جمال يملأ القلوب جلالًا، جمع بين الهداية والتشريع، والبلاغة والإعجاز، والعلم والنور، فهو كتاب الحياة، ومرجع الهداية، وحبل الله المتين، ومعجزة الدهر المبين، والحمد لله تعالى.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1558","text":"أربع أكلات موبقات مهلكات: أكلُ مال اليتيم ظلمًا، وأكلُ الربا حربًا لله ورسوله، وأكلُ لحم أخيك غيبةً ونميمة، وأكلُ أموال الناس بالباطل غصبًا وظلمًا. هي نارٌ تحرق الحسنات، وتورد صاحبها موارد المهلكات والمحرقات.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1559","text":"لو نُصرت البوسنة أول أمرها، ما تجرّأ العدو على فلسطين بعدها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1560","text":"لو نهيت الأولى لما كانت الثانية.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1561","text":"لو أُطفئ الشَّرار، لما احترق من في الديار.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1562","text":"لو أُقيم على الظالم حدّه يوم بَغى، ما تجبّر حتى طغى، ولكف غيره من الورى.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1563","text":"لو وُئدت الفتنة في مهدها، ما استحكمت في عهدها.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1564","text":"كل ما تشتهي، والبس ما يعجب الناس.","kind":"mathal","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1565","text":"يراعى في اللباس: الشرع - المناخ - العرف.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1566","text":"القيادة لا تستقيم بالقوة وحدها، بل لا بد أن تؤازرها الحكمة، ويعضدها العدل، وتزينها السياسة الرشيدة.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1567","text":"وإذا تعارضت العدالة والصداقة، فقدم العدالة، وحاول أن تحفظ الصداقة فلا تخسرها.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1568","text":"وإذا تزاحمت الحزبية ومصلحة الأمة، فدع الحزبية وراء ظهرك، وامضِ بمصلحة الأمة، فهي الأَولى والأجدر.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1569","text":"لكل جديد لذة، ولكل قديم حرمة. هذا في الناس.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1570","text":"لكل جديد لذة، ولكل قديم زتة. هذا في الأجهزة والأثاث.","kind":"hikma","topic":"الحياة والزمن","note":"زتة: رمي وطرح بالعامية الكويتية","source":"شذرات (ملف وورد)"},{"id":"m1571","text":"الأمة العربية والإسلامية ليسوا على قلب رجل واحد، لو كانوا كذلك لهابتهم الأمم، ولو من غير حرب ولا سلاح، لخوفهم على مصالحهم ومنافعهم.","kind":"hikma","topic":"السياسة والقيادة","note":"جاءت تعليقًا على حديث التحريش بين المصلين","source":"شذرات (ملف وورد)"},{"id":"m1572","text":"حب الدنيا فطرة، وحب الآخرة إيمان، ولولا حب الدنيا لخربت الدنيا ولم تعمر، وحب الدنيا لا يلحقه ذم ولا إنكار، لكن إيثار الدنيا على الآخرة هو المنهي عنه والمذموم.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1573","text":"المال يُهلكه الإسراف، والتباهي بالمظاهر، ويُنميه الاقتصاد والاقتصار على الحاجات، فدعوا المظاهر الخدَّاعة، وعُودوا للبَساطة والقناعة، فالعاقل من ملك حاجاته، لا من ملكته الكمالياتُ والمباهاةُ.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1574","text":"لا تجعلوا جُلَّ همّكم تتبّع أخبار الناس: ماذا قالوا، وماذا فعلوا، وماذا لو فعلوا، ولا تنشغلوا بالأخبار المحلية والعربية والعالمية، ثم تُعرضوا عن ذكر الله تعالى؛ فالذِّكر روحُ العبادات وغايتُها، وما شُرعت العبادات إلا لإقامته، وهو الباقي في الجنة دون سائر الطاعات. وهو عبادة الملائكة الأطهار وحملة العرش الكبار، عبادةٌ لا يحدّها زمان، ولا يقيدها مكان، ولا تحتاج إلى هيئة مخصوصة، بل يؤديها العبد في كل أحواله وتقلباته. وهو البلسم الشافي للقلوب من همومها وغمومها، والدَّواء الناجع لأدواء النفوس وأمراض الأرواح، وبه تطمئن القلوب، وتسكن النفوس، ويعظم الرجاء، فهو خير دواء لكل داء، وسلاح أمضى على شياطين الإنس والجن الأشقياء.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1575","text":"الكتاب المفيد غذاءٌ للعقل، ودواءٌ للجهل، والقراءة عمرٌ ثانٍ يُضاف إلى العمر، بها تنفتح الآفاق، وتسمو المدارك، ويصفو الفكر، ويستنير البصر والبصيرة. هي سلوى للنفس، وأنسٌ للروح، وفرارٌ من رتابة الأيام إلى بساتين العلم ومفاهيم المعرفة.","kind":"hikma","topic":"العلم والثقافة","source":"شذرات (ملف وورد)"},{"id":"m1576","text":"الموت خاتمة دارٍ فانية، دارِ ابتلاءٍ وامتحان، ينجو فيها من آمن وعمل صالحًا، ويهلك فيها من كفر وأعرض. وهي في الوقت نفسه فاتحة دارٍ باقية، دارِ جزاءٍ وعدل وفضل، يُكرم الله فيها المتقين بالجنة والرضوان، ويُذلّ فيها الجاحدين بالهوان والخزي والنيران.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1577","text":"رُبَّ ضارةٍ نافعة، ورُبَّ حسنةٍ لمنزلتك رافعة، تُقَدِّمها فتكون لك شافعة، فلا تيأسوا من رحمة الله، ولا تقنطوا من عفوه ورضاه، ففرجُه قريب، وتدبيرُه عجيب، وهو السميعُ المجيب.","kind":"hikma","topic":"الصبر والشدائد","source":"شذرات (ملف وورد)"},{"id":"m1578","text":"يا بُنيّ، اعلم أنّ لكلِّ عالِمٍ زلّة، ولكلِّ حكيمٍ هفوة، ولكلِّ بصيرٍ غفوة، ومن ادّعى العصمة فقد أوقع نفسَه في أعظم سقطة. والخطأ طبعُ البشر، والصواب هبةُ الله خالق البشر، والرجوع إلى الحق فضيلة، والتمادي في الباطل رذيلة. ومن لم يعتبر بعثراته أعاد كرّاته وعَبَراته، فإنّ الصواب ثمرة التجربة، والتجربة طريق الصواب، ومن سار على الطريق بلغ الهدف على التحقيق.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1579","text":"لولا السلبيات ما أدركنا قيمة الإيجابيات، وبضدها تتميز الأشياء: لولا المرض ما عرفنا قيمة الصحة. لولا الخوف ما عرفنا قيمة الأمن. لولا الظلم ما عرفنا قيمة العدل. لولا الجهل ما عرفنا قيمة العلم. لولا الفقر ما عرفنا قيمة الغنى. لولا القسوة ما عرفنا قيمة الرحمة. لولا الشتات ما عرفنا قيمة الوحدة. وبضدها تتميز الأشياء.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1580","text":"إذا أراد اللهُ بعبدِه خيرًا، فتح له أبوابَ طاعتِه، وصرف عنه شَرَّ نفسِه وهواه، وغرس في قلبه محبّةَ الإيمان، وهيّأه لطاعةِ الرحمن، ووفّقه لعملِ الصالحات، وبذلِ الصدقات، وإطعامِ الجياع والفقراء، ورعايةِ الأيتام والمساكين والضعفاء، وألهمه التمسّك بالدين، والعطف على المحتاجين والمكروبين، لا يطلب جزاءً ولا شكورًا، إنما ابتغاءَ وجهِ ربِّ العالمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1581","text":"التفكير خارج الصندوق، يفتح مغاليق العقول، ويكشف حقائق المستور، ويجلي المعارف المخبوءة، ويوسّع المدارك الضيّقة، ويقرّب الغايات البعيدة، ويضم الصغائر المبعثرة، ويجمع متناثرها، ويصوغ من الفكرة اليتيمة كنوزًا ثمينة، تبدعها العقول المستنيرة.","kind":"hikma","topic":"النجاح والإبداع","source":"شذرات (ملف وورد)"},{"id":"m1582","text":"الأخلاق تاجُ المرء، بها يعلو مقامه، وبدونها يسقط احترامه، هي جواز المرور إلى القلوب، وميزان التفاضل بين الشعوب، فالأخلاق ترفع الضعيف، وتُسقط القويّ إن حاد عن الطريق، فهي ميراث الأنبياء عليهم السلام، وزينة العقلاء، ورأس مال الحكماء، من تزين بها أكرمه الخالق، وأحبّه واحترمه الخلق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1583","text":"فالحكمةُ أن يبدأَ بالأخفِّ قبلَ الأشدِّ، وباللينِ قبلَ الغلظة، وبالنصحِ قبلَ العتابِ، فذلك أدعى للقبولِ، وأليقُ بكرامةِ المسؤوليةِ التي حمّله اللهُ إياها.","kind":"hikma","topic":"الحياة الزوجية","note":"في سياق وعظ الرجل لأهله","source":"شذرات (ملف وورد)"},{"id":"m1584","text":"الأم: حاضنةٌ تُدفئ، ومرضعةٌ تُروِي، ومربيةٌ تُهذِّب، ومعلِّمةٌ تُؤدِّب، ومدرسةٌ تُخرِّج الأجيال، ومُلهمةٌ تُوقِد العقول والآمال، هي نبعُ الحنان، ومصدرُ الأمان، وسرُّ الإيمان، وصانعةُ الإنسان، إن نظرتَ إليها أبصرتَ الجنةَ بين عينيها، وإن قبلتَ يدَها مسَّت أناملك بركةَ السماء، فسلامٌ على قلبٍ وسِعَ من حوله حبًّا وحنانًا وأمنا وسلاما.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1585","text":"فالتنويع حياةٌ للنفس، وتجديدٌ للعقل، وطردٌ للملل، وجلبٌ للنشاط. ومن أدرك سرّ التنويع، فقد ملك مفاتيح الجمال والإبداع.","kind":"hikma","topic":"النجاح والإبداع","note":"من خاطرة عن التنويع في مجموعات الواتساب","source":"شذرات (ملف وورد)"},{"id":"m1586","text":"الأمومة حنان وتضحية وصبر، تحفظ الحياة وتغرس الفضيلة، هي سِرُّ الوجود، ومصنع الخلود، بدعائها تُفتح السدود، ويُشرع الباب الموصود، ويُحْيَى الأمل المفقود، تبذل لأبنائها الكبير والمولود، وتُعطي بلا حساب ولا حدود، ولا تنتظر جزاءً ولا مردود، فبرها يهدي إلى جنات النعيم والخلود.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1587","text":"فعلى الرجل أن يكون لطيفا ودودا معها، ويقدر أُنوثتها ورقتها وعاطفتها، فهي ريحانة وليست قُهرمانة.","kind":"hikma","topic":"الحياة الزوجية","note":"القهرمانة: وكيل الملك أو رئيس التجار","source":"شذرات (ملف وورد)"},{"id":"m1588","text":"الشعب المثقف الواعي، يعصم الحكومة من ارتكاب الخطأ، لأنه يراقبها وينتقدها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1589","text":"الصمت سلاح الحكيم ضد السفيه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1590","text":"تعاليم الدين والأخلاق يعصمان المجتمع من الانزلاق.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1591","text":"جميلٌ أن نختلفَ بأدب، ونعتذرَ باعتراف، ونعاتبَ برفق، ونلتقي بمودّة، ونفترقَ بسلام، ونجتمعَ ببشاشة، وننصحَ بلين، ونُنكرَ بلطف، ونغضبَ بحِلم، ونطلبَ بتواضع، ونردَّ بحكمة، ونُجيبَ بتؤدة، ونستأذنَ بحياء، ونُعاتبَ بحنان، ونحاورَ بهدوء، ونأمرَ برفق، ونُكرمَ بصمت، ونُعبّرَ ببصيرة.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1592","text":"التعاليم السماوية منسجمةٌ مع الفطرة الإنسانية، لاتحاد المصدر الإلهي، وسلامة النهج من الزلل والقصور. فإذا جرى تطبيق التعاليم السماوية في الأفراد والمجتمعات، استقام الميزان واعتدل البنيان. والأب مسؤولٌ عن إقامتها في أهل بيته، كما أن وليَّ الأمر مؤتمنٌ على تطبيقها في رعيته.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1593","text":"ربما بثَّ الآباء في آذان الأبناء قولًا مشحونًا بالحكمة والضياء، ونثروا عليهم من النصح ما لو عقلوه لنجوا من الشقاء، لكنّهم لم يدركوا معانيه إلا بعد أن مسّهم البلاء، فيا أيها الآباء، اعذروا أبناءكم، فبعض دروس الحياة لا تُقرأ في الكتب، ولا تُفهم بالعقل المجرد، بل تُتلى على صفحات التجارب، ويُشرح معناها بمداد العناء.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1594","text":"تركُ المهارات يُضعف القدرات. فداومْ على ما تُتقن، وجدِّد مهاراتك، فإنَّ القدرة تُولد من الممارسة، وتموت بالإهمال.","kind":"hikma","topic":"النجاح والإبداع","note":"خلاصة قصة (العصفور الذي نسي الطيران)؛ له صيغة أخرى","source":"شذرات (ملف وورد)"},{"id":"m1595","text":"بالحواسّ يدرك العقل ما حوله، وباللسان يُفصح عمّا وعاه. فحركةُ الحواسّ من الخارج إلى الداخل، وحركةُ اللسان من الداخل إلى الخارج؛ تلك تجلبُ المعنى، وهذا يُخرجهُ إلى الوجود.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1596","text":"حركة الحب عند الرجل من الداخل إلى الخارج، وحركته عند المرأة من الخارج إلى الداخل، فالرجل يمنح الحب، والمرأة تتلقاه.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1597","text":"المرأة تُفضِّل الحب المعلن على الحب المكنون، فهي لا تكتفي بالإحساس، بل تريد اللمسة واللفظة والنظرة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1598","text":"والنجاح في الحياة الزوجية أشبه بـ البندول، لا بد أن يُسمِعها كلَّ أربع ساعات كلمةً أو يُريها تصرفًا يحمل في طيّاته نبض الحب ودفء المودة.","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1599","text":"مفاتيح أبواب الرزق: ١- سؤالُ الله تعالى ودعاؤه بإلحاح. ٢- الأخذُ بالأسباب مع صدق التوكل. ٣- كثرةُ الاستغفار، فهو يمحو الذنوب ويجلب الأرزاق من علام الغيوب. ٤- صلةُ الأرحام، فإنها سبب في بسط الرزق وطول العمر. ٥- الإنفاقُ في وجوه الخير، فالعطاء باب يجلب العطاء. ٦- البعدُ عن المعاصي، فالمعصية تُغلق أبواب البركة. ٧- أداءُ الأمانة، والصدقُ في المعاملة. ٨- برُّ الوالدين، ودعاؤهما من مفاتيح الرزق. ٩- التوكلُ الصادق مع الرضا بالمقسوم. ١٠- السعي في أول النهار ( اللهم بارك لأُمتي في بكورها ) ١١- الأمانة غنى، لأن من اشتهر بالأمانة، كثر زبائنه، وصاروا يروجون له.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1600","text":"تداركُ تقصير الصمت أيسر من تقصير النطق.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1601","text":"حفظ ما في يديك أولى من طلب ما في يَدَيْ غيرك.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1602","text":"مرارة الحرمان خير من ذِلة الطلب.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1604","text":"صدرُك أحفظ لسِرِّك، فلا تُفْشِ سِرَّك لغيرك.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1605","text":"من أكثر أهْجَرَ، ومن تفكر أبصر.","kind":"hikma","topic":"الكلام والصمت","note":"أهجر: هذى","source":"شذرات (ملف وورد)"},{"id":"m1606","text":"صاحب أهل الخير تكن منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1607","text":"اترك الشرَّ يتركك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1608","text":"اترك اهل الشرَّ فلا تكن منهم.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1609","text":"بئس الطعام الحرام، فهو بوابة للنار.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1610","text":"العقل حفظ التجارب.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1611","text":"التاجر مُخاطر، والمتاجرة مُخاطرة.","kind":"hikma","topic":"المال والاقتصاد","source":"شذرات (ملف وورد)"},{"id":"m1612","text":"من يأتي الحكمَ وحده يَثْلُج.","kind":"mathal","topic":"العقل والحكمة","note":"أثلج الأمرُ صدرَه: أسعده وأفرحه","source":"شذرات (ملف وورد)"},{"id":"m1613","text":"إذا خلطت بين الإحسان والإساءة، فاحرص على أن يكون الإحسان آخرا، وأكثر من الإساءة كما وكيفا.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1614","text":"ذَبْحُ الرجلِ ذكر مناقبه ومدحه وتزكيته في وجهه.","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1615","text":"أبلغ الجواب ما كان حاضرا، مع ابراز المعنى وإيجاز اللفظ، وبلوغ الهدف، فيكون حسما للمعارضة والمجادلة","kind":"hikma","topic":"الكلام والصمت","source":"شذرات (ملف وورد)"},{"id":"m1616","text":"من ظن بك خيرا فصدق ظنه أو بعضه، ولا تُقنطه من جودك.","kind":"hikma","topic":"الأخلاق والآداب","source":"شذرات (ملف وورد)"},{"id":"m1617","text":"لا يكن أهل بيتك أشقى الناس بك، فتكن لئما.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1618","text":"العاقل يتعظ بالآداب، والبهائم لا تتعظ إلا بالضرب على الإيهاب.","kind":"hikma","topic":"العقل والحكمة","note":"الإيهاب: الجلد","source":"شذرات (ملف وورد)"},{"id":"m1619","text":"الهوى شريك العمى، فلا يميز بين الخير والشر.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1620","text":"ليس كل من رمى أصاب، وليس كل من قال صدق. وليس كل من أحب نال.","kind":"hikma","topic":"العقل والحكمة","source":"شذرات (ملف وورد)"},{"id":"m1621","text":"اشتكى استاذ جامعي إلى مدير الجامعة: بأنه رأي حمارا يدخل من باب الجامعة، فقال المدير: دخول الحمار في الجامعة لا يُسبب مشكلة، لكن خروج الحمار من الجامعة هو المشكلة بعينها.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1622","text":"الدجاجُ المعاصرُ صناعيٌّ أكثرُ منه طبيعيّ، شأنُهُ شأنُ كثيرٍ من المأكولاتِ اليوم، وهي ظاهرةٌ مؤسفةٌ تُلقي بظلالِها السلبيةِ على صحّةِ الإنسان: النفسية والبدنية.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"},{"id":"m1623","text":"قال رجلٌ لزوجته: خلقكنَّ اللهُ جميلات، لكنكنَّ ناقصاتِ عقل. فابتسمتْ وقالت: خلقنا اللهُ جميلاتٍ لتميلوا إلينا، وناقصاتِ عقلٍ لنميلَ إليكم، فتكتمِل الأُلفة والمحبّةُ بين الطرفين.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1624","text":"( 14 ) شيء كثيرها كثير وقليلها كثير النار والمرض والعدو والدَّين والملح والفلفل والسم والشرك والسكر والدواء والإهانة والعقوق وغدر الصديق والبوز على الريق.","kind":"hikma","topic":"الحياة والزمن","source":"شذرات (ملف وورد)"},{"id":"m1625","text":"المشقة في تنظيف البيت ليست إلا دليلاً على نعم الله التي تحيط بنا. الأواني المتسخة تعني أننا وجدنا ما نأكله، وغرفة المعيشة التي تحتاج كنسًا تدل على اجتماعنا حول مائدة واحدة. وغرف الأطفال التي نرتبها تشهد على ضحكاتهم ومرحهم، والمطبخ الذي تفوح منه رائحة الطعام يثبت أننا نطعم أبناءنا. حتى الأطباق في الحوض تحكي قصة أطفال ناموا شبعى، وغرفة الضيوف التي رتبناها تومئ إلى لقاء قريب بأحبابنا. فما نعدّه تعبًا، هو في الحقيقة نعمة تستحق الشكر، والبيت الذي لا يحتاج ترتيبًا وجهدا، قد فقد بعض الضروريات والحاجيات، وشيئًا من الأنس والفرح والمسرات.","kind":"hikma","topic":"التربية والأسرة","source":"شذرات (ملف وورد)"},{"id":"m1626","text":"تهادوا بالورود والريحان، فالوردُ يشرحُ الصدور بشذا يفوقُ البخور وينشرُ في النفسِ سرورًا ويكسو الأيّامَ حُبورًا ويُحيي القلبَ نورًا ويطردُ الهمَّ دُحورًا ويبعثُ في الروحِ حضورًا ويجعلُ العيشَ سرورًا","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1627","text":"دخل الزوج على زوجته وهو في غاية الحزن والكآبة، فقالت له: سلامات! خير إن شاء الله، قال لها بصوت حزين: ضاع الحمار، فقالت له: لا تحزن، فوالله لدخلتك علينا سالما أحسن من ألف حمار.","kind":"tarfa","source":"شذرات (ملف وورد)"},{"id":"m1628","text":"احذر دعوةَ المظلوم، فإنها تُرفع بين السماء والأرض بلا حجاب.","kind":"hikma","topic":"الإيمان والعبادة","note":"في معنى حديث نبوي","source":"شذرات (ملف وورد)"},{"id":"m1629","text":"لن تستطيع أن تخدع جميع الناس في جميع الأوقات.","kind":"hikma","topic":"العلاقات والناس","note":"قول مشهور يُنسب إلى أبراهام لينكولن","source":"شذرات (ملف وورد)"},{"id":"m1630","text":"قاموس الحب والإعجاب للشباب المقبلين على الزواج: وجهك منور، عيونك ذباحة، شعرك يجنن، ريحتك حلوة، جسمك يعجبني، مشيتك تفتن، صوتك موسيقى، ابتسامتك حلوة، خدودك تفاح، نظرتك تسعدني، أسلوبك رقيق، كلامك عسل، ضحكتك تجنن، عقلك كبير، قلبك طيب، رقتك حنان، أخلاقك راقية، أحبك من قلبي، ما أستغني عنك، وجودك راحة لي، أنتِ حياتي، جمالك مستحيل، يا جميلة، تسلمين يا غالية، طبخك لذيذ، لمساتك رقيقة، ترتيبك ذوق، ذكية ونبيهة، الله يحفظك، أنتِ بركة بيتنا، ما قصرتي، خَسَّيْتِ، يا بعد قلبي، يا روحي، يا عمري، يا أجمل هدية، يا ألطف إنسانة، يا عيوني أنتِ","kind":"ghazal","source":"شذرات (ملف وورد)"},{"id":"m1631","text":"سبحان من جعلك تُبصر بشحم، وتسمع بعظم، وتتكلم بلحم، وتنبض بعضلة، وتفكر بمضغة، وتتحرك بعصب، وتُرزق من غير حولٍ ولا طول، وتُحاط بنِعَمٍ لا تُعدّ ولا تُحصى، وتُحفظ بعينٍ لا تنام، وتُستر بسترٍ لا يُرام، وتُمهل على زلل، وتُوفّى على عمل، وتُسقى بماءٍ عذب، وتُغذى برزقٍ عجب، وتُكفى الشرّ قبل أن يقع، وتُرحم قبل أن تضرع، يا أكرم الأكرمين.","kind":"hikma","topic":"الإيمان والعبادة","source":"شذرات (ملف وورد)"},{"id":"m1632","text":"فلسطين اليوم تدفع ثمن الأمس؛ يومَ تقاعست الجيوش العربية والإسلامية والجامعة العربية عن نصرة المستضعفين، في أفغانستان والبوسنة وفي بقاع الأرض، بجميع أنواع النصر، فأصبح الطريق ممهّدًا لهذه الكارثة وغيرها.","kind":"hikma","topic":"السياسة والقيادة","source":"شذرات (ملف وورد)"},{"id":"m1633","text":"قُدراتُ الناسِ تَختلِفُ في الفَهمِ والاستِيعابِ للأُمورِ، ومِن فِقهِ العالِمِ أنْ يُحدِّثَ كلَّ فَرْدٍ وكلَّ جَماعةٍ بما تَستوعِبُه عقُولُهم ولا تَنفِرُ منه أفهامهم.","kind":"hikma","topic":"الكلام والصمت","note":"جاءت شرحًا لأثر علي رضي الله عنه: حدثوا الناس بما يعرفون، وقد تكون منقولة من شرح","source":"شذرات (ملف وورد)"},{"id":"m1634","text":"بعض صور المقاطع الشنيعة في التواصل الاجتماعي ما ودك أن تُرسل وتظهر، لأنها تُحزن نفس الإنسان، وتجلب الأحزان، وتُؤلم الجَنان، بمجرد أن تُبصرها العينان.","kind":"hikma","topic":"العلاقات والناس","source":"شذرات (ملف وورد)"},{"id":"m1635","text":"مهارة التذكر: استخدم التكرار الذهني الواعي: حين تضع المفتاح في مكان ما، قُل لنفسك بتركيزٍ وسكون: “وضعت المفتاح على الطاولة”مثلا، فالكلمة المسموعة تُثبّت الفعل في الذاكرة كما يُثبّت الختم على الورقة. استعن بحاسةٍ أخرى تُعين الذاكرة على التوثيق: المس الشيء أو تأمّله بعينيك لحظة وضعه، فالحواسّ إذا تعاونت تآزرت، وإذا تآزرت أثمرت، فيرسخ المشهد في الذهن رسوخ النقش في الحجر.","kind":"hikma","topic":"الصحة والنفس","source":"شذرات (ملف وورد)"}];